// Phase 2 — React project generation contract + parser.
//
// Sonnet emits a whole Vite/React/Tailwind PROJECT as a series of file blocks,
// each introduced by a line `===FILE: <relative/path>===`. This delimiter format
// avoids JSON-escaping code (quotes, backslashes, newlines) which is fragile for
// large multi-file output. The parser turns that text into { "<path>": "<src>" }
// ready to POST to the build-service.
//
// The build-service only allows writes to index.html / vite,tailwind,postcss
// configs / src/**, and the image deps are pre-baked, so the model MUST stay
// inside that shape and use ONLY the pinned packages.

export function parseGeneratedFiles(text) {
  const files = {};
  const s = String(text || "");
  // Split on the FILE markers (kept as capture groups → [pre, path, body, path, body, ...]).
  const parts = s.split(/^===FILE:\s*(.+?)\s*===[ \t]*$/gm);
  for (let i = 1; i < parts.length; i += 2) {
    const rawPath = (parts[i] || "").trim();
    let body = parts[i + 1] || "";
    // Trim one leading newline and trailing whitespace; strip an accidental
    // ```lang fence the model may wrap a block in.
    body = body.replace(/^\r?\n/, "").replace(/\s+$/, "");
    body = body.replace(/^```[a-zA-Z]*\r?\n/, "").replace(/\r?\n```$/, "");
    if (rawPath) files[rawPath] = body;
  }
  return files;
}

// The allowed dependency set (must match builder/package.json). The generator is
// told these are the ONLY importable packages.
export const REACT_DEPS = [
  "react", "react-dom", "react-router-dom", "lucide-react", "clsx", "tailwind-merge", "@tanstack/react-query",
  // Radix backs five kit components (Modal, Dropdown, Popover, Tooltip, MultiSelect). Pages never import it
  // directly — they use our components — but it is a real dependency of the bundle.
  "@radix-ui/react-dialog", "@radix-ui/react-dropdown-menu", "@radix-ui/react-popover", "@radix-ui/react-tooltip",
];

// Backend protocol — shared by build + revise. Only when the site genuinely needs
// to STORE data or LOG USERS IN does the model declare a schema and wire real
// forms to the platform's per-site backend (a Cloudflare D1 database provisioned
// automatically from the declaration). Informational sites emit nothing here.
export const BACKEND_RULES =
  "BACKEND (ONLY when the site must save data or sign users in — a form that persists, a login, a dashboard, a store; a purely informational site emits NOTHING here). " +
  "**CRITICAL — SCHEMA IS MANDATORY: if ANY file calls `${API}/auth/*` or `${API}/rows/<table>`, you MUST emit a file `===FILE: isibi.schema.json===` declaring every table used, or the live app 404s 'this site has no backend yet'.** Body: `{\"tables\":[{\"name\":\"<snake>\",\"access\":\"collect|display|user|feed|admin\",\"columns\":[{\"name\":\"<snake>\",\"type\":\"text|integer|real|boolean|json\",\"ref\"?:\"<table>\",\"required\"?:true,\"max\"?:N,\"min\"?:N,\"format\"?:\"email|url|number\",\"default\"?:<value>,\"enum\"?:[\"a\",\"b\"],\"pattern\"?:\"<regex>\"}]}]}`. Column rules are ENFORCED server-side on writes (a bad value → 400 with a message): `required`; `max`/`min` = length for text, value bounds for numbers; `default` = server default when omitted; `enum` = value must be one of the set; `pattern` = must match the regex; `format` = email/url/number; A TABLE-level `\"publicView\":{\"columns\":[\"date\",\"time\"],\"where\":[\"status:eq:confirmed\"]}` publishes a READ-ONLY, PII-filtered projection of an owner-scoped table at `GET /rows/<t>/public`, readable by ANYONE including a signed-out visitor — use it when a visitor must see which slots/seats are taken WITHOUT seeing who took them (widening the table access would expose the booker). Only the listed columns are ever returned; `id` and `owner_id` are rejected. Read it from a page with `usePublicRows(<table>, { where: date:eq:2026-08-04 })`. `immutable`:true LOCKS a field (settable on insert, but any later edit that includes it → 400 — use for an email, a created price, an order number); `default` also accepts computed tokens `\"@now\"` (current datetime), `\"@today\"` (date), `\"@uuid\"` (a random id) that the DB fills per-insert when you omit the field. CROSS-FIELD rules go in a TABLE-level `\"checks\":[[\"end_at\",\"gte\",\"start_at\"],[\"capacity\",\"gt\",\"reserved\"]]` (ops gt/gte/lt/lte/eq/ne, numeric when both are numbers else string/date) — enforced on writes when both fields are present (always on a full insert; on a partial update only if it carries both). Derived READ-ONLY columns go in a TABLE-level `\"computed\":{\"full_name\":[\"first_name\",\" \",\"last_name\"]}` — on read each token that names a column (incl. `id`/`created_at`) becomes that row's value, anything else is a literal, so you don't store a redundant `full_name`. To validate the inner shape of a `json` column, add a TABLE-level `\"jsonShapes\":{\"payload\":{\"type\":\"string\",\"count\":\"number\",\"tags\":\"array\"}}` — each listed inner field is REQUIRED and type-checked (string|number|boolean|array|object) on write, so a structured blob is validated, not just stored (a bad field → 400 naming it). For NUMERIC derived values use a TABLE-level `\"formulas\":{\"line_total\":[\"quantity\",\"*\",\"unit_price\"],\"net\":[\"subtotal\",\"-\",\"discount\"]}` — tokens are numeric columns or literal numbers joined by operators + - * / (correct precedence, * and / bind first); read-only per row, non-numeric operand or divide-by-zero → null; use it for money math (line totals, tax, margins) so the browser never recomputes it. MULTI-CURRENCY (store money in native currencies but report in ONE) — add a TABLE-level `\"currency\":{\"amount\":\"amount\",\"code\":\"currency\",\"base\":\"USD\",\"rates\":{\"EUR\":1.08,\"GBP\":1.27}}`: `amount` is the money column, `code` is the per-row ISO-currency column, `base` is what you report in, `rates` maps each other currency to base units per 1 unit (base is always 1). On READ each row gains `<amount>_base` (= amount × rate, or `as` to rename it), null when the row's currency has no rate. Crucially `stats` can `sum=/avg=` that base field — `?group=region&sum=amount_base` rolls a cross-currency pipeline up into ONE base-currency total in SQL (a EUR deal and a GBP deal add correctly), so dashboards never mix currencies. AUTO-NUMBERING (human-readable record numbers — invoice/order/quote/ticket/case IDs like INV-01000, LEAD-0042, PO/2001) — add a TABLE-level `\"sequence\":{\"field\":\"number\",\"prefix\":\"INV-\",\"pad\":5,\"start\":1000}` (`prefix`/`pad`/`start` optional — default no prefix, no padding, start 1). Every new row is stamped with the next number in sequence (atomic per-table counter → gap-free, no collisions even under load). The field is AUTHORITATIVE: it's platform-set, never app-writable, so a client can't spoof or reuse a number (a value sent for it is ignored), and it can't be changed by a later edit. It's queryable + sortable like any column (`?where=number:eq:INV-01001`, `?sort=-number`). Use it for any record that needs a stable customer-facing ID — don't try to compute one in the browser (that races). Declare these instead of validating only in the browser. Every table auto-gets `id`+`created_at`; `user`/`feed` also auto-get `owner_id` — NEVER declare those yourself. **ENCODE THE BRIEF'S RULES AS SCHEMA KEYS — the database is the only real enforcement (front-end checks race and are trivially bypassed), so a rule stated in words MUST become a schema constraint, not just a column:** A slot/seat/resource that only ONE record may hold at a time (a 10:00 appointment, seat 4B, a room on a date) → TABLE-level `unique:[{columns:[\"date\",\"time\"], where:\"status:eq:confirmed\"}]` — a PARTIAL unique index, so the database refuses a second booking for that slot (409 `{code:'duplicate'}`) and a CANCELLED row stops holding it. Plain `unique:[[\"date\",\"time\"]]` without the `where` would keep the slot locked forever after a cancellation. Greying out taken slots in the UI is a courtesy; this is the only thing that actually stops two people booking the same time. 'one <X> per member' / 'per member per <Y>' / 'can only <do> once' → TABLE-level `oncePerUser:[\"<y>\"]` (use `[]` for once-per-member overall); 'rated 1-5' / 'score out of 10' / 'up to N chars' → column `min`/`max`; a record that BELONGS TO or is shown grouped under / filtered by a parent (comments on a post, RSVPs for an event, line-items of an order, a task in a project) → a `ref` column pointing at that parent table; a unique handle/username/slug/promo-code → `unique` (or `uniqueCI` for names/handles); a fixed choice set (status, category, role, priority) → `enum`; a must-fill field → `required`. If the brief says it, the schema carries it. STATE MACHINE / STAGE-GATING — when a status/stage field may only move along a set path (opportunity stage, order or ticket status, an approval flow), add a TABLE-level `\"transitions\":{\"<col>\":{\"<from>\":[\"<to>\",…]}}` (use `\"*\"` as a from-key to allow a move from ANY current value — its targets are ADDED to every state's own list, so `\"*\":[\"cancelled\"]` means 'cancellable from anywhere'). A PATCH that moves the column to a step not declared from its current value is refused with HTTP **409** `{code:'transition', from, to, allowed}` — catch it and show the valid next steps. The DB enforces the flow, so no invalid stage jump slips through; a PATCH that doesn't touch the column is unaffected. " +
  "ACCESS MODES (pick the right one): `collect` = visitors submit, only owner reads (contact/orders/RSVP); `display` = everyone reads, owner-managed content — starts EMPTY with no in-app editor, so hardcode a small fixed catalog instead; `user` = each login sees only their OWN private rows (dashboard, to-do, saved items); `feed` = everyone reads, a logged-in visitor posts + edits only their own (board, comments, reviews); `admin` = everyone reads, only an app admin writes — an in-app CMS WITH an add/edit UI (blog/catalog/events). Submit-AND-show = `feed` (not collect, which hides; not display, which blocks posting). " +
  "UNIQUENESS (stop duplicates race-free — 'one review per member per product', 'one RSVP per event per member', a unique slug/code): add a TABLE-level key next to `columns`. `\"oncePerUser\":[\"product_id\"]` on a `user`/`feed` table = at most ONE row per member per that value (owner_id is added automatically). `\"unique\":[\"code\"]` = globally unique; a composite like `\"unique\":[\"event_id\",\"seat\"]` = that pair unique. Enforced by the database, so a duplicate POST returns HTTP **409** `{error,code:'duplicate'}` — catch it and show a friendly 'you've already done this' (don't treat 409 as a crash). Prefer this over checking-then-inserting in JS (that races). Add `\"uniqueCI\":[\"handle\"]` for CASE-INSENSITIVE uniqueness (so 'Alice' collides with 'alice' — usernames, emails); same 409 `code:'duplicate'`. Add `\"maxRows\":100` to CAP a table's size (scoped PER-MEMBER on user/feed, global otherwise) — the row over the cap is refused with HTTP 409 `{code:'limit'}` (free-tier limits, 'max 100 todos per user'). Add `\"rateLimit\":5` to cap each member at N WRITES PER MINUTE to a table (anti-spam, 'max 5 posts/min') — over the cap → HTTP 429, catch it and show 'slow down'. To tune the WHOLE app's data-API throughput add a TOP-LEVEL `\"rateLimits\":{\"read\":300,\"write\":60}` (requests per IP per minute — the defaults shown) as a sibling of `tables`; raise it for a busy app or lower it to harden a quiet one (over the cap → 429). " +
  "**API BASE — MANDATORY, GET THIS EXACTLY RIGHT or the whole app 404s: the live site is served at `/s/<slug>/`, so you MUST derive the slug from the URL and put it in EVERY backend call. Define it ONCE: `const API = '/api/db/' + (location.pathname.split('/')[2] || '');` and route EVERY call through it — `${API}/auth/signup`, `${API}/auth/login`, `${API}/auth/me`, `${API}/rows/<table>`, `${API}/rows/<table>/<id>`, etc. NEVER hardcode `/api/db/auth/…` or `/api/db/rows/…` and NEVER write `` `/api/db${x}` `` — those drop the slug and every request fails. If you use a fetch helper/hook, build the URL as `` `${API}${path}` `` (API already contains the slug); do NOT bake a slugless `/api/db` into the helper and expect callers to add it.** All responses are JSON `{ok,...}`; guard every fetch in try/catch with friendly error/success states. " +
  "DATA: `GET ${API}/rows/<table>` (list) · `POST` (create — body of ONLY declared columns) · `GET/PATCH/DELETE ${API}/rows/<table>/<id>`. `user`/`feed`/`admin` writes send header `Authorization: Bearer <token>`. BATCH: `POST {rows:[…]}` (≤100) → `{inserted}`. FILE UPLOAD (an image or PDF — avatar, listing photo, resume): read the file as a base64 data URL and `POST ${API}/upload {name, data}` → `{url}`, a PERMANENT public link (images PNG/JPG/WebP/GIF + PDF, ≤6MB); then SAVE that `url` into a row (e.g. a listing's `photo` column) so it isn't orphaned. Needs the site to be live. SERVER-SIDE RESIZE/CONVERT (shrink big phone photos + convert format on the way in, so you store a bounded thumbnail not a 6MB original): add a `resize` to the upload body — `{name,data,resize:{max:1200}}` bounds the longest side to 1200px keeping aspect (downscale only), `{w,h}` sets exact/one-side dims, and `format:'jpeg'|'webp'|'png'` (+ optional `quality` 40–100 for jpeg) re-encodes it (webp = smallest, jpeg = photos, png = keeps alpha). The returned `{url,type,size}` reflect the transformed file. Only PNG/JPG/WebP are transformed (GIF/PDF pass through). Use it for avatars/thumbnails to keep storage small. UPSERT (one-row-per-key: settings, a like toggle): `POST ${API}/rows/<t>?upsert=<col>` updates the row matching `<col>` (scoped to the user on user/feed tables) else inserts → `{ok,created}`. BULK (mark-all-read, delete-selected, archive-done): `PATCH ${API}/rows/<t>?where=…` updates every matching row with the body → `{updated:N}`; `DELETE ${API}/rows/<t>?where=…` deletes every matching row → `{deleted:N}`. A `where`/`q`/`tag` FILTER is REQUIRED (no unfiltered mass changes), it's capped at 1000 rows/call, and scoped like single writes (feed/user only YOUR rows, admin any). To delete a specific SET, use `?where=id:in:1,2,3`. " +
  "QUERY (always filter/paginate on the SERVER, never fetch-all-and-filter): list params `where=<col>:<op>:<val>` (repeatable, AND-ed; op `eq|ne|lt|lte|gt|gte|contains|startswith|endswith|in|nin|between|isnull|notnull` — `in`/`nin` take a comma list e.g. `where=status:in:draft,live`; `between` takes two bounds `where=price:between:20:100` (inclusive, for price bands / date windows); `isnull`/`notnull` ignore the value), `q=<text>` (multi-word, relevance-ranked — for a big text corpus, declare a TABLE-level `\"fts\":true` (or `[\"title\",\"body\"]`) and search with `?fts=<query>` instead: a real FULL-TEXT index (FTS5, bm25-ranked, prefix + AND terms), far faster and better-ranked than `q=`'s LIKE scan on large tables; to weight fields so title matches outrank body matches, add a TABLE-level `\"searchWeights\":{\"title\":5,\"body\":1}` — `q` then ranks by weighted matches in those columns). SORT: one column `sort=<col>&order=asc|desc`, OR multiple comma-separated with a per-column direction prefix `sort=-price,name` (`-`=desc, `+`/none uses `order`), OR `sort=random` for a shuffled/discover/featured surface (pair with a small `limit` to pick N random rows). PAGINATE two ways: `limit`(≤200)+`offset` (jump to any page; response carries `{total}`), OR keyset for endless 'load more' — pass `after=<lastRowId>` to get the next older page (stable + fast on big lists; use the id of the last row you got as the next `after`). STATS / REPORTS: `GET ${API}/rows/<t>/stats?sum=<col>&avg=&min=&max=&group=<col>` Add `&distinct=<col>` for a UNIQUE count (`distinct:{<col>:n}` — 'how many distinct customers'). → `{count, sum:{…}, groups:[{value,count,sum}]}` (respects where/q/tag; user tables scope to the caller). `group` accepts MULTIPLE comma-separated columns for a matrix/pivot report (up to 4 dimensions) — e.g. `?group=stage,owner_id&sum=amount&avg=amount` returns `{groupBy:[…], groups:[{stage, owner_id, count, sum:{amount}, avg:{amount}}]}` (one row per combination), so you get 'pipeline by stage AND by rep' in ONE request. CROSS-TABLE grouping — group by a column on a REFERENCED parent with a `<fkcol>.<parentcol>` token: e.g. on opportunities (each has `account_id` ref accounts) `?group=account_id.industry&sum=amount` returns pipeline value grouped by each opportunity's ACCOUNT's industry — a join you'd otherwise do client-side, in one request (`{group:'account_id.industry', groups:[{value:'software', count, sum:{amount}}]}`). The `where=`/owner-scope filter still applies to the child table first. TIME-SERIES grouping — group by a TRUNCATED timestamp with a `<datecol>:<granularity>` token (granularity year|month|week|day|hour): `?group=closed_at:month&sum=amount` returns one bucket per month ordered CHRONOLOGICALLY (`{group:'closed_at:month', groups:[{value:'2026-01', count, sum:{amount}}]}`) — a revenue-per-month / leads-per-week trend line in one request, no client-side date bucketing. Works on `created_at`/`updated_at` or any declared ISO-date column; combine with `where=` (e.g. won deals only). Add `&fill=1` to ZERO-FILL empty periods (a month/day/hour/year with no rows still appears with `count:0`) so a trend line is continuous with no gaps — filled buckets carry the same shape (0/null aggregates); works for year/month/day/hour (not week), capped at 2000 buckets. GROUPED-REPORT CONTROLS (apply to ANY grouped stats — plain, matrix, cross-table, or time): `groupSort=<count|sum:col|avg:col|min:col|max:col|value>` + `groupOrder=asc|desc` sorts the groups by an aggregate (default `count` desc) — a revenue leaderboard is `?group=rep&sum=amount&groupSort=sum:amount&groupOrder=desc`; `groupLimit=<n>` caps to the top-N (so add `&groupLimit=10` for 'top 10 accounts'); `having=<agg>:<op>:<n>` (repeatable, AND-ed; op gt/gte/lt/lte/eq/ne; agg = `count` or `<sum|avg|…>:col`) filters the GROUPS themselves — `?group=rep&sum=amount&having=sum:amount:gte:50000` returns only reps whose pipeline clears 50k (quota reports, big-account filters). HAVING needs a `group`; it's ignored on an ungrouped total. EXPRESSION AGGREGATES (aggregate an arithmetic expression, not just a column — a WEIGHTED pipeline forecast, a discounted total): `sum=<alias>:<expr>` where `<expr>` is `+ - * /` and parens over declared numeric columns and number literals — e.g. `?group=rep&sum=weighted:amount*probability/100` returns each rep's weighted pipeline `{sum:{weighted: …}}` summed IN SQL (a formula field is read-time and can't be SUMmed). Works for `sum/avg/min/max`, in every grouped or ungrouped stats path, and you can `groupSort=sum:<alias>` / `having=sum:<alias>:gt:N` by it. Note integer columns use integer math, so multiply BEFORE dividing (`amount*probability/100`, not `amount*(probability/100)`); URL-encode a literal `+` as `%2B`. Combine with `where=` to scope a report (e.g. this-quarter). Use this for dashboards/KPIs instead of pulling rows and aggregating in the browser.FACETS (filter sidebars — 'Red (12) · Blue (4)', category/brand/size counts): `GET ${API}/rows/<t>/facets?fields=<colA>,<colB>` → `{facets:{colA:[{value,count},…], colB:[…]}}` (each column's distinct values + how many rows have each, top 100 by count). It respects the CURRENTLY-applied `where`/`q`/`tag` too, so as the user ticks filters the remaining counts narrow (drill-down). Use it to build a checkbox filter panel with live counts in ONE request instead of counting client-side. HISTOGRAM (distribution of a NUMERIC column into ranges — price bands, score/age spread, 'orders in each $10 band'): `GET ${API}/rows/<t>/histogram?col=<numcol>&buckets=N` buckets the column into N equal-width ranges and counts rows per range → `{col, min, max, width, total, buckets:[{lo,hi,count}, …]}`. Bounds auto-compute from the data, or pin them with `&min=&max=` (values outside pinned bounds clamp into the edge buckets; `buckets` default 10, max 100). Respects the same where/q/tag/trash filters + read visibility as stats (a `user` table counts only the caller's own rows). Use it for a distribution bar chart; use `group=` stats when the column already holds discrete categories. COLUMN PROFILE / DESCRIBE ('what's in this table' — a data-quality / admin overview in ONE call): `GET ${API}/rows/<t>/profile` → `{total, columns:[{name, type, non_null, nulls, distinct, min, max, avg?, sum?}]}` — per-column completeness (nulls), cardinality (distinct), range (min/max), and for numeric columns avg+sum, computed over the visible rows in a single query. Same read visibility + trash filters as stats (a `user` table profiles only the caller's own rows; `collect` has none). Use it to render a table-overview / data-health panel or spot empty/low-cardinality columns, instead of firing a stats call per column. DRY-RUN VALIDATION (check a row against the table's rules WITHOUT saving — live 'is this valid?' feedback on a form, a check-before-submit step): `POST ${API}/rows/<t>/validate {<fields>}` → `{valid:true}` or `{valid:false, error:'<message>'}`, running the SAME server-side checks a real create would (required, enum, min/max, pattern, format, immutable, cross-field `checks`, `jsonShapes`) but touching nothing. Default checks a CREATE; add `?partial=1` to check an EDIT (absent required fields are fine, immutables still rejected). It does NOT check uniqueness/refs — use `/duplicates` for that. No login needed (no data touched). Use it to validate as the user types instead of duplicating every rule in the browser. DUPLICATE CHECK ('does this contact/lead already exist?' before a create): `GET ${API}/rows/<t>/duplicates?email=<v>[&phone=<v>]` → `{matches:[…], count, on:[…]}` — existing rows matching ANY of the supplied declared columns (case-insensitive, trimmed), so a create form can warn 'a contact with this email already exists' and offer to open it instead of making a dupe. Add `&exclude=<id>` when checking during an EDIT so the row doesn't flag itself. Same read visibility as the table (a `user` table checks only the caller's own/team rows; public-read tables check all; `collect` has none). Pair with `/merge` to fold a found duplicate together, or use column-level `uniqueCI` when you'd rather HARD-block the duplicate at write time. GLOBAL SEARCH (one search bar across the WHOLE app — type a name, get matching contacts AND deals AND tickets): `GET ${API}/search?q=<text>[&tables=a,b][&per=N]` runs the same free-text `q` match your list reads use, over EVERY readable table at once, and returns `{results:[{table, rows}], count}` grouped by table (per-table cap `per`, default 5). Per-table visibility is enforced exactly like a list read — public-read tables (display/feed/admin) search all rows, a `user` table only the signed-in caller's own (skipped when signed out), `collect` never; trashed rows are excluded and field-level security is applied. Send the caller's Bearer token so their private records are included. Use `tables=` to scope (e.g. just contacts+companies). This is the backend for a command-palette / global search box; for one table use the list read's `?q=` instead.NEARBY / GEO: on a table with coordinate columns declare `\"geo\":{\"lat\":\"latitude\",\"lng\":\"longitude\"}` (or just name them `lat`/`lng`), then `GET ${API}/rows/<t>/near?lat=<>&lng=<>&radius=<km>[&limit=<>]` returns rows within the radius, NEAREST FIRST, each with `row._distance_km` — for 'stores near me', map results, local listings. SLA / DEADLINES (response/resolution timers on tickets, cases, leads — 'respond within 4h', 'resolve within 2 days'): add a TABLE-level `\"sla\":{\"start\":\"opened_at\",\"mins\":\"4h\",\"done\":{\"field\":\"status\",\"values\":[\"resolved\",\"closed\"]}}` — the clock runs from the `start` date column (default `created_at`) for `mins` (a number of minutes or a duration like `30m`/`4h`/`2d`/`1w`); when the row's `done` status column holds a stop value the clock is MET. Every read then carries a `row._sla = {due_at, remaining_mins, overdue, done}` (no config to render an 'overdue' badge, sort by urgency, or color a countdown). The OVERDUE QUEUE is `GET ${API}/rows/<t>/overdue[?where=&limit=&offset=]` → rows past their deadline and not done, MOST-OVERDUE FIRST, each with `_sla`, computed in SQL so it filters/paginates server-side (respects the table's read visibility + your `where=`). Build a 'breaching SLA' worklist from it. ESCALATION — add an `\"escalate\"` block to the sla config: `\"sla\":{…,\"escalate\":{\"to\":\"<member id or email>\",\"field\":\"priority\",\"value\":\"urgent\"}}` — then `POST ${API}/rows/<t>/overdue/escalate` (ADMIN) applies that action to every overdue row not yet escalated (reassign `owner_id` to `to` and/or set `field`=`value`), returning `{escalated:<count>}`. It's IDEMPOTENT (rows already at the target are skipped, so re-running is safe) and does NOT resolve the rows (they stay overdue until their status reaches a `done` value). There's no built-in timer — call this endpoint from a scheduled function or an external cron to fire escalation automatically, or wire an 'Escalate overdue' admin button to it. `to` needs an owner column (a `user`/`feed` table); a field-only escalate works on any writable table." +
  "TAGS / LABELS (categorize any row and filter by it — post topics, product categories, task labels): `POST ${API}/rows/<t>/<id>/tags {tag}` adds a tag (same write scope as the row: feed/user your own row, admin any), `DELETE ${API}/rows/<t>/<id>/tags/<tag>` removes it, `GET ${API}/rows/<t>/<id>/tags` lists them. To SHOW tags on a feed add `?tags=1` and each row comes back with `row.tags` (array). To FILTER a list to one tag add `?tag=<name>` to the list read. Tags are short (letters/numbers/-/_), deduped per row. " +
  "RELATIONS: declare a fk column with `ref` (`{\"name\":\"post_id\",\"ref\":\"posts\"}`). `?expand=<fk>` attaches the parent as `row. A dotted token `expand=customer_id.company_id` DEEP-expands up the chain (order → customer → company) in one request.<fk minus _id>`; `?children=<child_table>` attaches an array of children under that name. Both batched (no N+1); can ONLY join a PUBLIC-READ table (display/feed/admin) — never leaks user/collect rows. Deleting a parent row AUTO-deletes its children (cascade) — you don't clean them up yourself. Add `\"enforceRefs\":true` to a TABLE to REJECT a write whose fk points at a non-existent parent (HTTP 400 `{code:'ref'}` — no orphan rows); a NULL fk stays allowed (optional link). Control what happens to children when the parent is deleted via a column-level `\"onDelete\"` on the fk: `\"cascade\"` (default — children deleted with the parent), `\"setNull\"` (children KEPT, their fk nulled — e.g. keep line items when a category is removed), or `\"restrict\"` (REFUSE the parent delete with 409 `{code:'restrict'}` while any child still points at it). THREADED / NESTED (replies-to-replies, a category tree, an org chart — a table that references ITSELF): give it a column with `ref` back to its OWN name (`{\"name\":\"parent_id\",\"ref\":\"comments\"}`), then `GET ${API}/rows/<t>/tree` returns the rows NESTED — each carries a `replies` array of its children (recursive); `?root=<id>` returns one subtree; honors `?authors=1`/`?reactions=1`. MANY-TO-MANY LINKS (a bidirectional relationship between rows WITHOUT declaring a join table — tags↔posts, users↔projects, 'related items'): `POST ${API}/link {a,b}` (Bearer) links two rows where a/b are `<table>:<id>` (e.g. `post:1`, `tag:5`); `DELETE ${API}/link {a,b}` unlinks; `GET ${API}/links/<table>:<id>[?to=<table>]` → the rows linked to it `[{target,table,id}]`, queryable from EITHER side. Deduped + undirected. (If the link needs its OWN data — a role, a quantity — use a real join table with two `ref` columns instead.) " +
  "EDIT TIMESTAMPS: add `\"timestamps\":true` to a TABLE → every row auto-gets `updated_at` (set on create, bumped on every edit, returned on reads) with NO extra code — sort by it for 'recently updated' or show an 'edited' state. READ SHAPING (both optional, on any list/get): `?fields=a,b` returns ONLY those columns (plus `id`, always) to shrink big lists; `?count=<child_table>` attaches `row._counts.<child>` = how many children point at each row, so a feed shows '12 comments' WITHOUT fetching them (peer of `?children`, public-read children only). `?rollup=<child>:<agg>:<col>` (agg sum/avg/min/max/count; comma-separate several) rolls a child column UP onto each parent as `row._rollups.<child>.<agg>.<col>` — an order total (`line_items:sum:amount`), an average rating (`reviews:avg:rating`), a highest bid — again without fetching the children. " +
  "SOFT DELETE / TRASH (a recycle bin — 'archive', 'move to trash', 'undo delete', so nothing is lost by accident): add `\"trash\":true` to the TABLE (sibling of columns). Then `DELETE ${API}/rows/<t>/<id>` HIDES the row (marks it trashed) instead of erasing it, and every read EXCLUDES trashed rows automatically. To build a trash/archive view: list with `?trashed=1` (only trashed) — restore one with `POST ${API}/rows/<t>/<id>/restore`. `?withTrashed=1` lists live+trashed together. To delete for real (empty-trash / permanent), add `?hard=1` to the DELETE. Same write scope as normal (feed/user own row, admin any). Use this whenever the user should be able to recover a deletion. " +
  "ARCHIVE (Gmail-style — file a row away without deleting it, SEPARATE from trash): add `\"archivable\":true` to the TABLE → `POST ${API}/rows/<t>/<id>/archive` hides it from normal lists and `POST ${API}/rows/<t>/<id>/unarchive` brings it back. Reads exclude archived by default; `?archived=1` lists the archive view, `?withArchived=1` lists everything. Same write scope as the table. Use for 'archive project', 'done' items you keep, an inbox archive. " +
  "ORDERED LISTS / DRAG-TO-REORDER (a hand-arranged list — todos, a playlist, kanban cards, a gallery): add `\"ordered\":true` to the TABLE → each row auto-gets a `position` (appended to the END on insert, scoped per-member on user/feed), and you reorder with `POST ${API}/rows/<t>/<id>/move` sending `{after:<id>}` or `{before:<id>}` (drop it beside that row) or `{to:<number>}` (absolute). List with `?sort=position&order=asc`. Positions are fractional so one move never renumbers the rest. Same write scope as the table (feed/user your own rows, admin any). ASSIGN / LEAD ROUTING (hand a record to another member — assign a lead to a rep, reassign a case): `POST ${API}/rows/<t>/<id>/assign {user:<memberId or email>}` on a `user`/`feed` table sets that row's owner to the named member. Allowed for an ADMIN (or, on a `teamRead` table, the current owner's MANAGER). Combine with `teamRead` so the new owner's manager still sees it; it also fires any `on:{update}` automation. MERGE DUPLICATES (dedupe two records into one — merge duplicate accounts/contacts): `POST ${API}/rows/<t>/<id>/merge {from:<otherId>, fillBlanks?:true}` (ADMIN) folds the `from` record INTO this one — every child row that references `from` (via a `ref`) is repointed to this id, then `from` is deleted. `fillBlanks:true` first copies the loser's non-empty values into this record's still-empty fields (keep the fuller record). The loser's ACTIVITY comes along too — its notes, attachments, approvals, and tags are moved onto the survivor (duplicate tags/reactions deduped), so a merge never loses history. Returns `{into, from, repointed:{table:count}}`. DUPLICATE a record — `POST ${API}/rows/<t>/<id>/clone` (optionally `{overrides:{…}}`) copies a row into a NEW one (auto id/slug/number/timestamps regenerate; the caller becomes owner on user/feed tables) — for a 'Duplicate' button on an invoice/project/template. Override any field (e.g. a UNIQUE code, or a new title); a UNIQUE clash you didn't override comes back 409. " +
  "EXPIRING ROWS / TTL (a row that should disappear after a time — a flash-sale price, a 24h story, a one-time invite, a temp share link): add `\"expires\":true` to the TABLE → the row auto-gets an `expires_at` column that YOU set to a datetime/ISO string when creating it, and every read then HIDES rows whose `expires_at` has passed (leave it NULL = never expires). `?expired=1` lists only the expired ones, `?withExpired=1` lists all. Renew by PATCHing `expires_at` to a later time. Hidden, not deleted (sweep them with a scheduled function if you want them physically gone). " +
  "SCHEDULED PUBLISH / DRAFTS (a post that auto-goes-live at a set time, or a draft hidden until ready — the inverse of expiring rows): add `\"publishable\":true` to the TABLE → the row auto-gets a `publish_at` column; leave it NULL to publish immediately, or set it to a FUTURE datetime and the row stays HIDDEN from reads until then (goes live automatically, no cron needed). `?scheduled=1` lists the not-yet-published (a 'Scheduled'/drafts admin view), `?withScheduled=1` lists everything. Publish now by PATCHing `publish_at` to null or a past time. " +
  "FEATURED / PINNED + DEFAULT ORDER: add `\"pinnable\":true` to a TABLE → each row gets a `pinned` flag (0/1) that YOU set, and pinned rows ALWAYS list first (sticky posts, featured products, announcements) with the normal order applying within each group; `pinned` is queryable/sortable like any column (`where=pinned:eq:1`). Add `\"defaultSort\":\"-created_at\"` to a TABLE (same prefix convention as `?sort`: `-`=desc, `+`=asc, e.g. `\"+title\"`) so its list has a built-in order when a request sends no `sort` of its own — the app can still override per query. " +
  "REALTIME (chat/live feed): `GET ${API}/rows/<t>/changes?since=<cursor>` returns only newer rows (ascending) + a fresh `{cursor}`+`{count}`; add `&wait=1` to long-poll up to ~20s (returns the instant a row lands). For a full CHANGE LOG (updates and deletes too, not just new rows) on an `audit:true` table, `GET ${API}/rows/<t>/events?since=<cursor>` returns the insert/update/delete stream (admin) — use it to sync an external system. Seed the cursor from the newest id of your initial list, then loop. Appends only (re-list to catch edits). OFFLINE SYNC (keep a local copy current — pull edits AND deletes since last time, not just new rows): add `\"sync\":true` to the TABLE, then `GET ${API}/rows/<t>/changes?sync=<lastCursor>` returns `{updated:[rows created OR edited since], deleted:[ids removed since], at:<newCursor>}` — apply the updates, drop the deleted ids from your local copy, save `at` for next time (first call: `?sync=` empty = full pull). " +
  "ATOMIC INCREMENT (change a NUMBER on ONE row race-free — decrement stock on a purchase, +1 a score/quantity/view on a specific record): `POST ${API}/rows/<t>/<id>/incr {col, by}` adds `by` (default 1, negative to subtract) to that numeric column and returns `{value}` (the new number); pass `{col,by,min:0}` to floor it (stock never goes below 0). Write scope matches the table (feed/user → your own row, needs the Bearer; admin → any row). Use this instead of read-then-write (which races). For a TALLY not tied to a row (page views, anonymous likes) use a counter instead. " +
  "OPTIMISTIC LOCKING / NO LOST UPDATES (when two people can edit the SAME row — a shared doc, a collaborative board, an admin CMS with several editors — stop the second save from silently overwriting the first): add `\"version\":true` to the TABLE (sibling of columns). Every row then carries a `_version` number that auto-increments on each edit and is returned on reads (`row._version`). When you PATCH, send the version you loaded: `PATCH ${API}/rows/<t>/<id>?ifVersion=<n>` (or header `If-Match: <n>`). If someone else edited it since, the write is REFUSED with HTTP **409** `{code:'conflict', version:<current>}` — catch it, tell the user 'this changed, reload', and refetch. A successful PATCH returns `{ok:true, version:<new>}` so you can keep editing. Omit `ifVersion` to force-write (last-writer-wins). Use this on any row multiple members can edit. " +
  "ROW HISTORY / UNDO (keep a version history of a row and let its owner restore a past version — docs, listings, a profile, anything edited over time): add `\"history\":true` to the TABLE → every edit snapshots the previous values automatically; the row's OWNER (or an admin) reads `GET ${API}/rows/<t>/<id>/history` → `[{id, snapshot, at}]` newest-first, and restores one with `POST ${API}/rows/<t>/<id>/revert/<historyId>` (the revert is itself recorded, so it too is undoable); and `GET ${API}/rows/<t>/<id>/diff[/<histId>]` returns what CHANGED between a snapshot (the latest by default, or `/<histId>` or `?rev=`) and the current row — `{changed, changes:{col:{from,to}}}` — for a 'what changed' revision view. " +
  "PER-ROW SHARING / ACL (let a member share ONE of their private records with specific other members — a shared doc/board/trip/list, Google-Docs style; ONLY on a `user`-access table): the row's OWNER manages access — `POST ${API}/rows/<t>/<id>/share {user:'<email or member id>', perm:'view'|'edit'}` grants (re-POST to change the level), `DELETE ${API}/rows/<t>/<id>/share/<memberId>` revokes, `GET ${API}/rows/<t>/<id>/share` lists who it's shared with (owner only, Bearer). The RECIPIENT then: sees it via `GET ${API}/rows/<t>/<id>` (their normal reads still only show their OWN rows — to list everything shared WITH them add `?shared=1` to the list read), and if granted `edit` may `PATCH` it (a `view` share is read-only). DELETE stays owner-only (a collaborator can edit content but never delete someone else's row). Use this for real collaboration instead of copying a row per user. " +
  "CUSTOM ROLES / RBAC (roles beyond just admin/user — moderator, editor, staff — that can write to an `admin` table): on an `admin`-access table add a table-level `\"writeRoles\":[\"editor\",\"admin\"]` (sibling of columns) → members whose role is any of those may write (create/edit/delete); everyone still READS. The built-in `admin` role can ALWAYS write (superuser), so you needn't list it. Members default to role `user`; the OWNER assigns roles from their dashboard (there's no in-app self-serve role change — that'd be a privilege-escalation hole). So use `writeRoles` for 'editors can post articles, everyone reads' style gates; use `user`/`feed` when each member only touches their OWN rows. FIELD-LEVEL SECURITY (hide sensitive columns from some roles — salary, cost, margin, SSN): add a TABLE-level `\"fieldRoles\":{\"amount\":[\"admin\",\"manager\"],\"cost\":[\"admin\"]}` mapping a column to the roles allowed to READ it. On reads the column is STRIPPED for anyone whose role isn.t listed (signed-out visitors count as role `public`); an `admin` always sees every field. So reps see the deal but not its margin. FIELD MASKING (partial-reveal instead of fully hiding — show `••••4242` of a card, the last 4 of a phone/SSN): a TABLE-level `\"mask\":{\"number\":{\"roles\":[\"admin\"],\"keep\":4},\"cvv\":{\"roles\":[\"admin\"],\"keep\":0}}` — readers whose role isn't listed see the value with only its last `keep` chars, the rest replaced by `•` (an admin always sees it whole). Use `mask` when the shape should stay visible (a masked card still reads as a card); use `fieldRoles` when the field should vanish entirely.Combine with `writeRoles` to also gate who can edit the table. TEAM / MANAGER VISIBILITY (a manager sees their reports. records — CRM roll-up, org-scoped dashboards): add `\"teamRead\":true` to a `user` table. Members are arranged into a hierarchy by the OWNER (member management sets each member.s manager); then on READS (list/single/stats/facets) a member also sees rows owned by their whole downline (recursive), not just their own. WRITES stay own-row-only (a manager views but doesn.t edit a report.s row). A member with no reports is unaffected. APPROVAL WORKFLOW (sign-off before a record is final — expense/discount/big-deal approval, content review): add a TABLE-level `\"approval\":{\"approvers\":[\"manager\",\"admin\"],\"status\":\"approval_status\"}` (`status` optional, defaults to `approval_status`). It platform-adds a `status` column that is READ-ONLY to the app (queryable/sortable, but NEVER settable via a normal write — so an owner can.t self-approve by editing the row). Drive it with these endpoints (Bearer): `POST ${API}/rows/<t>/<id>/submit {note?}` (a writer of the row — its owner on user/feed, or an admin/writeRole on an admin table) sets status→`pending`; `POST ${API}/rows/<t>/<id>/approve {note?}` and `POST ${API}/rows/<t>/<id>/reject {note?}` (a member whose role is in `approvers`, or admin) set it to `approved`/`rejected`; `GET ${API}/rows/<t>/<id>/approvals` returns the decision LOG (who submitted/approved/rejected, when, note) + current status. The pending QUEUE is just a normal list filter: `?where=approval_status:eq:pending` (approvers see items to action; pairs with `teamRead` so a manager sees their team.s). approve/reject fire `on:{update}` functions. Use this instead of a plain enum column when a decision must be gated to certain roles AND audited. ROUND-ROBIN ASSIGNMENT / LEAD ROUTING (auto-distribute new records across a team — incoming leads/cases/tickets spread evenly over the reps): on a `user` or `feed` table add `\"roundRobin\":{\"among\":[\"rep\"]}` (the roles that form the pool). Each new row's `owner_id` is auto-assigned to the NEXT member of that pool in rotation (stable order, atomic counter → even distribution, no double-assign), regardless of who created it — so an admin or a public intake can file leads and they fan out to the sales team. Blocked members are skipped; an empty pool falls back to the creator (a record is never left unowned). The create response returns the chosen `owner_id`. Pair with `teamRead` so a manager sees the whole team's assigned records, and with `/assign` for manual re-routing. TERRITORY / FIELD-BASED ROUTING (send a new record to a SPECIFIC owner by one of its field values — leads from a region, deals of a product line, tickets of a tier): on a `user`/`feed` table add `\"assignBy\":{\"field\":\"region\",\"map\":{\"west\":\"<member id or email>\",\"east\":\"…\"},\"default\":\"<id|email>\"}`. On insert the row's `field` value (case-insensitive) is looked up in `map` → that member becomes `owner_id`; an unmapped value uses `default` (omit it to fall through). Territory routing takes PRECEDENCE over `roundRobin` on the same table, so you can pin known segments to named reps and let round-robin spread everything else — declare both together. The member must exist (id or email); if none resolves it falls back to round-robin, then the creator." +
  "AUTO SLUGS / PRETTY URLS (a clean url-safe key per row for `/blog/my-first-post` or `/p/blue-widget` instead of `?id=42`): add a TABLE-level `\"slug\":\"<sourceColumn>\"` (sibling of columns, e.g. `\"slug\":\"title\"`). On insert the platform fills a `slug` column from that source — lowercased, spaces/punctuation → dashes, diacritics folded (\"My First Post!\" → `my-first-post`) — and GUARANTEES it's unique (appends `-2`, `-3`, … on collision), so you can route by it safely. Read one row by slug with `GET ${API}/rows/<t>?where=slug:eq:<theSlug>` (take `rows[0]`); the `slug` field is returned on every read. Use it in links (`/post/${row.slug}`). You may also POST your own `slug` (it's normalized + still policed for uniqueness → 409 on a dup). Don't declare a `slug` column yourself — declaring `\"slug\":\"title\"` on the table is enough. " +
  "JSON / NESTED COLUMNS (store a whole object or list in ONE column — an order's line-items array, a settings object, tags/options, flexible metadata that doesn't deserve its own table): declare the column `\"type\":\"json\"` (aliases `array`/`object`). Then just POST/PATCH the real value — send `{items:[{sku,qty},…]}` or `{prefs:{theme:'dark'}}` as an actual array/object (NOT a JSON string) and read it back as a parsed array/object (NOT a string). The platform stringifies on write and parses on read for you, everywhere (single row, list, batch, realtime). Use this for genuinely nested/variable-shape data; use a related `ref` table instead when you need to QUERY or sort by the inner rows (you can't `where=` into a json column). " +
  "COUNTERS (likes · view counts · reactions · poll tallies — anything that just tallies up, where a race-free atomic count matters and a full row per event is overkill): `POST ${API}/count/<name>` increments a named counter and returns `{value}` (the NEW total); add `?by=N` to add N (negative to subtract, e.g. undo a like; floored at 0). `GET ${API}/count/<name>` → `{value}`; `GET ${API}/count` → `{counters:{name:value,…}}` for a whole dashboard. PUBLIC + atomic (no login, no races) — use a per-thing name like `like:post:${id}`, `views:home`, `poll:color:blue`. Use this for tallies; use a `feed` table only when you need one ROW per event (who/when/text). For an ANONYMOUS view/like tally a counter is enough; if it must be ONE-per-USER (a like/upvote/RSVP that a member can toggle), use REACTIONS instead (below) — it dedupes for you. " +
  "REACTIONS (one-per-user likes · upvotes/downvotes · RSVPs · emoji — a signed-in member toggles it, and you need the count AND whether THIS member reacted): `POST ${API}/react/<target> {type}` (Bearer; `type` default `'like'`) TOGGLES the caller's reaction and returns `{reacted, count}` (pass `{type,on:true|false}` to force on/off). `GET ${API}/react/<target>` → `{counts:{type:n,…}, mine:[types you reacted with]}` (send the Bearer to get `mine`; anon gets counts only). **`<target>` MUST be `<tableName>:${id}` — the exact table name plus the row id (e.g. `posts:${id}`, `comments:${id}`) — so your manual react calls line up with the `?reactions=1` feed shortcut below; a mismatched target (e.g. `post:` vs the `posts` table) makes the button and the feed count disagree.** Dedup is enforced server-side (one per member+target+type) — you do NOT need a side table. **FEED SHORTCUT: add `?reactions=1` to a list read and every row comes back with `row.reactions = {counts, mine}` for target `<table>:<id>` (batched, and `mine` reflects the logged-in caller)** — so a list of posts renders like/upvote buttons with counts and the user's own state in ONE request. Combine with `?authors=1` freely. " +
  "POLLS (one vote per member, changeable — 'best logo', a survey, a with-options RSVP): `POST ${API}/poll/<pollId>/<option>` (Bearer) casts or CHANGES the caller's vote → `{counts:{option:n}, total, mine}`; `GET ${API}/poll/<pollId>` → the same tally (Bearer → `mine` = your chosen option); `DELETE ${API}/poll/<pollId>` (Bearer) withdraws it. pollId + option are your own strings (e.g. poll `logo-2026`, options `red`/`blue`). One-vote-per-member is enforced server-side (re-voting moves it), so you don't hand-roll it. " +
  "MENTIONS (@-mention members and notify them): when a member posts text containing @handles, resolve those handles to user ids client-side (you have the member list via profiles), then `POST ${API}/mention {target:'<table>:<id>', users:[<ids>], text?}` (Bearer) drops a `mention` notification into each mentioned member's inbox (with `link` = target). Capped ≤10 recipients/call, rate-limited, and deduped per target+member within an hour (so it can't spam). Pairs with the notifications inbox. " +
  "NOTIFICATIONS (a per-member inbox + unread badge — 'someone commented on your post', 'your order shipped'): a signed-in member reads THEIR OWN inbox with `GET ${API}/notifications` (Bearer) → `{rows:[{id,type,text,link,read,created_at}], unread}` (add `?unread=1` for only-unread); mark one read `POST ${API}/notifications/<id>/read`, or all `POST ${API}/notifications/read-all`. Poll `unread` for the badge. Notifications are CREATED server-side only — a `{\"do\":\"notify\",…}` step in a function (usually an on-insert TRIGGER: new comment → notify the post's owner_id), never by the browser — so members can't spam each other. " +
  "AUTH (for user/feed/admin): `POST ${API}/auth/signup` · `/auth/login` `{email,password}` → `{token,user}` (store token in localStorage); `GET ${API}/auth/me` with the Bearer header verifies the session. ROLES: `user.role` — first signup becomes `'admin'`, rest `'user'`; gate admin UI on `user.role==='admin'` (server also enforces: non-admin write to an admin table → 403). FORGOT PASSWORD: a form POSTing `${API}/auth/reset-request {email}` — always resolves ok, show ONE neutral message ('if that email has an account…'), never reveal existence; the platform sends the email + hosts the reset page (you build only the form). EMAIL VERIFY: automatic on signup; `user.verified` (0/1) is available if you want to gate on it, with a 'Resend' → `${API}/auth/verify-request`; most apps ignore it. To REQUIRE a confirmed email before a member may WRITE to a given table, add `\"requireVerified\":true` to that TABLE — unverified writes then get 403 `{code:'unverified'}` (reads still work), so gate sensitive posting on it. INVITE-ONLY: if the owner turned on invite-only signup, `POST ${API}/auth/signup` returns `{ok:false, need:'invite'}` (403) unless the body includes a valid `invite` code — so ALWAYS include an optional 'Invite code' field on the sign-up form and pass it as `invite`; on a `need:'invite'` error, reveal/hint the invite field. The owner turns this on and mints codes from their dashboard; you don't manage codes in the app. ACCOUNT SETTINGS (a signed-in member manages their OWN account): `POST ${API}/auth/password {current_password, password}` changes the password (re-checks the current one, returns a fresh `token` — store it); `POST ${API}/auth/email {password, email}` changes the email (returns a fresh token); `DELETE ${API}/auth/account {password}` permanently deletes the account plus that member's own rows AND their personal side-data (direct messages, block edges, login history, presence, consents, saved views, and notes they authored) — a real right-to-be-forgotten erase. Each re-verifies the current password (a stolen token alone can't). `POST ${API}/auth/logout-all` (Bearer) logs the account out of OTHER devices and returns a FRESH token for THIS one (store it) — every device's next `/auth/me` check then fails and forces re-login. Build an 'Account settings' page from these when the app has logins. SOCIAL LOGIN (Google / GitHub OAuth — 'Continue with Google' buttons): to start, send the browser to `${API}/auth/oauth/google` (or `/auth/oauth/github`) — a plain LINK or `location.href`, NOT fetch (it's a full-page redirect). Optional `?return=<path>` picks where to land after (defaults to the app root). The platform runs the whole OAuth dance server-side and redirects back to `/s/<slug>/<return>#token=<jwt>`; so on EVERY page load, if `location.hash` has `#token=…`, grab it (`new URLSearchParams(location.hash.slice(1)).get('token')`), `store.set(K, token)`, strip the hash (`history.replaceState(null,'',location.pathname)`), then proceed as a normal logged-in session (the token works at `/auth/me` and everywhere a password token does; the account is auto-verified). Requires the OWNER to add `GOOGLE_CLIENT_ID`+`GOOGLE_CLIENT_SECRET` (and/or `GITHUB_CLIENT_ID`+`GITHUB_CLIENT_SECRET`) in Cloud → Secrets and register the redirect URI `https://<this-site>/api/db/<slug>/auth/oauth/<provider>/callback` with the provider — TELL the user this; until then those buttons return a clear 'not set up' message (so only add social buttons when asked, and mention the setup). Password signup/login and social login share the same `_users`, so a member can use either. TWO-FACTOR (TOTP authenticator apps — Google Authenticator / Authy / 1Password): `POST ${API}/auth/2fa/setup` (Bearer) → `{secret, otpauth}` (show the `otpauth` as a QR + the secret to type); `POST ${API}/auth/2fa/enable {code}` confirms the first code and turns it on; `POST ${API}/auth/2fa/disable {code}` turns it off. Once ON, LOGIN needs the code too — if `POST ${API}/auth/login` returns `{ok:false, need:'2fa'}` (401), prompt for the 6-digit code and re-POST login with `{email,password,code}`. " +
  "PROFILES (a member's PUBLIC identity — display name, avatar, bio — so you show WHO posted WITHOUT copying an author name into every row): signup optionally takes `display_name` (`{email,password,display_name}`; else it defaults from the email). `GET ${API}/profile/<userId>` → public `{id,display_name,avatar_url,bio}`; `GET ${API}/profile/me` (Bearer) → own; `PATCH ${API}/profile/me {display_name?,avatar_url?,bio?}` edits own (build a simple 'Edit profile' form for this). **To show authors on a feed, DON'T store an author_name column — add `?authors=1` to the list read and each row comes back with `row.author = {id,display_name,avatar_url}` (its poster, by owner_id), batched.** Batch fetch arbitrary members with `GET ${API}/profiles?ids=1,2,3`. " +
  "FOLLOWS (a member follows another — the social graph behind followers/following counts and follow buttons): `POST ${API}/follow/<userId>` (Bearer) TOGGLES → `{following, followers}` (pass `{on:true|false}` to force a direction); `GET ${API}/follow/<userId>` → `{followers, following, mine}` (send the Bearer so `mine` = whether YOU follow them). Build 'Followers'/'Following' pages with `GET ${API}/follow/<userId>/followers` and `/following` → arrays of public profiles `{id,display_name,avatar_url,bio}`. You can't follow yourself; dedup is automatic (one edge per pair, no side table). **HOME FEED: on a `feed` list read, a signed-in caller adds `?following=1` to get ONLY posts by members they follow (the classic home/timeline) — composes with `where`/`q`/`sort`/pagination; empty if they follow nobody, ignored when signed out.** " +
  "BLOCK / MUTE (a member hides another): `POST ${API}/block/<userId>` (Bearer) toggles a block → `{blocking}` (and severs any follow between the two); `GET ${API}/block/<userId>` → `{blocking}`; `GET ${API}/blocks` → your blocked user ids. Then add `?hideBlocked=1` to a `feed` list read (Bearer) to drop posts by anyone you've blocked (composes with `?following=1`), and pass it on `${API}/feed?table=…` to drop blocked authors from the home timeline too. A block also STOPS DMs: a member you've blocked can no longer send you a direct message (their `POST ${API}/dm` to you → 403 `{code:'blocked'}`) — it's one-directional, so YOU can still message them. " +
  "PRESENCE / ONLINE (show who's active now — a chat sidebar, a collab room, an 'active members' list): the signed-in member sends a heartbeat `POST ${API}/presence` every ~60s while the tab is active; `GET ${API}/presence[?within=5]` → members seen in the last N minutes `[{id,display_name,avatar_url,last_seen}]`; `GET ${API}/presence/<userId>` → `{online, last_seen}` for one. " +
  "APP SETTINGS / CONFIG (site-wide settings, feature flags, theme, editable hero text — a single key→value store per app, NOT per-row data): `GET ${API}/config` → `{config:{…}}` or `GET ${API}/config/<key>` → `{value}` (PUBLIC, so the app reads these to render). Set with `POST ${API}/config/<key> {value}`; remove with `DELETE ${API}/config/<key>` — BOTH require an ADMIN site-user (only the app's admin edits settings). Values are JSON, so booleans/numbers/objects round-trip (`{value:true}`, `{value:42}`, `{value:{...}}`). Use this for global switches/feature-flags/branding; use a real TABLE for records. API KEYS (server-to-server / app-to-app access — let ANOTHER backend read+write this app's data without a member login): an admin mints a key with `POST ${API}/apikeys {label, rpm?}` → `{key:'sk_…', rpm}` shown ONCE (store it then; optional `rpm` caps THAT key at N requests/minute across all tables — over the cap → 429, omit for unlimited), `GET ${API}/apikeys` lists them (prefix + label + rpm only, never the secret), `DELETE ${API}/apikeys/<id>` revokes. The other server calls the data API with header `X-API-Key: sk_…` (instead of a Bearer token) and acts as the admin who minted it (full read/write). Manage these on an admin-only settings screen; NEVER embed a key in client-side page JS — it's a secret, treat it like a password. " +
  "SAVED VIEWS / FILTERS (let a member save and reuse a filter set / saved search / dashboard config): `POST ${API}/views/<name> {spec}` (Bearer) saves an arbitrary-JSON view; `GET ${API}/views` → their saved views `[{name,spec,created_at}]`; `GET ${API}/views/<name>` → one spec; `DELETE ${API}/views/<name>` removes it. Put the current filter/query params in `spec` and re-apply them when the member picks a view. Private per member. " +
  "BOOKMARKS / SAVES (a member's PRIVATE 'save for later' — favourites, a wishlist, a reading list — over any row): `POST ${API}/save/<table>:<id>` (Bearer) TOGGLES a save → `{saved, count}` (`{on:true|false}` forces); `GET ${API}/save/<table>:<id>` → `{count, mine}` (Bearer → whether YOU saved it). List the caller's own saves with `GET ${API}/saves[?table=<t>]` → `[{target, table, id, created_at}]` newest-first — then load those rows with `?where=id:in:<ids>`. Target is `<tableName>:<id>` (same convention as reactions). Deduped per member; no side table needed. " +
  "REPORTS / MODERATION (let members flag bad content — spam, abuse — and give the app ADMIN a queue to review): `POST ${API}/report/<table>:<id> {reason}` (Bearer) flags a row → `{reported, count}`; `GET ${API}/report/<target>` → `{count, mine}`. The admin moderation queue: `GET ${API}/reports[?status=open|resolved|dismissed|all]` (ADMIN Bearer) → the flagged items with reporter name + reason; resolve one with `POST ${API}/reports/<id> {action:'resolve'|'dismiss'|'reopen'}`. Deduped one-flag-per-member; build a simple admin 'Reports' page from the queue. ACTIVITY NOTES / LOGGING (a CRM activity log against a record — logged calls, emails, meeting notes, follow-ups on a contact/lead/deal; also works as internal comments on any row): `POST ${API}/rows/<t>/<id>/notes {body, kind?}` (Bearer) logs a note — `kind` is one of note|call|email|meeting|task|sms|log (default note); `GET ${API}/rows/<t>/<id>/notes[?kind=&limit=]` returns them newest-first, each with the author's public profile under `note.author`; `DELETE ${API}/rows/<t>/<id>/notes/<noteId>` removes your OWN note (an admin removes any). A member must be able to SEE the record to read/add notes — on a `user` table that's the owner, its owner's manager (`teamRead`), or an admin; on a public-read table (display/feed/admin) any signed-in member; write-only `collect` tables have no notes. Use it to render a record's activity timeline and log touches — no schema declaration needed, it's available on every non-collect table. FILE ATTACHMENTS (attach a contract PDF, proposal, image to a record): `POST ${API}/rows/<t>/<id>/attach {filename, content_type?, data:<base64>}` (Bearer; `data` may be a `data:` URL — the prefix is stripped; ≤~10 MB) stores the file and returns `{attachment:{id, filename, size, url, …}}`; `GET ${API}/rows/<t>/<id>/attach` lists a record's attachments (metadata + `url` each); `DELETE ${API}/rows/<t>/<id>/attach/<attId>` removes your own (admin any). Fetch the bytes back at the returned `url` (`${API}/attach/<attId>`) — it streams the file through the server with its content-type, and access follows the RECORD's visibility (a public-read row's file is public; a `user` row's file only its owner/team/admin — send the Bearer token). A member must be able to SEE the record to attach/list; not available on `collect` tables; 50 files/record. No schema declaration needed. Add `?sign=1[&ttl=<seconds>]` to the LIST call and each attachment also gets a `signed_url` — an expiring link (default 1h, max 7d) that opens the file WITHOUT a token, for embedding a private file in an email, an `<img src>`, or a share link. STORAGE USAGE (an admin dashboard of how much file storage the app is using): `GET ${API}/storage` (admin Bearer) → `{attachments:{count, bytes}, by_table:[{table, count, bytes}]}` — total attachment count + bytes site-wide and per table. Render a usage bar or per-object breakdown from it. UNIFIED TIMELINE (render a record's whole history panel in ONE call): `GET ${API}/rows/<t>/<id>/timeline[?types=&limit=]` merges that record's notes, approval decisions, and — when the table declares `\"audit\":true` — its field-change audit events into ONE reverse-chronological feed. Each entry has `{type:'note'|'approval'|'audit', at (ISO), actor_id, actor:{display_name,avatar_url}, …}` plus type-specific fields (note→kind/body, approval→action/note, audit→action). Narrow the sources with `?types=note,approval` and cap with `?limit=`. Same visibility gate as notes. Use this for the activity/history sidebar instead of stitching notes + approvals client-side." +
  "COUPONS / DISCOUNT CODES (a redeemable promo code with a usage cap + expiry): the app ADMIN mints codes `POST ${API}/coupons {code, discount, max_uses?, expires_at?}` (`discount` is your OWN JSON — `{percent:10}`, `{amount:500}`, `{freeShipping:true}`), lists `GET ${API}/coupons`, removes `DELETE ${API}/coupons/<code>`. Anyone VALIDATES a code (no consume) with `GET ${API}/coupon/<code>` → `{valid, discount, remaining}`; a signed-in member REDEEMS with `POST ${API}/coupon/<code>/redeem` → `{ok, discount}` (atomic, so the usage cap is race-free) or 409 when expired/used-up. " +
  "CART + ORDERS (a store): the CART is ready-made — `POST ${API}/cart/<table>:<id> {qty}` (Bearer) sets an item's quantity (qty 0 removes), `GET ${API}/cart` → `{cart:[{item,table,id,qty}], count}`, `DELETE ${API}/cart/<item>` removes one, `DELETE ${API}/cart` empties it. For ORDERS, declare a `user`-access `orders` table (columns like `items` (json), `total`, `status`, `email`); on checkout read `/cart`, price it by looking each item up in its product table (server-authoritative — never trust a client price), write the order row, decrement stock with the atomic incr `{by:-1, min:0}`, apply a coupon via `/coupon/<code>/redeem`, then `DELETE ${API}/cart`. Take payment with the Stripe `checkout` FUNCTION step (owner adds their STRIPE_KEY). " +
  "AUDIT LOG (a compliance / 'who changed what' trail): add `\"audit\":true` to a TABLE → every insert/update/delete is recorded automatically (no code); the app ADMIN reads it at `GET ${API}/audit[?table=<t>&action=<a>&actor=<id>&since=&until=&limit=N&offset=N]` → `[{row_table,row_id,action,actor_id,at}]` newest-first (filter by table / exact action / actor id / time range). Actor is the row's owner on user/feed tables. " +
  "DATA EXPORT / IMPORT (admin): `GET ${API}/export/<table>[?format=csv|json]` (ADMIN Bearer) downloads the whole table as CSV/JSON. `GET ${API}/export[?limit=N]` (ADMIN) downloads the ENTIRE site's data in one JSON bundle — `{tables:{name:[rows]}, users:[…safe cols, no passwords]}` — for a one-click 'Download all data' / backup button. `POST ${API}/import/<table> {csv, mapping?, hasHeader?}` (ADMIN) bulk-loads a spreadsheet — headers that match a declared column auto-map, or pass `mapping:{\"CSV Header\":\"table_col\"}`; only declared columns are written, each row is validated, and it returns `{inserted, skipped}`. Wire an admin Export button + an Import (paste CSV / file-read) form. BULK UPDATE / DELETE (admin — change or remove MANY rows at once by a filter, in one call: 'archive all completed tasks', 'delete all drafts', 'mark everything in this category on sale'): `POST ${API}/rows/<table>/bulk {op, where, set?, all?, limit?}` (ADMIN Bearer). `op` is `\"update\"` (needs `set:{col:val,…}` of declared columns) or `\"delete\"`. `where` is an array of the SAME filter clauses as a list read (`[\"status:eq:done\",\"priority:gte:3\"]`) and is REQUIRED — to intentionally hit every row pass `all:true` instead. Returns `{op, affected}` (the row count changed). Affected rows are capped (default 1000, `limit` up to 5000). On a `trash` table a bulk delete SOFT-deletes (recoverable, `soft:true` in the response); on a non-trash table it's permanent. Use THIS instead of looping per-row PATCH/DELETE from the client. " +
  "AI (real AI features, NO key needed): `POST ${API}/ai {prompt, system?}` → `{ok,text}` (chatbot, summarize, suggest, categorize). Runs server-side on the owner's credits; show a loading state, on `{ok:false}` show `d.error`. Server-side variant = an `ai` function step. " +
  "ANALYTICS (optional): fire-and-forget `POST ${API}/track {event, path}` on page views + key actions ('signup','purchase') so the owner sees traffic. No auth, no response handling. To build an IN-APP analytics dashboard (the app's OWN admin viewing that traffic), read it back with `GET ${API}/analytics[?days=14 | from=YYYY-MM-DD&to=YYYY-MM-DD][&event=&path=]` (ADMIN Bearer) → `{total, from, to, byEvent:{event:count}, byPath:[{path,n}] (top 50), series:[{day,n}] (a zero-filled daily time-series for charts — one point per day, gaps = 0), events:[distinct event names]}`. Filter to one `event` or `path`; window defaults to the last 14 days (max 90) or pass an explicit `from`/`to`. Admin-only (traffic is business data). Use the `series` straight in a line/bar chart and `byPath`/`byEvent` for top-lists. CONVERSION FUNNEL (how many people make it through an ordered flow — signup → activate → purchase, or add-to-cart → checkout → paid): log a row per actor per step into an event-log table (a `feed` table with an `event` text column works — each member owns their rows), then read `GET ${API}/funnel?table=<t>&steps=signup,activate,purchase[&step_col=event&actor=owner_id&from=YYYY-MM-DD&to=YYYY-MM-DD]` (ADMIN Bearer) → `{steps:[{step, count, pct_of_top, pct_of_prev}], overall_conversion}`. For each step it counts DISTINCT actors who completed THAT step and every step before it (so it's a real monotonic funnel with drop-off — `pct_of_prev` is the step-to-step conversion, `pct_of_top` is vs the first step), repeated steps are de-duplicated, and steps outside your list are ignored. `step_col` defaults to 'event' and `actor` to 'owner_id' (override if your columns differ — both must be columns on the table). Admin-only. Use THIS for drop-off/conversion instead of counting each step separately (which double-counts and can't tell who advanced). RETENTION COHORTS (do people come BACK — of the users first seen in a period, what % return in later periods): over the same kind of event-log table (any row by an actor = 'active that period'), `GET ${API}/retention?table=<t>[&period=week&offsets=8&actor=owner_id&from=&to=]` (ADMIN Bearer) → `{period, offsets, cohorts:[{cohort, size, retention:[{offset, count, pct}]}], overall:[{offset,count,pct}]}`. Each actor is grouped into the cohort of their FIRST activity; `retention[o]` is how many of that cohort were active again `o` periods later (offset 0 = the cohort period, always 100%). `period` is day|week|month; `overall` is the size-weighted curve across all cohorts. Render it as the classic triangular retention heatmap (`cohort` rows × `offset` columns, shade by `pct`). Admin-only. Use THIS to see stickiness/repeat-usage over time, which a funnel (one-time flow) can't show. KPI SNAPSHOTS (track a business number over time — MRR, active users, NPS, conversion rate — with deltas): record `POST ${API}/kpi {metric, value, at?, note?}` (ADMIN Bearer) whenever you have a fresh reading (`at` defaults to now; `value` is any number, fractions OK). Read one metric's trend with `GET ${API}/kpi/<metric>[?from=&to=&limit=]` → `{points:[{value,note,at}] (oldest→newest), latest, previous, change, pct_change, min, max}`, or `GET ${API}/kpi` for every metric's latest value + delta vs its previous snapshot (`{metrics:[{metric, latest, previous, change, pct_change, at, count}]}`). `DELETE ${API}/kpi/<metric>` clears a metric's history. Admin-only. Use THIS for a metrics/stat dashboard (chart the `points`, show the `pct_change` as an up/down badge) — it's for numbers YOU compute and snapshot, vs `/analytics` which counts `/track` events automatically. OUTBOUND WEBHOOKS (notify an external service — Zapier / Slack / a CRM — when something happens in your app): an admin registers subscriber URLs then the app fires events to them. `POST ${API}/webhooks {url, events?, secret?}` (ADMIN Bearer) registers a subscriber (`url` MUST be https and public — localhost/private IPs are rejected; `events` is an array like `[\"order.created\",\"signup\"]` or omit/`\"*\"` for all; a `secret` turns on HMAC signing). `GET ${API}/webhooks` lists them (the secret is NEVER returned), `DELETE ${API}/webhooks/<id>` removes one. Fire an event with `POST ${API}/webhooks/emit {event, data}` (ADMIN) — the server POSTs `{event, data, at}` as JSON to every matching subscriber and returns `{matched, delivered, results:[{hook_id, ok, status}]}`. Each subscriber receives headers `X-Webhook-Event` and, when a secret was set, `X-Webhook-Signature: sha256=<hmac of the raw body>` (the receiver recomputes it to verify authenticity). Review attempts at `GET ${API}/webhooks/deliveries[?hook=&limit=]` (a log of ok/status/error per delivery). Admin-only. Use THIS to push events OUT to other systems; use the app's own tables/notifications for in-app reactions. AUTO-FIRE ON ROW CHANGES: add `\"webhooks\":true` to a TABLE and every create/update/delete on it AUTOMATICALLY fires `<table>.created` / `<table>.updated` / `<table>.deleted` to matching subscribers (no `/emit` call needed) — the payload's `data` is the row (`created` includes the new `id` + `owner_id` + submitted fields; `updated` the id + changed fields; `deleted` just `{id}`). Opt into only some actions with `\"webhooks\":[\"created\",\"deleted\"]`. So an app subscribes an external URL to `[\"orders.created\"]` and every new order POSTed to the `orders` table is delivered automatically. (Auto-fire covers single-row writes; bulk/batch inserts + upserts don't auto-fire — call `/webhooks/emit` for those.) " +
  "SAVED SEGMENTS / AUDIENCES (save a named filter over a table — 'active users', 'big spenders', 'trials expiring' — and re-count/preview it any time): `POST ${API}/segments {name, table, filter}` (ADMIN Bearer) where `filter` is either a query string (`\"where=plan:eq:pro&where=spend:gte:500\"`) or an object (`{where:[\"plan:eq:pro\",\"active:eq:1\"]}`) using the SAME where/q/sort grammar as a list read. `GET ${API}/segments` lists them, `GET ${API}/segments/<name>` returns one, `GET ${API}/segments/<name>/count` → `{count}` of matching rows right now, `GET ${API}/segments/<name>/preview[?limit=]` → sample matching rows, `DELETE ${API}/segments/<name>` removes it. Re-saving a name updates it. Evaluated as admin over ALL rows (trashed rows excluded), so it's an audience/marketing tool — pair a segment's members with `/webhooks/emit` or an export. Admin-only. Use THIS for reusable saved audiences instead of re-typing the same filter. " +
  "TEAMS / ORGANIZATIONS / WORKSPACES (group members into shared teams with a role each — the foundation for any B2B / multi-tenant app: a workspace, a project team, an org account): a signed-in member creates a team with `POST ${API}/teams {name}` (they become its `owner`) and lists the teams they're in with `GET ${API}/teams` → `[{id, name, role, members}]`. `GET ${API}/teams/<id>` → `{team:{…, my_role}, members:[{user_id, role, display_name, avatar_url}]}` (members only — a non-member gets 403). Roles are `owner` › `admin` › `member`: `POST ${API}/teams/<id>/members {user, role?}` adds a member (owner/admin; only the owner may grant `admin`), `PATCH ${API}/teams/<id>/members/<userId> {role}` changes a role — including `role:'owner'` to TRANSFER ownership (the caller-owner is demoted to admin) — owner-only, `DELETE ${API}/teams/<id>/members/<userId>` removes someone (owner/admin; nobody can remove the owner). `POST ${API}/teams/<id>/leave` leaves (the owner must transfer or delete first), `PATCH ${API}/teams/<id> {name}` renames, `DELETE ${API}/teams/<id>` deletes the whole team (owner-only). To SCOPE data to a team, add a `team_id` column to your table, set it on create, and filter reads by the caller's team ids (from `GET ${API}/teams`); enforce writes with a membership check on the server side of your own logic. Deleting an account removes that person's memberships automatically. INVITE BY EMAIL (the normal way to grow a team — you rarely know someone's user id): an owner/admin invites with `POST ${API}/teams/<id>/invites {email, role?}` (only the owner may invite an `admin`; inviting a current member → 409); `GET ${API}/teams/<id>/invites` lists the team's pending invites and `DELETE ${API}/teams/<id>/invites/<inviteId>` revokes one. The INVITEE (any signed-in member) sees invites addressed to their email with `GET ${API}/teams/invites/mine` → `[{id, team_id, team_name, role, invited_by}]`, and acts with `POST ${API}/teams/invites/<id>/accept` (joins the team as the invited role) or `POST ${API}/teams/invites/<id>/decline`. Accept/decline require the caller's email to match the invite. So the flow is: invite by email → the person signs up (or is already a member) → they see it under `/teams/invites/mine` → accept. Build a 'Pending invitations' banner from `/teams/invites/mine`. (The invite is stored server-side; to also EMAIL the person a link, pair it with an `email` function step.) PER-TEAM SETTINGS (each workspace configures ITSELF — branding, preferences, feature flags — separate from the site-wide `/config`): `GET ${API}/teams/<id>/config` → `{config:{key:value}}` and `GET ${API}/teams/<id>/config/<key>` → `{key, value}` (any member reads); `POST ${API}/teams/<id>/config/<key> {value}` sets and `DELETE ${API}/teams/<id>/config/<key>` removes (owner/admin only). Values are JSON, so booleans/numbers/objects round-trip. Config is isolated per team and cleared when the team is deleted. Use THIS for per-workspace settings in a multi-tenant app (each team's theme, plan limits, integrations) instead of one global config. TEAM-SCOPED DATA (a table whose rows are SHARED across a team — a shared CRM, a team task board, workspace docs): add `\"teamScope\":true` to a `user`-access TABLE. Then every row is stamped with a `team_id` on create (the member MUST pass `team_id` of a team they belong to — else 400/403 `{code:'team'}`), and READS are shared: any member of that team sees EVERY row whose team_id is one of their teams (not just their own). WRITES stay author-scoped — only the row's creator can edit/delete it (a teammate can read but not change it), so it's safe by default. A member in no team sees nothing. Rows come back with their `team_id`. Combine with `/teams` (create/join) + `/teams/<id>/config`. (Batch/upsert insert isn't supported on a teamScope table — insert one row at a time with its team_id.) Use THIS for genuinely shared team data instead of owner-private `user` rows or public `feed` rows. " +
  "DOUBLE-ENTRY LEDGER (accounting / bookkeeping for an ERP, invoicing app, or finance dashboard — a real general journal, NOT just a `transactions` table): ADMIN-only, `${API}/ledger/*`. POST a BALANCED entry `${API}/ledger/entries {ref?, memo?, date?, ledger?, lines:[{account, debit?, credit?, dim?, memo?}]}` — every entry is a set of debit/credit lines where Σdebit MUST equal Σcredit (each line puts an amount on exactly one side), e.g. a $100 cash sale is `lines:[{account:'cash',debit:100},{account:'revenue',credit:100}]`; a non-balancing entry is REFUSED (400). Entries are APPEND-ONLY + IMMUTABLE — never edited/deleted, only REVERSED: `POST ${API}/ledger/entries/<id>/reverse {memo?}` posts a mirror entry (a double-reverse → 409). Read balances with `GET ${API}/ledger/balance?account=<a>[&from=&to=&dim=]` → `{debit,credit,balance}` (balance = debit−credit, posted lines only), or the whole `GET ${API}/ledger/trial-balance[?from=&to=]` → every account's `{debit,credit,balance}` + `total_debit/total_credit/balanced`. List/inspect with `GET ${API}/ledger/entries[?account=&ref=&from=&to=]` and `GET ${API}/ledger/entries/<id>`. Use `dim` for a cost-center/project dimension, and `ledger` (default 'gl') to keep separate journals (a general ledger + AP/AR/inventory subledgers) in one app. Money is kept exact to the cent. Use THIS for anything that must tie out (accounts, invoices→payments, expense tracking) instead of summing a plain table — the balance invariant + immutability are the point. PERIOD CLOSE (freeze finalized books so nobody backdates into a closed month — the accounting 'lock date'): `POST ${API}/periods/close {through:'2026-01-31'}` closes the ledger through that date — any entry OR reversal dated on/before it is then REFUSED (409 `period_locked`), so post corrections into the current open period instead. `POST ${API}/periods/reopen` clears the lock (or `{through}` moves it earlier). `GET ${API}/periods` shows the current `lock_through` + any named periods you define with `POST ${API}/periods {name,start,end}`. Applies to the ledger only. RECURRING JOURNALS (save a balanced entry once, post it every month — rent, accruals, standing charges): `POST ${API}/ledger/templates {name, memo?, ledger?, lines:[…]}` saves a template (the lines must balance, checked now so posting always works); `GET ${API}/ledger/templates` lists them, `GET/DELETE ${API}/ledger/templates/<id>` fetch/remove one, and `POST ${API}/ledger/templates/<id>/post {date?, memo?}` fires it as a fresh dated ledger entry (respects the period lock). FINANCIAL STATEMENTS (a real P&L + balance sheet, not a hand-rolled sum): first CLASSIFY accounts — `POST ${API}/ledger/accounts {account, type, name?, code?}` where type is `asset|liability|equity|income|expense` (`GET ${API}/ledger/accounts` lists, `DELETE ${API}/ledger/accounts/<account>` unclassifies). Then `GET ${API}/ledger/pnl?from=&to=` → `{income:[…], total_income, expenses:[…], total_expenses, net_income}` for the period, and `GET ${API}/ledger/balance-sheet?as_of=` → `{assets, total_assets, liabilities, total_liabilities, equity, total_equity, retained_earnings, total_liabilities_and_equity, balanced}` (current earnings roll into equity, so a fully-classified set has `balanced:true` — any unclassified account with activity is surfaced in `unclassified` and flips `balanced` false so nothing is silently dropped). BUDGETS VS ACTUALS (set targets, compare to reality): `POST ${API}/ledger/budgets {account, period, amount, notes?}` sets a target for an account in a named period (e.g. '2026-q1'; upserts), `GET ${API}/ledger/budgets[?period=]` lists, `DELETE ${API}/ledger/budgets/<id>` removes. `GET ${API}/ledger/budget-report?period=<label>&from=&to=` compares that period's budgets against the ledger actuals over from..to → `{lines:[{account, type, budget, actual, variance, pct}], totals}` (variance oriented by account type so over/under reads naturally; unbudgeted income/expense activity still surfaces, balance-sheet accounts don't). DEPRECIATION (a fixed-asset schedule — how much an asset writes off each period): `POST ${API}/finance/depreciation {cost, salvage?, life, method?, factor?, start?, freq?}` returns `{total_depreciable, schedule:[{period, date?, depreciation, accumulated, book_value}]}`; method `straight_line` (default, even) or `declining_balance` (front-loaded, factor default 2). It ties out to the cent (book value ends exactly at salvage). LOAN AMORTIZATION (a repayment schedule for a mortgage / auto loan / BNPL / any loan-management app): `POST ${API}/finance/amortization {principal, rate, term, freq?, extra?, start?}` → `{payment, periods, total_interest, total_paid, schedule:[{period, date?, payment, interest, principal, balance}]}`. `rate` is the ANNUAL percentage (e.g. 6 = 6% APR), `term` is the number of payments (360 = a 30-year monthly loan), `freq` is payments/year (default 12 = monthly). It's a level-payment (annuity) loan that ties out to the cent — the balance ends exactly at 0. Pass `extra` (extra principal per period) to model early payoff — the loan finishes in fewer `periods` with less `total_interest`. `start` + `freq` stamps each row's due `date`. Stateless (any signed-in member). Use THIS for a loan schedule instead of hand-rolling interest math; post each period's interest + principal to the ledger. INVESTMENT / CAPITAL BUDGETING (should we do this project? — NPV, IRR, payback for FP&A/CPM/EPM analysis): `POST ${API}/finance/investment {cashflows, rate}` where `cashflows` is an array of per-period net amounts (index 0 = today, usually the negative up-front investment, then each period's inflow/outflow) and `rate` is the discount/hurdle rate as a percent (10 = 10%). Returns `{npv, irr, irr_pct, payback_period, discounted_payback, profitability_index, total_inflow, total_outflow, periods}`. `npv` is the net present value at your rate (positive = creates value); `irr`/`irr_pct` is the break-even rate solved numerically (null if the flows never cross zero); `payback_period` is when cumulative cashflow turns positive (fractional; `discounted_payback` on discounted flows); `profitability_index` = PV(inflows)/PV(outflows) (>1 = worth it). Cashflows may be numbers or `{amount}` objects. Stateless. Use THIS to rank projects / evaluate an investment instead of eyeballing raw cashflows. EOQ / INVENTORY PLANNING (how much to order and when — for IMS/SCM/WMS): `POST ${API}/finance/eoq {demand, order_cost, holding_cost[, lead_time, demand_std, service_level | safety_stock]}` → `{eoq, eoq_rounded, orders_per_year, cycle_time_days, annual_order_cost, annual_holding_cost, total_annual_cost}` — the cost-minimizing order quantity (√(2·D·S/H)) where `demand` is annual, `order_cost` is per order, `holding_cost` is per unit per year. Add a `lead_time` (days) to also get `{demand_during_lead, safety_stock, reorder_point, z}` — safety stock comes from a `service_level` (e.g. 95) + daily `demand_std`, or pass `safety_stock` directly. Stateless. Pairs with the reorder-rules + stock system. BREAK-EVEN / CVP (how many to sell to be profitable — pricing & planning): `POST ${API}/finance/breakeven {price, variable_cost, fixed_cost[, target_profit, units]}` → `{contribution_margin, cm_ratio, break_even_units, break_even_units_rounded, break_even_revenue}`. Give `target_profit` to also get the units to hit that profit; give a `units` volume to get `{profit_at_units, margin_of_safety_units, margin_of_safety_pct}`. Contribution margin = price − variable cost; break-even needs price > variable cost. Stateless. Use THIS for a pricing/what-if calculator. Store the asset in a normal table, show this schedule, and post each period with a recurring journal. Any signed-in member (stateless calc). DEMAND FORECAST (project future demand/sales from history — for planning + reorder): `POST ${API}/finance/forecast {series:[numbers or {value}], method?, horizon?, window?, alpha?}` → `{forecast:[{step, value}]}` for the next `horizon` periods. method `linear` (default, least-squares trend), `moving_average` (flat mean of the last `window`), or `exp_smoothing` (weighted recent, `alpha`). Feed the forecast against on-hand + reorder rules to plan purchasing. Stateless calc (any signed-in member). SALES TAX / VAT (compute tax on an order — invoice/POS/checkout): `POST ${API}/finance/tax {subtotal, rate | rates:[{name?, rate, compound?}], inclusive?}` → `{subtotal, tax, total, taxes:[{name, rate, amount}]}`. Pass one `rate` or a `rates[]` of jurisdictions (state + county + city); an additive rate charges on the subtotal, a `compound:true` rate charges on subtotal + prior taxes (tax-on-tax). `inclusive:true` treats the given `subtotal` as tax-INCLUSIVE and backs out the net (the per-jurisdiction split ties to the cent). Cents-exact, stateless (any signed-in member). Use THIS for order tax instead of multiplying in the browser. INSTALLMENTS / PAYMENT PLAN (BNPL, layaway, pay-over-time): `POST ${API}/finance/installments {total, count, down?, rate?, freq?, start?}` → `{payment, count, total_interest, total_paid, schedule:[{n, date?, amount, interest, principal, balance}]}`. Splits `total` (minus an optional `down`) into `count` payments; `rate` 0 = an equal split, `rate` > 0 = an amortized annuity that reuses the loan tie-out (the final payment clears the balance to exactly 0). `start` + `freq` (payments/year, default 12) stamp each row's due date. Stateless. TIERED / MARGINAL COMMISSION (sales comp, payroll, SPM): `POST ${API}/finance/commission {amount, rate | brackets:[{up_to?, rate}], base?}` → `{commission, effective_rate, brackets:[{from, to, rate, portion, commission}]}`. A flat `rate`, or marginal `brackets` where each bracket's rate applies ONLY to the portion of `amount` inside it (like income-tax brackets; the last bracket omits `up_to` = open-ended), plus an optional flat `base`. Cents-exact, stateless. Use THIS for tiered payout math instead of hand-rolling bracket logic. LEAVE / PTO BALANCES (HR — track annual/sick leave without overdrawing): ADMIN-only, `${API}/leave/*`. `POST ${API}/leave {employee, leave_type?, days, kind?, note?, date?}` records an accrual (days POSITIVE) or a taking (NEGATIVE); a taking that would overdraw is refused (409) unless `allowNegative`. `GET ${API}/leave/balance?employee=<e>[&leave_type=]` → `{balance}`, `GET ${API}/leave/balances[?leave_type=]` → everyone's, `GET ${API}/leave?employee=&leave_type=` → the history. Half-days OK. (The REST of HR — employees, departments, timesheets, projects — is plain tables: use `teamRead` for a manager's view, the approval workflow for leave requests, and stats for timesheet/project cost rollups. Payroll tax calc needs an external provider.) SCHEDULING / BOOKINGS (appointments, interviews, room/resource/equipment rentals — book time slots that can't double-book): any signed-in member uses `${API}/bookings/*`. `POST ${API}/bookings {resource, start, end, party?, ref?, note?}` books a window on a resource (ISO datetimes); two overlapping bookings on the same resource are IMPOSSIBLE — the second is refused (409 `conflict`) atomically, so no double-booking even under races. `GET ${API}/bookings/availability?resource=<r>&from=&to=&slot=<minutes>[&step=]` returns the FREE slots in a window (for a 'pick a time' UI). `GET ${API}/bookings[?resource=&from=&to=&status=]` lists (a member sees their own, an admin sees all), `POST ${API}/bookings/<id>/cancel` frees a slot, `DELETE ${API}/bookings/<id>` removes it. Back-to-back slots (end == next start) are allowed. Use THIS for anything time-slot based instead of a plain table so the no-overlap guarantee is real. WALLET / POINTS / STORE CREDIT (loyalty points, store credit, gift cards, in-app currency, XP — a guarded balance): writes are ADMIN (server-authoritative, so users can't credit themselves); a member reads their OWN balance. `POST ${API}/wallet {account, currency?, amount(+earn/−spend), kind?, ref?, note?}` credits or debits — a debit that would overdraw is refused (409) unless `allowNegative`. `GET ${API}/wallet/balance?account=<a>[&currency=]` → `{balance}`, `GET ${API}/wallet?account=<a>` → the ledger history, `GET ${API}/wallet/balances` (admin) → everyone's, `POST ${API}/wallet/transfer {from, to, amount}` (admin) moves balance between accounts (guarded). `currency` namespaces independent balances (points vs credit vs a giftcard); a gift card is just an `account` keyed by the card code. Use THIS for any earn/spend balance instead of a number column that races or goes negative. PROMOTIONS / PROMO CODES (a real discount engine — the discount is computed server-side, unlike the simpler `/coupons`): an admin mints `POST ${API}/promotions {code, kind:'percent'|'fixed'|'free_shipping', value, min_order?, max_uses?, per_user_max?, starts?, expires?}`. A shopper PREVIEWS with `POST ${API}/promotions/<code>/validate {order_total, account?}` → `{valid, discount, free_shipping, reason?}` (reasons: invalid/expired/not_started/min_order/exhausted/user_limit). Applying is server-authoritative: `POST ${API}/promotions/<code>/redeem {order_total, account?, order_ref?}` (ADMIN) records a redemption ATOMICALLY so a limited code can't be oversold or reused past its per-user cap. Codes are case-insensitive. `GET ${API}/promotions[/<code>]` (admin) shows usage. Use `/promotions` when you need computed percent/fixed discounts + min-order + usage caps; use the simpler `/coupons` for an opaque discount blob. ENTITLEMENTS / SUBSCRIPTIONS (gate 'Pro' or a feature per account, with expiry — the membership STATE, not the payment): an admin grants `POST ${API}/entitlements {account, feature?, plan?, status?, expires?, meta?}` (feature omitted = the whole-account plan). The app gates with `GET ${API}/entitlements/check?account=<a>[&feature=]` → `{active, plan, expires, status}` where `active` is true only if status is active AND within any start/expiry window (so an expired plan reads inactive automatically). `GET ${API}/entitlements?account=<a>` lists all of an account's, `DELETE ${API}/entitlements/<feature>?account=` revokes. A member checks/reads their OWN; an admin any. Renew by re-granting (upsert). Use THIS to unlock features by plan instead of a boolean column you have to expire by hand. (Payments themselves are Stripe at the platform level.) REFERRALS / INVITE ATTRIBUTION (a 'refer a friend' program — who invited whom, a referral leaderboard): any signed-in member. `POST ${API}/referrals/code` returns MY stable referral code (deterministic, get-or-create — share it in an invite link). A newly-signed-up member attributes themselves with `POST ${API}/referrals/claim {code}` → `{referrer_id}` — this can happen exactly ONCE per member (a second claim, or switching codes, → 409; you can't claim your OWN code → 400; unknown → 404), enforced atomically so it can't be double-counted under races. `GET ${API}/referrals/mine` → `{code, referred_count, referred:[{user_id, at}]}` (who I've brought in), and `GET ${API}/referrals/leaderboard[?limit=]` (ADMIN) ranks the top referrers. Use THIS for invite/referral tracking instead of a nullable `referred_by` column that anyone can overwrite. Grant the reward yourself (wallet/points/entitlement) off the claim. FEATURE FLAGS (turn features on/off per user without a redeploy — gradual rollouts, betas, kill switches): an admin configures flags, every member evaluates which are on for THEM. `POST ${API}/flags {key, enabled?, rollout?(0-100), roles?[], teams?[], value?}` (ADMIN) upserts a flag; `rollout` is a percent (a member is deterministically bucketed by a stable hash of key+their id, so raising the % only ever adds users, and a member is consistently in/out), `roles`/`teams` restrict it to certain roles or teams, and `value` is an optional JSON payload delivered when the flag is on (for a variant/config). The app gates with `GET ${API}/flags/eval?key=<k>` → `{on, value}` for one flag, or `GET ${API}/flags/eval` → `{flags:[{key, on, value}]}` for all — open to any signed-in member. An unknown/deleted flag evaluates to `on:false` (never errors), so you can gate on any key safely. `GET ${API}/flags` (admin) lists every flag + config, `DELETE ${API}/flags/<key>` (admin) removes one. A flag is ON iff enabled AND role matches AND team matches AND the member is in the rollout bucket. Use THIS for staged rollouts / betas / A-B gating instead of a hardcoded boolean, and DISTINCT from the static public `/config` KV (that's read verbatim; this is evaluated per user). SAVED SEARCHES (per-member — a member names a filter over a table and re-runs it, e.g. their open tickets, listings under a price cap, a saved report): `POST ${API}/searches {name, table, query}` saves it (query is a list query-string like `where=status:eq:open&sort=created_at&order=desc`, or an object `{where:[…], q, sort, order, limit}`); `GET ${API}/searches[?table=]` lists mine; `GET ${API}/searches/<name>/run[?limit=&offset=]` RUNS it → `{total, rows}`; `GET ${API}/searches/<name>` returns its metadata; `DELETE ${API}/searches/<name>` removes it. Each member's searches are PRIVATE (keyed to them — another member's is a 404 to you), and RUN executes under the CALLER's own read scope (their own rows on a `user` table, public rows on display/feed, refused on write-only `collect`; trashed/expired/unpublished/archived rows always hidden) — so a saved search can never surface a row the member couldn't read directly. Use THIS to let members keep reusable filtered views instead of re-passing the same query params every time; it's the per-member cousin of admin `/segments` (which build audiences over ALL rows). RATINGS & REVIEWS (star ratings + written reviews on any subject — products, listings, anything): `POST ${API}/reviews {subject, rating(1-5), title?, body?}` upserts MY review for a subject (one per member; re-posting edits it). Reads are PUBLIC: `GET ${API}/reviews?subject=<s>[&sort=recent|top&limit=&offset=]` lists them and `GET ${API}/reviews/summary?subject=<s>` returns `{count, average, distribution:{1..5}}` computed in SQL. `GET ${API}/reviews/mine?subject=<s>` is my own review; `DELETE ${API}/reviews?subject=<s>` removes mine (an admin may add `&user=<id>` to moderate any). Use THIS for a rating/review widget instead of a plain table — the one-per-member rule and the aggregate are handled. WAITLIST / QUEUE (a fair first-come signup queue — early access, a drop, limited slots): any member. `POST ${API}/waitlist/<list>/join` puts me on the named list once → `{position, seq}`; `GET ${API}/waitlist/<list>/me` is my live `{status, position}` (position advances as people ahead leave or are let in); `POST ${API}/waitlist/<list>/leave` removes me. An admin runs it: `GET ${API}/waitlist/<list>` is the ordered queue + counts, and `POST ${API}/waitlist/<list>/claim {user?, as?}` lets in the front (or a named member), dropping them from the waiting count so everyone behind moves up. Positions are atomic (no two members ever get the same slot). Use THIS for any waitlist/queue instead of a table you hand-rank. DAILY CHECK-IN STREAKS (habit tracker / gamification — a Duolingo-style streak): any member. `POST ${API}/streak/checkin` records today (at most once per UTC day; a repeat is a harmless no-op) → `{checked_in, current_streak, longest_streak, total}`; `GET ${API}/streak` returns those plus the recent check-in days. current_streak is the run ending today or yesterday, longest_streak the best ever. Use THIS for a streak/consistency feature instead of computing consecutive days yourself. REMINDERS (per-member scheduled notes the app polls for — follow-ups, nudges, due dates), all PRIVATE to the owner: `POST ${API}/reminders {remind_at, note, subject?}` schedules one; `GET ${API}/reminders` lists mine soonest-first (`?upcoming=1` future only, `?done=1` completed); `GET ${API}/reminders/due` returns the ones that have come due (poll this to surface them); `POST ${API}/reminders/<id>/done` completes one; `PATCH ${API}/reminders/<id>` edits; `DELETE ${API}/reminders/<id>` removes. Use THIS for reminders/follow-ups instead of a table you filter by time by hand — to actually alert at the due time, poll /due and raise an in-app notification (or wire a scheduled edge function). THREADED COMMENTS (a comment section on any record — posts, listings, tasks): `POST ${API}/comments {table, row, body, parent?}` adds a comment (or a reply via parent) on a (table,row); `GET ${API}/comments?table=<t>&row=<id>` returns the thread oldest-first (PUBLIC — each row carries parent_id so the client nests replies), and `GET ${API}/comments/count?table=<t>&row=<id>` the live count. A member edits their own with `PATCH ${API}/comments/<id> {body}` and soft-deletes with `DELETE ${API}/comments/<id>` (an admin may delete any). A soft-deleted comment stays as a tombstone only while it still has replies, else it disappears. Use THIS for a comment/discussion thread on any record instead of a plain table. SURVEYS / NPS / CSAT (collect a satisfaction score + comment and get the aggregate): `POST ${API}/surveys/<survey> {score, comment?, max?}` records MY response (one per member per survey; re-submitting edits it; score 0..max, max default 10). `GET ${API}/surveys/<survey>/mine` is my own response. The owner reads the aggregate `GET ${API}/surveys/<survey>/summary?kind=nps|csat|avg` (ADMIN) — nps returns promoters/passives/detractors + the NPS number, csat the average + %satisfied, avg the mean — and the raw `GET ${API}/surveys/<survey>/responses` (ADMIN). Use THIS for an NPS/CSAT/feedback score instead of a plain table — the one-per-member rule and the NPS/CSAT math are handled (distinct from /reviews, which is a public per-subject star rating). AT-MENTIONS (a who-tagged-me inbox — flag a member they were @-mentioned in a comment/post/task): when your app detects an @tag, `POST ${API}/mentions {user, ref_table?, ref_id?, context?}` records it (user = the mentioned member's id). The mentioned member reads `GET ${API}/mentions/mine[?unseen=1]` (newest-first), `GET ${API}/mentions/unseen-count` for a badge, and clears them with `POST ${API}/mentions/<id>/seen`, `POST ${API}/mentions/seen-all`, or `DELETE ${API}/mentions/<id>`. Mentions are private to the recipient. Use THIS for @mention notifications instead of scanning text yourself. EVENT REGISTRATION WITH CAPACITY (ticketed events, class signups, limited slots — sign-ups that stop at a hard cap and auto-waitlist): an admin defines an event with `POST ${API}/events/<event> {title?, capacity, starts_at?}`. A member registers with `POST ${API}/events/<event>/register` → `{status:'registered'|'waitlisted', seq}` — the seat-vs-waitlist decision is atomic so the cap is never exceeded. `GET ${API}/events/<event>` is the public status `{capacity, registered, waitlisted, spots_left}`, `GET ${API}/events/<event>/me` is my registration (+ waitlist position), `POST ${API}/events/<event>/cancel` frees my seat and auto-promotes the next person off the waitlist, and `GET ${API}/events/<event>/roster` (ADMIN) is the full list. Use THIS for anything with a fixed number of spots instead of a plain table — the no-overbooking guarantee + the waitlist promotion are the point. (For an UNBOUNDED signup queue use /waitlist; for a simple yes/no RSVP with no cap use /reactions.) FUNDRAISING / GOAL PROGRESS (a crowdfunding thermometer, a tip jar, a pledge drive with a target): an admin sets `POST ${API}/goals/<goal> {title?, target, currency?, deadline?}`. A member contributes with `POST ${API}/goals/<goal>/contribute {amount, note?}` → `{raised, progress_pct}`. `GET ${API}/goals/<goal>` is the public progress `{target, raised, progress_pct, met, contributions, contributors}` and `GET ${API}/goals` lists every goal — perfect for a progress bar. The per-contributor amounts are private (`GET ${API}/goals/<goal>/contributions` is ADMIN-only). Money is exact to the cent and over-funding past 100% is allowed. Use THIS for a fundraising/goal bar instead of summing a table yourself. (Contributions here are amounts you record — to actually CHARGE money, wire a Stripe checkout edge function and record the paid amount here on the webhook.) NOTIFICATION PREFERENCES + QUIET HOURS (let members choose which notifications they get + a do-not-disturb window): a member reads `GET ${API}/notify-prefs` and updates `POST ${API}/notify-prefs {channels?, types?, quiet_start?, quiet_end?, tz_offset?}` — channels/types are maps like `{email:true, sms:false}` and `{marketing:false, mentions:true}` (on unless set false); quiet_start/quiet_end are local hours 0–23, tz_offset is minutes from UTC. Before sending, the app asks `GET ${API}/notify-prefs/should-send?type=<t>&channel=<c>` → `{send, reasons}` (the sender, as ADMIN, may check any member with `&user=<id>`) — send is true only if that type + channel are enabled AND the member isn't in their quiet window right now (handles windows that wrap past midnight and the member's timezone). Use THIS to respect notification opt-outs + quiet hours instead of blasting everyone. ANNOUNCEMENTS (a site-wide banner/notice an admin broadcasts to everyone, dismissible per member — maintenance notices, new-feature banners, alerts): an admin posts `POST ${API}/announcements {title?, body, level?, starts_at?, ends_at?}` (level e.g. info/warning/critical; starts_at/ends_at bound when it's live). A member fetches `GET ${API}/announcements` → the ACTIVE announcements they haven't dismissed yet, and dismisses one with `POST ${API}/announcements/<id>/dismiss` (per-member — dismissing hides it only for them). An admin lists everything with `GET ${API}/announcements/all` and removes one with `DELETE ${API}/announcements/<id>`. Use THIS for a dismissible notice banner instead of hardcoding one — scheduling + per-member dismissal are handled. IDEMPOTENCY KEYS (make a repeated action run only ONCE — safe retries for a payment, an order, a webhook that might be delivered twice): before doing the work, the app calls `POST ${API}/idempotency/<key> {response?}` with a unique key. The FIRST call returns `{first:true}` (so you do the work, and can pass the result as `response` to store it); any REPLAY of the same key returns `{first:false, response:<the stored result>}` so you skip re-doing it and return the original result. `GET ${API}/idempotency/<key>` peeks, `DELETE` clears it. Keys are per-member. Use THIS to guard anything that must not double-execute instead of hoping the client never retries. CATEGORIES / TAXONOMY TREE (a nested category hierarchy — blog categories, product categories, folders): an admin builds it with `POST ${API}/categories {name, slug?, parent?, sort?}` (parent = a parent category's id; slug auto-derives from the name). Anyone reads `GET ${API}/categories` → `{flat, tree}` (the nested tree, ready to render a menu) and `GET ${API}/categories/<id>` → `{category, path, children}` (path = the breadcrumb root→node). An admin edits with `PATCH ${API}/categories/<id>` (reparenting is cycle-guarded) and removes with `DELETE ${API}/categories/<id>` (its children reparent up to its parent). Use THIS for a category/folder hierarchy instead of a flat table with a parent column you assemble by hand. NAMED LISTS / COLLECTIONS (a member curates named lists of items — a wishlist, a watchlist, a playlist, saved items across tables): `POST ${API}/lists {name, kind?, public?}` creates a list; `GET ${API}/lists` is my lists (with item counts); `GET ${API}/lists/<id>` is a list + its items (mine, or anyone's if it's public — a shareable wishlist); `PATCH ${API}/lists/<id> {name?, public?}` renames or toggles sharing; `DELETE ${API}/lists/<id>` removes it. Add/remove items with `POST ${API}/lists/<id>/items {table?, row?, note?}` and `DELETE ${API}/lists/<id>/items/<itemId>` — an item references a row (table+row) and/or carries a note. Lists are private to the owner unless made public. Use THIS for user-curated named collections (distinct from a single flat bookmarks toggle — this is multiple named lists with ordered items). ONE-TIME CODES / OTP (verify a short code — confirm a phone/email, or gate a sensitive action): `POST ${API}/otp/generate {purpose, identifier, ttl?, length?, max_attempts?}` makes a code and returns it ONCE (your app sends it to the user via an email/SMS edge function — it's stored only hashed); then `POST ${API}/otp/verify {purpose, identifier, code}` checks it → `{verified:true}` (single-use), or a miss returns `{verified:false, attempts_left}`, an expired code → 400, and too many wrong tries → 429 (locked — request a new one). `purpose` groups codes (e.g. phone, email-change) and `identifier` is what's being verified. Use THIS for confirmation codes instead of rolling your own — expiry, the attempt lockout, single-use, and hashing are handled (sending the code is yours: return it to your edge function and email/SMS it). SAVED ADDRESSES / ADDRESS BOOK (a member's shipping/billing addresses with one default — for checkout, profiles): `POST ${API}/addresses {label?, name?, line1, line2?, city?, region?, postal?, country?, phone?, default?}` saves one (line1 required; the first is auto-default); `GET ${API}/addresses` lists mine (default first); `GET`/`PATCH`/`DELETE ${API}/addresses/<id>` read/edit/remove one; `POST ${API}/addresses/<id>/default` makes it the default (exactly one, set atomically). Private per member. Use THIS for a saved-addresses picker instead of keeping the one-default invariant on a plain table yourself. PER-MEMBER SETTINGS (each member's own key→value preferences — theme, saved layout, app options; distinct from the public site `/config` and from `/notify-prefs`): `GET ${API}/settings` returns all my settings as `{key:value}`; `GET ${API}/settings/<key>` one; `POST ${API}/settings/<key> {value}` sets one (value is any JSON — string/number/object/array); `POST ${API}/settings {k:v, …}` bulk-sets several; `DELETE ${API}/settings/<key>` removes one. Private per member. Use THIS for per-user app settings instead of stuffing them in a profile column. RECENTLY-VIEWED (a per-member ring of the rows they last looked at — recently-viewed products, recent documents): call `POST ${API}/recent {table, row}` when a member opens a record; `GET ${API}/recent[?table=&limit=]` returns their recently-viewed newest-first (re-viewing bumps a row to the top, no duplicates, pruned to the last 200); `DELETE ${API}/recent[?table=&row=]` clears one or all. Private per member. Use THIS for a recently-viewed rail instead of tracking it in the browser (it follows the member across devices). FAQ / KNOWLEDGE BASE (a help section — questions & answers, categorized): an admin manages entries with `POST ${API}/faq {question, answer, category?, sort?, published?}`, `PATCH ${API}/faq/<id>`, `DELETE ${API}/faq/<id>`. Anyone reads the published ones: `GET ${API}/faq[?category=&q=]` (q searches the question + answer), `GET ${API}/faq/categories` lists the categories, and an admin sees drafts too via `GET ${API}/faq/all`. Use THIS for a FAQ/help page instead of a plain table — publish gating + search + categories are handled. BUSINESS HOURS / OPEN-NOW (weekly opening hours + holidays + an are-we-open check — for a local-business site): an admin sets weekly intervals with `POST ${API}/hours {dow(0=Sun..6=Sat), open, close}` (open/close as HH:MM; a day may have several intervals) and holiday/special overrides with `POST ${API}/hours/special {date, closed?, open?, close?}`. Anyone reads `GET ${API}/hours` → `{weekly, specials}` (render an hours table) and checks `GET ${API}/hours/open?tz=<minutesFromUTC>` → `{open, reason, closes_at}` (pass the business's timezone offset; a date override wins over the weekly schedule). Use THIS for opening hours + an open/closed badge instead of hardcoding them. A/B EXPERIMENTS (test two designs and measure which converts better — a step past a simple on/off flag): an admin defines `POST ${API}/experiments/<key> {variants:[{name, weight?}] or ['a','b'], enabled?}`. In your page, `GET ${API}/experiments/<key>/assign` → `{variant}` assigns the member to a variant deterministically + stickily (weighted; the same member always gets the same one) and records the exposure — render that variant. When the goal happens (signup, purchase), call `POST ${API}/experiments/<key>/convert`. The admin reads `GET ${API}/experiments/<key>/results` → per-variant `{exposures, conversions, rate}` to pick the winner. Use THIS to A/B-test instead of guessing; use `/flags` when you just need an on/off or % rollout with no conversion measurement. NAMED COUNTERS (atomic tallies — page-hit counts, download counts, poll votes, a live signup counter): any signed-in member `POST ${API}/counters/<name>/incr {by?}` → `{n}` bumps a named integer counter atomically (`by` defaults to 1, may be negative); anyone reads `GET ${API}/counters/<name>` → `{n}` (0 if unset) or `GET ${API}/counters` for all of them. An admin can `POST ${API}/counters/<name> {value}` to set it or `DELETE` it. Use THIS for a shared running total instead of a table you COUNT() every read — the increment is a single atomic write and the read is instant. REDIRECTS (a link-shortener or an old-URL → new-URL map with hit tracking): an admin `POST ${API}/redirects {from, to, code?}` maps a path (a leading slash is added if missing) to any URL/path with an HTTP code (301 default · 302/307/308); re-posting the same `from` updates it. At runtime `GET ${API}/redirects/resolve?from=<path>` → `{to, code}` (404 if none) and counts the hit. Admin lists all with hit counts via `GET ${API}/redirects` and removes one with `DELETE ${API}/redirects/<id>`. Use THIS for vanity links, campaign short-URLs, or migrating old paths. BADGES / ACHIEVEMENTS (award members earned badges — Early Adopter, Top Contributor, a course-completion mark): an admin defines one `POST ${API}/badges/<key> {name, description?, icon?}` (re-post to edit), then awards it to a member `POST ${API}/badges/<key>/award {user:<memberId>}` (idempotent — awarding twice is a no-op) and can revoke `DELETE ${API}/badges/<key>/award/<memberId>`. Anyone reads the catalog `GET ${API}/badges` → each badge + its holder count; a member reads their own earned set `GET ${API}/badges/mine`; an admin sees who holds one via `GET ${API}/badges/<key>/holders`. Deleting a badge removes all its awards. Use THIS for gamification/recognition instead of a boolean column per achievement. NAV / MENU BUILDER (a header/footer/sidebar navigation the owner can edit without touching code — ordered, nestable links): an admin adds items `POST ${API}/menus/<menu>/items {label, url?, parent?, position?}` → `{id}` (menu is any key like header/footer; `parent` is another item id in the SAME menu for a dropdown; `position` sorts, may be negative), edits with `PATCH ${API}/menus/<menu>/items/<id> {label?, url?, parent?, position?}`, removes with `DELETE ${API}/menus/<menu>/items/<id>` (also removes its descendants). Your page reads the whole thing as a nested tree: `GET ${API}/menus/<menu>` → `{items:[{id,label,url,position,children:[…]}]}` (already ordered + nested — render it recursively), and `GET ${API}/menus` lists the menu keys. Use THIS for editable navigation instead of hardcoding links. SEO METADATA (per-page title / meta description / OG share image / canonical / keywords the owner can set per record): an admin upserts `POST ${API}/seo {entity, ref, title?, description?, image?, canonical?, keywords?}` where (entity,ref) identifies the thing (entity:`product` ref:`42`, or entity:`page` ref:`/about`). Your page reads `GET ${API}/seo?entity=product&ref=42` → `{meta:{title,description,image,canonical,keywords}}` (or `meta:null`) and injects those into the document <head> for rich search results + social cards. Admin `GET ${API}/seo/all` lists every row; `DELETE ${API}/seo?entity=&ref=` clears one. Use THIS so each page/product has its own share preview instead of one generic site-wide tag. REUSABLE CONTENT SNIPPETS (named chunks of copy the owner edits in one place and you drop in many — a promo banner, a footer blurb, boilerplate terms): an admin upserts `POST ${API}/snippets/<slug> {title?, body, format?, published?}` (set `published:false` to stage a draft). Your page pulls one with `GET ${API}/snippets/<slug>` → `{snippet:{title,body,format}}` (published only — a draft 404s) and renders `body` (use `format` to know if it is html/markdown/plain). `GET ${API}/snippets` lists published slugs; admin `GET ${API}/snippets/all` includes drafts. Use THIS for owner-editable copy that appears in several spots instead of hardcoding the text. SUPPORT TICKETS (a help desk — customers open tickets, staff triage + reply on a thread): a signed-in member opens one `POST ${API}/tickets {subject, body, priority?}` (priority low/normal/high/urgent) → `{id}`. They list their own with `GET ${API}/tickets` and read one + its whole reply thread with `GET ${API}/tickets/<id>` → `{ticket, messages:[…]}`. Either side adds a reply `POST ${API}/tickets/<id>/messages {body, internal?}` — a member replying to a resolved/closed ticket auto-REOPENS it. Staff (an ADMIN Bearer) see EVERY ticket via `GET ${API}/tickets[?status=open&assignee=<id>&mine=1]`, can post an `internal:true` note the requester never sees, and triage with `PATCH ${API}/tickets/<id> {status?, priority?, assignee?}` (status open/pending/resolved/closed — resolving/closing stamps closed_at; assignee is a staff user id). A requester can only see/reply to their OWN ticket; internal notes are admin-only. Use THIS for customer support instead of a plain contact-form table — you get status, assignment, threaded replies, and staff-private notes. CANNED RESPONSES (a staff library of reusable reply templates to paste into ticket answers): ADMIN-only — `POST ${API}/canned/<key> {title?, body}` saves one, `GET ${API}/canned` lists them, `GET ${API}/canned/<key>` reads one, `DELETE` removes it. Build a staff-side picker that inserts `body` into the ticket reply box. Not visible to members. HELP-ARTICLE VOTES (a `Was this helpful? Yes / No` widget under a help/FAQ article): a signed-in member casts `POST ${API}/helpful/<article> {helpful:true|false}` (one vote each, changeable) and can retract with `DELETE ${API}/helpful/<article>`. Anyone reads the tally `GET ${API}/helpful/<article>` → `{yes, no, total, score, mine}` (score = % who said yes; `mine` = the caller past vote or null). `<article>` is any stable id/slug/path for the page. Use THIS to measure which docs help instead of a raw counter — you get yes vs no, a helpful %, and per-user dedup. STATUS PAGE / INCIDENTS (a service status page — staff post outages with a live timeline, visitors read + subscribe): an ADMIN opens an incident `POST ${API}/incidents {title, body?, impact?, status?}` (impact none/minor/major/critical; status investigating/identified/monitoring/resolved — the `body` seeds the first timeline entry) and posts progress with `POST ${API}/incidents/<id>/updates {status?, body}` (a new status advances the incident; `resolved` stamps it done). Visitors read `GET ${API}/incidents[?active=1]` (active=1 hides resolved ones) and one incident with its full timeline `GET ${API}/incidents/<id>` → `{incident, updates:[…]}`. Anyone subscribes for notifications `POST ${API}/incidents/subscribe {email}` (DELETE with `?email=` to stop); the admin reads the notify list `GET ${API}/incidents/subscribers`. Admin also `PATCH ${API}/incidents/<id> {title?, impact?}` + `DELETE`. Use THIS for an uptime/status page instead of a manual banner — you get a timeline, impact levels, and an email list. FEEDBACK BOARD (a public idea/feature-request board with upvotes + a roadmap — like a mini Canny): a signed-in member submits `POST ${API}/feedback {title, body?}` (their own submission auto-counts as the first upvote). Anyone browses `GET ${API}/feedback[?status=&sort=top|new]` → each post with its `votes` count + `mine` (did the caller vote); a member upvotes `POST ${API}/feedback/<id>/vote` and removes it with DELETE (one vote each, idempotent). Read one with `GET ${API}/feedback/<id>`. Staff (ADMIN) set the roadmap status `PATCH ${API}/feedback/<id> {status}` (open/planned/in_progress/done/declined) — sort/filter by it to render roadmap columns. The author OR an admin can `DELETE ${API}/feedback/<id>`. Use THIS for feature-request voting instead of a plain list — you get dedup upvotes, a top sort, and a public roadmap. COUNTDOWN / LAUNCH TIMER (a live countdown to a launch or sale — server-authoritative so every visitor sees the same time left, no client-clock drift): an ADMIN sets one `POST ${API}/countdowns/<key> {title?, target}` where `target` is any ISO datetime; your page reads `GET ${API}/countdowns/<key>` → `{target_at, remaining, expired}` (remaining = whole SECONDS left, 0 once past; `expired` flips true) and ticks it down locally, re-syncing from the server. `GET ${API}/countdowns` lists them; admin `DELETE` removes one. Use THIS for launch/sale timers instead of hardcoding a date in the page so the deadline is editable + drift-free. SHIPPING-RATE CALCULATOR (compute a checkout shipping cost from weight + order subtotal per destination zone): an ADMIN builds the rate table `POST ${API}/shipping/rates {zone, label?, min_weight?, max_weight?, min_subtotal?, max_subtotal?, rate, free_over?}` — one row per tier (a `zone` is any name you map the customer to, like US/EU/domestic; bands are inclusive; `rate` is the flat cost; `free_over` waives it above a subtotal). At checkout your page asks `POST ${API}/shipping/quote {zone, weight?, subtotal?}` → `{rate, rate_c, free, matched}` — the server picks the CHEAPEST tier whose weight AND subtotal bands contain the order, and returns 0 with `free:true` when the subtotal clears that tier free_over. Admin `GET ${API}/shipping/rates[?zone=]` + `DELETE ${API}/shipping/rates/<id>`. Use THIS for shipping cost instead of hardcoding a flat number — bands + free-over + per-zone are handled server-side. QUOTE / ESTIMATE BUILDER (a sales quote a business sends a customer, who accepts it online — line items, a total, a shareable link): an ADMIN creates one `POST ${API}/quotes {customer?, currency?, notes?, expires?, lines:[{description, qty?, unit}]}` and the SERVER totals it (qty × unit, to the cent) → `{id, number, token, total}`. The `token` is a public share link: the customer opens `GET ${API}/quotes/view/<token>` → `{quote, lines}` (no internal fields) and accepts/declines with `POST ${API}/quotes/view/<token>/respond {accept:true|false}` (once; blocked past `expires`). Staff manage with `GET ${API}/quotes[?status=]`, `GET ${API}/quotes/<id>` (+ lines), `PATCH ${API}/quotes/<id> {status?, customer?, notes?, lines?}` (re-posting `lines` re-totals), `DELETE`. Statuses: draft/sent/accepted/declined/expired. Use THIS for estimates/proposals instead of a flat table — totals, a customer-facing accept link, and expiry are built in. GIVEAWAY / SWEEPSTAKES (run a prize draw — members enter, you pick random winners fairly): an ADMIN opens one `POST ${API}/giveaways/<key> {title?}`; a signed-in member enters once with `POST ${API}/giveaways/<key>/enter` (idempotent, only while open). Anyone reads `GET ${API}/giveaways/<key>` → `{status, entries, winners, mine}` (mine = did the caller enter). When entries close, the admin draws `POST ${API}/giveaways/<key>/draw {count?}` → `{winners:[userIds]}` picked with a cryptographically-random shuffle (each winner a real distinct entrant), which flips the giveaway to `drawn`. `GET ${API}/giveaways` lists them; admin `DELETE`. Use THIS for raffles/sweepstakes instead of rolling your own random pick — entry dedup + a fair CSPRNG draw are handled. LEAD CAPTURE + SCORING (a contact/lead form that feeds a sales inbox — capture prospects, then score + triage them): your PUBLIC page posts the form with NO auth `POST ${API}/leads {name?, email?, phone?, company?, source?, notes?}` → `{id}` (at least one of name/email/phone required; heavily rate-limited against spam). Staff (ADMIN) work the inbox: `GET ${API}/leads[?status=&min_score=&sort=score|new]` (statuses new/contacted/qualified/unqualified/converted), `GET ${API}/leads/<id>`, bump a leads temperature `POST ${API}/leads/<id>/score {by}` (add/subtract points), `PATCH ${API}/leads/<id> {status?, score?, owner?, notes?, …}` to qualify/assign, `DELETE`. Use THIS for a contact/lead form instead of a plain table — you get spam-throttled public capture plus scoring, ownership, and a status funnel. DEAL PIPELINE / KANBAN (a sales CRM board — deals move across stages, drag between columns, see totals per column): ADMIN-only. Create `POST ${API}/deals {title, stage?, amount?, currency?, contact?, lead?}` (stage is any label, normalized to a slug; amount to the cent). Render the board with `GET ${API}/deals/board` → `{stages:[{stage, count, total, deals:[…]}]}` (open deals grouped by stage with a summed value — one column each). Drag = `PATCH ${API}/deals/<id> {stage?, position?}`; close with `{status:won|lost}` (stamps closed_at and drops it off the open board — filter `GET ${API}/deals?status=won` for closed ones). Also `GET ${API}/deals[?stage=&status=]`, `GET ${API}/deals/<id>`, `DELETE`. Use THIS for a sales pipeline instead of a status column — the board grouping + per-stage totals + open/won/lost are built in. NEWSLETTER SIGNUP (double opt-in) (a mailing-list signup that confirms the email before adding it — the compliant way): your page posts `POST ${API}/newsletter/subscribe {email, name?}` → `{token}`; EMAIL that token as a confirm link, and when the visitor clicks it your page calls `POST ${API}/newsletter/confirm {token}` → confirmed (the token is single-use). Anyone can `POST ${API}/newsletter/unsubscribe {email}` (or `{token}`). Staff read the list `GET ${API}/newsletter[?status=]` (confirmed by default) and `GET ${API}/newsletter/stats` → `{pending, confirmed, unsubscribed}`. Use THIS for a mailing list instead of dropping raw emails in a table — double opt-in (pending→confirmed), unsubscribe, and stats are handled. POINTS / KARMA (a gamification points balance per member — reward XP/karma/coins, show a top-users board): ADMIN grants or deducts `POST ${API}/points/award {user, amount, reason?, ref?}` → `{balance}` (amount may be negative; every change is an append-only ledger entry, so balance = sum of all deltas — never a lossy overwrite). A member reads their own `GET ${API}/points/me` → `{balance, history}`; an admin reads anyones `GET ${API}/points/<userId>`. Anyone shows the ranking `GET ${API}/points/leaderboard[?limit=]` → `[{rank, user_id, balance}]`. Use THIS for a karma/XP/coin balance instead of a number column — the ledger gives you an audit trail + a built-in leaderboard. (This is per-app play-money, separate from real billing credits.) LEADERBOARDS (a high-score / ranking board over ANY metric a member reports — game scores, steps, sales): an ADMIN defines a board `POST ${API}/leaderboards/<board> {mode?, title?}` where mode is how repeat submissions combine — `max` (keep the best, for high-scores), `sum` (accumulate, for step/point totals), or `last` (latest wins). A member reports a number `POST ${API}/leaderboards/<board>/submit {score}` → `{score, rank}` (the mode is applied atomically). Anyone reads `GET ${API}/leaderboards/<board>[?limit=]` → `{top:[{rank,user_id,score}], players, mine:{score,rank}}` (mine = the caller position if signed in). `GET ${API}/leaderboards` lists boards; admin `DELETE`. Use THIS for any ranked board instead of sorting a table yourself — pick the mode and per-member rank + top-N come for free. (Use `/points/leaderboard` specifically for the karma balance; use this for arbitrary metrics.) DAILY REWARD / STREAK (a once-a-day claim button that builds a login streak — daily bonus, check-in reward): a member calls `POST ${API}/daily/claim` → `{claimed, streak, day, reward}` (allowed once per UTC day; a second try the same day → 409). Claiming on consecutive days grows `streak`; MISSING a day resets it to 1. The `reward` scales with the streak (10 × min(streak,7)) — grant it however you like (e.g. pipe it into `/points/award`). Peek without claiming via `GET ${API}/daily` → `{streak, canClaim, lastClaim, nextReward}`. Use THIS for a daily check-in/bonus instead of tracking dates yourself — the per-day lock, streak math, and reset are handled server-side. CHALLENGES (a goal-with-a-deadline members work toward together — a step challenge, a reading goal, a 30-day streak event): an ADMIN defines one `POST ${API}/challenges/<key> {title?, description?, target, unit?, starts?, ends?}` (target is the number to reach; starts/ends bound an active window). A member logs progress `POST ${API}/challenges/<key>/progress {by}` (increment, floored at 0) or `{set}` (absolute) → `{progress, target, done}` — only while the challenge is active (before starts or after ends → 409). Anyone reads `GET ${API}/challenges/<key>[?limit=]` → `{challenge, active, participants, top:[{rank,user_id,progress}], mine:{progress,done}}`, and `GET ${API}/challenges` lists them; admin `DELETE`. Use THIS for a group goal/challenge instead of a plain counter — the target, active window, per-member progress, and a ranked board are built in. LEVELS / XP LADDER (turn a points/XP number into a named level with a progress bar — Bronze→Silver→Gold): an ADMIN defines the ladder `POST ${API}/levels {tiers:[{level, name?, min_xp}]}` (replaces the whole ladder). Resolve any XP value with `GET ${API}/levels/for?xp=<n>` → `{level, name, next, xp_to_next, progress}` (progress = % through the current band toward the next tier; top tier → next:null, progress:100), read the ladder with `GET ${API}/levels`, and get the SIGNED-IN members level straight from their points balance with `GET ${API}/levels/me`. Use THIS to render a level badge + progress bar instead of hardcoding thresholds — pair it with `/points` so a members level tracks their karma automatically. DASHBOARD LAYOUT (per-user) (let each user arrange their own dashboard — which tiles/widgets, in what order — and have it persist across devices): the signed-in member saves their layout `PUT ${API}/dashboard {tiles}` (tiles is ANY JSON you want — an array of tile configs, an object of settings, whatever your UI needs; up to 100k) and reads it back with `GET ${API}/dashboard` → `{tiles}` (null if never saved), or `DELETE ${API}/dashboard` to reset to default. Each member only ever sees their OWN layout. Use THIS to persist a per-user dashboard/settings/layout instead of localStorage so it follows the user across devices. TERMS ACCEPTANCE (make users accept your Terms/Privacy and know WHO accepted WHICH version — the compliance paper-trail): an ADMIN publishes the current version `POST ${API}/terms/<doc> {version, title?, url?, body?}` (doc is any key like tos/privacy). A signed-in member records acceptance `POST ${API}/terms/<doc>/accept` (stamps the version they saw), and your page checks `GET ${API}/terms/<doc>/status` → `{current_version, accepted_version, up_to_date}` — when you BUMP the version, everyone becomes up_to_date:false until they re-accept, so gate the app on it. Read the doc with `GET ${API}/terms/<doc>`; an admin pulls the audit trail with `GET ${API}/terms/<doc>/acceptances`. Use THIS instead of a single boolean — you get versioned re-consent + a per-user record of what they agreed to and when. AGE GATE (verify a visitor meets a minimum age from their date of birth — alcohol, 18+ content): your page posts `POST ${API}/agegate/check {dob, min?}` → `{age, pass, min}` (min defaults to 18; the age is computed month/day-aware). For a signed-in member a PASS is remembered (only the AGE is stored, never the raw DOB — a privacy choice) so you can skip re-asking: `GET ${API}/agegate/me` → `{verified, age}`. Use THIS for an age gate instead of trusting a client checkbox — the age math + a privacy-safe verified flag are server-side. PROFANITY FILTER (screen user text — usernames, comments, reviews — against a bad-word list): an ADMIN curates the list `POST ${API}/profanity/words {words:[…]}` (bulk, deduped) / `DELETE ${API}/profanity/words/<word>` / `GET ${API}/profanity/words`. Anywhere you accept text, check it `POST ${API}/profanity/check {text}` → `{clean, matches:[…], masked}` — matching is WHOLE-WORD + case-insensitive (so ‘classic’ never trips ‘ass’) and `masked` replaces hits with asterisks for display. Use THIS to moderate input instead of shipping a word list to the client — the list stays server-side and editable, and you get a ready-to-show masked string. HANDLE / SLUG RESERVATION (claim a unique username/handle/vanity-URL with no two-people-grab-the-same-name race): check availability `GET ${API}/reserve/<namespace>/<name>` → `{available}` (namespace groups names, e.g. handles/ vs events/), then a signed-in member claims it `POST ${API}/reserve/<namespace> {name}` → `{reserved}` or 409 if someone beat them to it (the claim is atomic, so it is truly first-come-first-served — safe to call the moment they pick a name). `GET ${API}/reserve/<namespace>/mine` lists what they hold; `DELETE ${API}/reserve/<namespace>/<name>` frees it (owner or admin). Names are case-insensitive. Use THIS to reserve a unique handle/slug instead of a SELECT-then-INSERT (which races) — the uniqueness is enforced atomically. IP ALLOW/DENY LIST (block abusive IPs or lock an area to an allowlist): an ADMIN adds rules `POST ${API}/ip-rules {ip, action, note?}` (action allow|deny) and removes them `DELETE ${API}/ip-rules/<ip>`; list with `GET ${API}/ip-rules`. Gate an action by checking `GET ${API}/ip-rules/check[?ip=]` → `{allowed, reason}` (defaults to the callers IP) — an explicit deny ALWAYS blocks, and the moment ANY allow rule exists it switches to allowlist mode (only listed IPs pass); with no rules everyone is allowed. Use THIS for IP blocking/allowlisting instead of hardcoding addresses — the deny-wins + allowlist logic is handled. QUEUE / TICKET DISPENSER (a take-a-number line — deli counter, support queue, event check-in): a member takes a ticket `POST ${API}/queue/<q>/take` → `{number, ahead, now_serving}` (numbers are handed out atomically in order); anyone shows the board `GET ${API}/queue/<q>` → `{now_serving, last_number, waiting}`; an operator (ADMIN) advances `POST ${API}/queue/<q>/call` → serves the next waiting number; a member checks their spot `GET ${API}/queue/<q>/mine` → `{ticket, ahead, now_serving}`; admin `DELETE ${API}/queue/<q>` resets. Use THIS for any take-a-number queue instead of a counter — monotonic tickets, now-serving, and per-person position are built in. SERVICE CATALOG (a menu of bookable/sellable services — a salon menu, a consultancy rate card, class offerings): an ADMIN manages it `POST ${API}/services {name, description?, duration?, price?, currency?, category?, active?, position?}` (duration in minutes, price in your normal units — stored to the cent), `PATCH ${API}/services/<id>`, `DELETE`. Your page renders `GET ${API}/services[?category=]` → active services only (each `{id, name, description, duration_min, price, category}`, ordered by position); set `active:false` to hide one without deleting (admin can still see all with `?all=1`). Read one with `GET ${API}/services/<id>`. Use THIS for a services/pricing menu instead of a plain table — active/hidden, categories, ordering, and to-the-cent prices are handled (pair with `/bookings` to actually book one). MEDIA METADATA (keep alt-text / captions / credits with your images so they travel with the file — accessibility + attribution): an ADMIN saves `POST ${API}/media-meta {key, alt?, caption?, credit?, tags?, width?, height?}` where `key` is the image URL (or an id). Your page reads it back `GET ${API}/media-meta?key=<url>` → `{meta:{alt, caption, credit, tags, width, height}}` and drops `alt`/`caption` into the <img>/figure. An admin lists the library `GET ${API}/media-meta[?tag=]` (filter by tag). Use THIS so every image has real alt text + a caption for a11y/SEO instead of leaving them bare — the descriptive data lives with the asset, not hardcoded in one page. SHARE COUNTERS (a ‘shared 1.2k times’ badge per page/post, split by network): when a visitor shares, bump the tally `POST ${API}/share-counts/increment {url, network}` → `{count, total}` (network is twitter/facebook/etc, normalized). Show the number with `GET ${API}/share-counts?url=<u>` → `{total, by_network}`, or a most-shared list with `GET ${API}/share-counts/top[?limit=]`. Use THIS for social-share counts instead of relying on each network’s own widget — you own the number, can show a combined total, and can rank your most-shared content. A/B SIGNIFICANCE (is variant B really better, or just noise? — a proper stats test on your experiment numbers): POST the two variants counts `POST ${API}/stats/significance {a:{visitors, conversions}, b:{visitors, conversions}, confidence?}` → `{a:{rate}, b:{rate}, uplift, z, p_value, significant, winner}`. It runs a two-proportion z-test (default 95% confidence): `significant:true` means the difference is unlikely to be chance, `winner` names the better variant (or null if it is a tie), `uplift` is B relative to A. Stateless — pass your own tallies (e.g. from `/experiments/<key>/results` or your own counts). Use THIS before calling an A/B test instead of eyeballing the percentages — it tells you if you actually have a result. TABLE OF CONTENTS (auto-build a jump-links TOC from an articles headings — no manual anchor list): POST the content `POST ${API}/toc {html}` or `{markdown}` (optional `min`/`max` heading levels) → `{headings:[{level, text, id}], tree}` where `id` is a URL-safe anchor slug (duplicates get -1/-2 suffixes) and `tree` is the headings nested by level. Render `tree` as a sidebar/inline TOC whose links point to `#<id>`, and add matching `id=` attributes to your rendered headings. Use THIS to generate a TOC + anchor ids from content instead of hand-maintaining them — it stays in sync with the actual headings. EMAIL OPEN/CLICK TRACKING (know who opened your email and what they clicked — open rate, click rate, CTR): in the HTML email you send, put a tracking pixel `<img src={API}/track-email/open?c=<campaign>&r=<recipient>>` (use a normal quoted src in your real HTML) (loading it logs an open and returns a 1x1 pixel), and wrap every link as `${API}/track-email/click?c=<campaign>&r=<recipient>&u=<url-encoded destination>` (clicking logs it then 302-redirects to the real URL). Then read results `GET ${API}/track-email/stats?campaign=<c>` (ADMIN) → `{opens, clicks, unique_opens, unique_clicks, ctr}`. Use THIS for email engagement metrics instead of a third-party tracker — the pixel + click-through + per-campaign stats are yours. SITEMAP + RSS FEED (give search engines a sitemap and readers an RSS feed of your content — auto-generated XML): an ADMIN registers each published page `POST ${API}/syndication {url, title?, summary?, published?, changed?, priority?}` (re-posting the same url updates it). The site then serves two live XML endpoints with NO extra work: `GET ${API}/sitemap.xml` (a standards sitemap for Google Search Console) and `GET ${API}/rss.xml[?title=&link=&desc=]` (an RSS 2.0 feed readers/aggregators can subscribe to). Both are public and always in sync with the registered items (XML is escaped for you). Admin lists the raw items with `GET ${API}/syndication` and removes one with `DELETE ${API}/syndication/<id>`. Use THIS for SEO sitemaps + a content RSS feed instead of hand-writing XML. BACK-IN-STOCK / PRICE-DROP ALERTS (a Notify me when this is available/cheaper button, then email everyone when it happens): a visitor subscribes `POST ${API}/notify-me/<item> {email, kind?}` (kind back_in_stock or price_drop; item is your product id/sku; deduped per email+kind). When the item restocks or drops in price, an ADMIN fires the alert `POST ${API}/notify-me/<item>/fire {kind?}` → `{emails:[…]}` — it returns everyone waiting AND marks them notified so nobody is emailed twice (then you send those emails, e.g. via an email function). Admin previews the waitlist `GET ${API}/notify-me/<item>[?kind=]`; a visitor can `DELETE ${API}/notify-me/<item>?email=`. Use THIS for restock/price alerts instead of a raw list — dedup, per-kind, and fire-once-per-person are handled. RECURRING DATES (turn a repeat rule into actual dates — a class every Mon/Wed, a monthly meetup, every-2-weeks): POST the rule `POST ${API}/recurring/expand {start, freq, interval?, count?, until?, byweekday?, from?, to?, limit?}` → `{occurrences:[ISO dates]}`. freq is daily/weekly/monthly; `interval` repeats every N (every 2 weeks); `byweekday` (0=Sun…6=Sat) picks days within a weekly rule (e.g. [1,3,5] = Mon/Wed/Fri); bound the series with `count` or `until`, and window the returned dates with `from`/`to`. Stateless — call it to render a schedule, populate a calendar, or seed booking slots. Use THIS to expand a recurrence instead of computing dates by hand — leap months, intervals, and multi-day weeks are handled. CAPACITY SLOTS / CLASS SIZES (book a limited-capacity session — a fitness class, a workshop, a tour with N seats — that can never oversell): an ADMIN creates a session `POST ${API}/slots {label?, starts?, capacity}`; a signed-in member grabs a seat `POST ${API}/slots/<id>/book` → `{seats_left}` or 409 when it is full (the capacity check is atomic, so simultaneous bookings can never exceed the cap), and frees it with `DELETE ${API}/slots/<id>/book`. Show availability with `GET ${API}/slots[?upcoming=1]` → each `{capacity, booked, available, full}`, or one session `GET ${API}/slots/<id>` (includes `mine`). Admin `PATCH ${API}/slots/<id>` (change capacity/time) + `DELETE`. Use THIS for anything with a headcount limit instead of a plain booking — overbooking is impossible by construction (distinct from /bookings, which is 1:1 appointments). PRODUCT BUNDLES / KITS (sell a set of items as one bundle and show the rolled-up price, optionally discounted): an ADMIN builds it `POST ${API}/bundles {name, description?, currency?, discount?, items:[{description, qty?, unit}]}` and the SERVER totals it → `{subtotal, total}` (total = subtotal − discount, floored at 0). Your page renders `GET ${API}/bundles[?active=1]` (each with its totals) and one bundle `GET ${API}/bundles/<id>` → `{bundle, items, subtotal, total}` to show whats inside and the savings. Admin `PATCH ${API}/bundles/<id>` (re-posting `items` re-rolls the total) + `DELETE`; `active:false` hides a bundle. Use THIS for kits/bundles/combo-deals instead of a flat price — the component list + rolled-up total + bundle discount are computed server-side. WIN/LOSS ANALYTICS (track why deals are won or lost and see your win rate by reason — sales insight): log each closed deal `POST ${API}/winloss {outcome, reason?, amount?, ref?}` (outcome won|lost) as it happens, then read `GET ${API}/winloss/summary[?from=&to=]` → `{won, lost, win_rate, won_value, lost_value, by_reason}` for a dashboard, or `GET ${API}/winloss[?outcome=]` for the raw entries. Admin-only. Use THIS to analyze win/loss reasons instead of counting a status column — win rate, revenue won vs lost, and the per-reason breakdown are aggregated for you (pairs with /deals). LOYALTY TIERS (a spend-based membership ladder — Bronze/Silver/Gold with perks that unlock as a customer spends more): an ADMIN defines the ladder `POST ${API}/loyalty/tiers {tiers:[{tier, name?, min_spend, benefits?}]}` (replaces it) and credits spend as customers buy `POST ${API}/loyalty/spend {user, amount}` → `{spend, tier, next, to_next}`. Show a members standing with `GET ${API}/loyalty/me` → `{spend, tier:{name,benefits}, next, to_next}` (how much more to the next tier) and the public ladder with `GET ${API}/loyalty/tiers`. Use THIS for a tiered loyalty/VIP program instead of a status column — the thresholds, current tier, benefits, and progress-to-next are computed from real spend. STORE CREDIT (issue refunds/gift-credit a customer can spend later, and let them redeem it at checkout — a real balance, not points): an ADMIN grants it `POST ${API}/store-credit/issue {user, amount, reason?}` → `{balance}`; the member spends it `POST ${API}/store-credit/redeem {amount}` → `{balance}` or 409 when they dont have enough (the balance can NEVER go negative — the check is atomic). A member sees `GET ${API}/store-credit/me` → `{balance, history}`; an admin audits anyone with `GET ${API}/store-credit/<userId>`. Every change is a ledger line, so the history is a full audit trail. Use THIS for refunds-as-credit / gift balances instead of a mutable number — issue + redeem + never-overdraw are handled (distinct from /wallet, which is peer-to-peer transfers). RELATED CONTENT (a You might also like list — recommend items that share the most tags/topics with the current one): POST the candidate set `POST ${API}/related {items:[{id, tags:[…]}], target, limit?}` → `{related:[{id, score, shared}]}` ranked by how many tags each item shares with the target (`shared` = overlap count, `score` = 0..1 Jaccard similarity; the target and zero-overlap items are excluded). Stateless — pass the items you already have (from a collection read) and the id of the one being viewed. Use THIS for related-posts / similar-products instead of hand-picking — it ranks by real tag overlap, no ML needed. ACTIVITY TIMELINE (a per-record history of interactions — calls, notes, emails, meetings logged against a contact/deal/project, newest first): a signed-in team member logs one `POST ${API}/activity {entity, ref, type?, body}` (type note/call/email/meeting/task; entity+ref identify the record, e.g. entity:contact ref:42) and reads the history `GET ${API}/activity?entity=contact&ref=42[&type=]` → `{activity:[{type, body, author_id, created_at}]}` (newest first). The author or an admin can `DELETE ${API}/activity/<id>`. This is a TEAM/internal log (any signed-in user can read/write, so build it into a staff/CRM view, not a public page). Use THIS for an interaction history/notes feed on any record instead of a plain notes column — typed entries, author, and a chronological timeline are handled. STAFF SHIFTS (a work-schedule roster — assign shifts and check who is on at a given time): an ADMIN schedules `POST ${API}/shifts {user, starts, ends, role?, note?}`, lists with `GET ${API}/shifts[?user=&from=&to=]`, and checks staffing for any window `GET ${API}/shifts/coverage?from=&to=` → `{on_shift, staff_count, staff, shifts}` (everyone whose shift overlaps that window). A staff member sees their own roster with `GET ${API}/shifts/mine[?from=&to=]`. Admin `DELETE ${API}/shifts/<id>`. Use THIS for a staff rota + coverage instead of a plain calendar table — the overlap/coverage query is done for you. TIME-OFF REQUESTS (a PTO/vacation request → manager approval flow): a member submits `POST ${API}/timeoff {starts, ends, reason?}` (starts pending) and tracks it with `GET ${API}/timeoff/mine`. A manager (ADMIN) reviews `GET ${API}/timeoff[?status=&user=]` and decides `POST ${API}/timeoff/<id>/decide {approve, note?}` (approved/denied, once). The member can cancel their OWN request while it is still pending (`DELETE ${API}/timeoff/<id>`); an admin can remove any. Use THIS for a leave/PTO approval workflow instead of a status column — the request→decision states, self-cancel, and manager review are built in (distinct from a leave-balance ledger). CONVERSION TRACKING (measure a goals conversion rate — visits vs completions for signups, checkouts, a CTA): fire one call per visitor `POST ${API}/conversions/<goal>/hit {converted}` — send `converted:false` when they merely see/start the step and `converted:true` when they complete it; the response `{visits, conversions, rate}` is the running rate (goals auto-create on first hit). Read a goal anytime `GET ${API}/conversions/<goal>` or all of them `GET ${API}/conversions`. An admin can give a goal a display name `POST ${API}/conversions/<goal> {name}` or `DELETE` it. Use THIS for a single goals conversion % instead of two separate counters — visits, conversions, and the rate are kept together (for a multi-step drop-off use /funnel instead). TWO-PERSON APPROVAL (require a SECOND admin to sign off on a dangerous action — delete-everything, a big refund — before it proceeds): one admin proposes `POST ${API}/dual-approval {op, ref?, note?}` → `{id, status:pending}`, and a DIFFERENT admin must `POST ${API}/dual-approval/<id>/approve` (the proposer approving their own → 403) which flips it to `authorized`; any admin can `POST ${API}/dual-approval/<id>/reject`. Gate the dangerous action in your code on the record being `authorized`. Admins review the queue with `GET ${API}/dual-approval[?status=]`. Use THIS for four-eyes / maker-checker control on sensitive ops instead of a single confirm — the two-distinct-admins rule is enforced server-side. RECURRING ORDERS / SUBSCRIPTIONS (a subscribe-and-save cadence — reorder every N days, a recurring box) with a due-list to fulfill: a member subscribes `POST ${API}/subscriptions {plan, interval_days, start?, ref?}` → `{id, next_run}` and manages theirs via `GET ${API}/subscriptions/mine` + `POST ${API}/subscriptions/<id>/cancel`. To fulfill, an admin (or a scheduled function) polls `GET ${API}/subscriptions/due` (every active sub whose next_run has passed), processes each order, then calls `POST ${API}/subscriptions/<id>/advance` to bump next_run forward one interval and count the run. Admin overview: `GET ${API}/subscriptions[?status=&user=]`. Use THIS for reorder/subscription cadences instead of tracking dates yourself — next-run, the due-list, and advance-after-fulfil are handled (pair with a scheduled edge function to run it automatically). RESOURCE BOOKING (reserve a room/table/piece-of-equipment for a time window with NO double-booking): a signed-in member books `POST ${API}/rooms/<resource>/book {starts, ends, note?}` → `{id}` or 409 if it overlaps an existing reservation of that resource (the overlap check is atomic, so two people can never grab the same slot; back-to-back bookings that merely touch are allowed). Check first with `GET ${API}/rooms/<resource>/free?starts=&ends=` → `{free}`, show a resources calendar with `GET ${API}/rooms/<resource>[?from=&to=]`, and cancel with `DELETE ${API}/rooms/<resource>/book/<id>` (owner or admin). `<resource>` is any id — room-3, table-7, projector-a. Use THIS for room/equipment/table reservations instead of a plain bookings table — overlap prevention is enforced server-side. DATA EXPORT (GDPR) (let a user download everything you hold about them, in one call — the data-portability right): the signed-in member calls `GET ${API}/data-export` → `{user, data:{<table>: rows}}` containing ONLY their own rows across every user-scoped table (points, orders, bookings, activity, etc). Offer it as a Download my data button that saves the JSON. Use THIS to satisfy data-portability/DSAR requests instead of assembling it by hand — it gathers the users rows everywhere automatically (and pairs with the Delete-my-account flow). PUBLISH SCHEDULING (schedule a post/page to go live later — a content calendar with a due-queue to flip things live): an ADMIN schedules `POST ${API}/publish-queue {ref, publish_at, kind?}` (ref points at your content record). A worker (a scheduled edge function) polls `GET ${API}/publish-queue/due` → everything whose publish_at has passed and is still scheduled, flips each live in your app, then marks it `POST ${API}/publish-queue/<id>/publish`. Admin overview + calendar: `GET ${API}/publish-queue[?status=]`; remove one with `DELETE`. Use THIS for scheduled publishing instead of checking a date on every read — a clean due-queue tells you exactly what to publish now. RECYCLE BIN / UNDO DELETE (a Trash where deleted records can be restored — soft-delete + undo instead of gone-forever): when the admin deletes a record, ALSO stash a snapshot `POST ${API}/recycle-bin {entity, ref?, data}` (data = the full record as JSON). Show the Trash with `GET ${API}/recycle-bin[?entity=]`; restoring `POST ${API}/recycle-bin/<id>/restore` returns `{entity, ref, data}` (re-insert it into your real table) AND removes it from the bin. Purge one `DELETE ${API}/recycle-bin/<id>` or empty old trash `DELETE ${API}/recycle-bin?before=<iso>`. Use THIS to give any delete an Undo / Trash instead of losing data — the snapshot + restore + auto-purge are handled. EVENT STREAM (an append-only activity/audit stream you can tail incrementally — feed a dashboard, sync a mirror, drive a webhook): a signed-in actor appends `POST ${API}/eventlog {type, data?}` → `{id}`. An admin tails it `GET ${API}/eventlog?after=<cursor>&type=&limit=` → `{events:[{id,type,data,actor_id,created_at}], cursor}` — pass the returned `cursor` as `after` next time to get ONLY new events (long-poll it for a live view). Use THIS for a durable event/activity stream instead of ad-hoc rows — monotonic ids + a resume cursor make incremental reads reliable (distinct from /audit, which logs record CRUD). CURRENCY CONVERTER (show prices in the visitors currency using rates YOU control — no live FX API needed): an ADMIN loads a rate snapshot `POST ${API}/fx {base?, rates:{USD:1, EUR:0.92, JPY:150}}` (rates relative to the base). The app converts `GET ${API}/fx/convert?amount=&from=&to=` → `{result, rate}` (cross-rates via the base are computed for you) and reads the table with `GET ${API}/fx`. Use THIS for multi-currency display/pricing instead of hardcoding conversions — update the snapshot when rates change and every conversion follows. PREORDERS / LIMITED DROPS (sell a capped number of units before stock exists — a limited drop, an early-bird batch — with no overselling): an ADMIN sets the cap `POST ${API}/preorders/<item> {capacity, name?}`; a member reserves units `POST ${API}/preorders/<item>/hold {qty}` → `{held, remaining}` or 409 when the cap is reached (the total-held check is atomic, so two buyers can never push it over; one hold per member). Show availability with `GET ${API}/preorders/<item>` → `{capacity, held, remaining, sold_out, mine}`; a member frees theirs with `DELETE ${API}/preorders/<item>/hold`. Use THIS for capped preorders/waitlists/limited drops instead of a stock column — the never-oversell guarantee is enforced server-side. SCHEDULED DIGESTS (a recurring email digest — a weekly summary, a daily report — you define once and a worker sends on cadence): an ADMIN defines it `POST ${API}/digests/<name> {description?, query?, interval_days, recipients?, start?}` (query = whatever your worker needs to build the content). A scheduled edge function polls `GET ${API}/digests/due` → digests whose next_run has passed, builds + sends each, then calls `POST ${API}/digests/<name>/sent` to advance next_run one interval. Admin overview: `GET ${API}/digests`; remove with `DELETE`. Use THIS for recurring reports/newsletters instead of tracking send-dates yourself — the cadence, due-list, and advance-after-send are handled (pair with a scheduled function + an email step). SLA TIMERS (a countdown deadline on a ticket/order — respond within N minutes — that flags breaches): start a clock `POST ${API}/sla-timers/<kind>/<ref> {target_mins}` when work arrives (kind+ref identify it, e.g. ticket/123), then read `GET ${API}/sla-timers/<kind>/<ref>` → `{remaining_mins, breached, due_at, status}` to show a due-in badge, and `POST ${API}/sla-timers/<kind>/<ref>/resolve` when its handled (stops the clock). An admin lists everything — filter the breaches with `GET ${API}/sla-timers?status=breached` for an escalation view. Use THIS for response/resolution SLAs instead of computing deadlines by hand — remaining time, the breach flag, and a breached-list are done for you. WISHLIST / SAVE FOR LATER (a heart/save button — a member saves items to their list, and you can show how many people saved each): a member saves `POST ${API}/wishlist/<item> {note?}` and removes `DELETE ${API}/wishlist/<item>`; they read their own list `GET ${API}/wishlist`. Anyone sees the popularity of an item `GET ${API}/wishlist/<item>/count` → `{count, mine}` (mine = did the caller save it) — great for a saved N times badge or a most-wished list. Use THIS for wishlists/favourites/save-for-later instead of a table you manage — per-member saves + a cross-member want-count are handled. GLOSSARY (a definitions/jargon page with lookup by term OR synonym — a knowledge glossary, a term tooltip): an ADMIN curates `POST ${API}/glossary {term, definition, aliases?, category?}`. The app looks one up `GET ${API}/glossary?term=<t>` → `{entry:{term, definition, aliases, category}}` (matches an ALIAS too, so a synonym resolves to the canonical term — perfect for inline term tooltips), and lists/searches `GET ${API}/glossary[?q=&letter=&category=]` (q searches term+definition, letter for an A–Z index). Admin `DELETE ${API}/glossary?term=`. Use THIS for a glossary/definitions feature instead of a plain table — alias lookup and an A–Z/search index come built in. STAR RATINGS (a quick 1–5 star rating with an average + a distribution bar — separate from written reviews): a member rates `POST ${API}/ratings/<item> {stars}` (1–5, changeable — re-rating replaces their vote) and can clear it with `DELETE ${API}/ratings/<item>`. Anyone reads `GET ${API}/ratings/<item>` → `{average, count, distribution:{1..5}, mine}` — render the average as stars, `count` as (N ratings), and `distribution` as the 5-bar histogram; `mine` is the callers own stars. Use THIS for a fast star-rating widget instead of building it on /reviews — one changeable vote per member, plus the average + per-star breakdown, are computed for you (use /reviews when you need written text too). DRIP SEQUENCES (an automated multi-step follow-up — a welcome series, an onboarding drip, a re-engagement flow — where each message goes out N days after signup): an ADMIN defines the flow `POST ${API}/sequences/<name> {steps:[{day, subject?, template?}], description?}` (day = days after enrollment; steps auto-sort). Enroll someone `POST ${API}/sequences/<name>/enroll {subject}` (subject = their email/id) — the first step schedules automatically. A worker (a scheduled edge function) polls `GET ${API}/sequences/<name>/due` → enrollments whose next step is now due (with the step content), sends each, then `POST ${API}/sequences/<name>/advance {enrollment}` to schedule the next step (or complete). Stop one with `POST ${API}/sequences/<name>/cancel {enrollment}`. Use THIS for drip campaigns/onboarding sequences instead of tracking send-dates yourself — the per-step scheduling, due-list, and advance-or-complete are handled (pair a scheduled function + an email step). ESCALATION RULES (auto-escalate an unhandled ticket/lead up a chain as time passes — after 30 min → team lead, after 2 h → manager): an ADMIN defines the ladder `POST ${API}/escalation-rules {name?, after_mins, target}`. Given how long something has been waiting, ask `GET ${API}/escalation-rules/evaluate?elapsed_mins=<n>` → `{escalate, escalate_to, rule, next_at_mins}` — it returns the HIGHEST rule whose threshold has passed (who it should be with now) and when the next escalation triggers. Admin lists/deletes rules. Use THIS to drive time-based escalation instead of hardcoding thresholds — the right tier for any elapsed time + the next-step time are computed (pair with /sla-timers for the clock). SALES TAX (compute tax on a cart by region using rates YOU set — no tax API needed): an ADMIN stores a rate per region `POST ${API}/tax-rates/<region> {rate, name?}` (rate as a percent, e.g. 8.75). At checkout the app calls `GET ${API}/tax-rates/compute?region=<r>&subtotal=<amount>` → `{rate, tax, total}` (tax rounded to the cent, total = subtotal + tax). `GET ${API}/tax-rates` lists them for a dropdown. Use THIS for sales-tax on an order instead of hardcoding a rate — per-region rates + the to-the-cent computation are handled. GIFT CARDS (sell/issue a gift card with a code + balance that the bearer redeems at checkout — a real stored-value card): an ADMIN issues one `POST ${API}/gift-cards {amount, code?, currency?, note?}` → `{code, balance}` (a code is generated if you dont supply one). Anyone with the code checks it `GET ${API}/gift-cards/<code>` → `{balance, status}` and spends against it `POST ${API}/gift-cards/<code>/redeem {amount}` → `{balance}` or 409 when the balance is too low (the deduction is atomic, so it can never go negative or be double-spent). Admin voids a card `POST ${API}/gift-cards/<code>/void` and lists them. Use THIS for gift cards / prepaid balances instead of a number you mutate — issue, check, atomic redeem, and void are handled (the code is a bearer token, so treat it like cash). LICENSE KEYS (issue + validate software license keys — activate a paid app/plugin, gate a download): an ADMIN issues `POST ${API}/licenses {product?, owner?, seats?, expires?}` → `{key}` (auto-generated). Your app/product validates on activation `GET ${API}/licenses/validate?key=<k>` → `{valid, product, seats, expires_at, reason}` — `valid:false` with a reason of unknown/revoked/expired tells you exactly why to refuse. Admin revokes `POST ${API}/licenses/<key>/revoke`, lists, and deletes. Use THIS to sell/validate license keys instead of rolling your own — generation, expiry + revocation checks, and a clear valid/invalid+reason are handled. CHANGELOG / RELEASE NOTES (a public whats-new page you update as you ship — versioned entries readers can browse): an ADMIN posts `POST ${API}/changelog {title, version?, body?, kind?, released?, published?}` (set `published:false` to stage a draft). Your page renders `GET ${API}/changelog[?limit=]` → published entries newest-first (each `{version, title, body, kind, released_at}`). Admin sees drafts too via `GET ${API}/changelog/all`, edits with `PATCH ${API}/changelog/<id>` (flip `published` to release a draft), and `DELETE`s. Use THIS for a release-notes/whats-new feed instead of hardcoding it in the page — drafts, publish-on-flip, and a newest-first public list are handled. DOWNLOAD COUNTER (count downloads of a file, and optionally gate it behind login — a lead magnet, a paid asset): an ADMIN registers a file `POST ${API}/downloads/<file> {name?, url?, gated?}` (gated:true = members only). Your download button calls `POST ${API}/downloads/<file>/hit` → `{url, count}` (it bumps the count and hands back the URL to redirect to; a gated file returns 401 to signed-out visitors). Show stats/most-popular with `GET ${API}/downloads/<file>` (count, no increment) and `GET ${API}/downloads` (ranked). Use THIS to track + gate downloads instead of a raw link — the count and the login-gate are handled server-side. WAIVERS / E-SIGNATURES (collect a signed agreement — a liability waiver, a photo release — with a name + a signature record per person): an ADMIN defines it `POST ${API}/waivers/<doc> {title, body, version?}`. A member reads `GET ${API}/waivers/<doc>` and signs `POST ${API}/waivers/<doc>/sign {name, signature?}`; check whether they have signed the CURRENT version with `GET ${API}/waivers/<doc>/mine` → `{signed, signed_at}` (bumping the version re-requires a signature, so gate the activity on signed:true). An admin exports the roster `GET ${API}/waivers/<doc>/signatures`. Use THIS for a signed waiver/consent instead of a checkbox — a name, a signature, a timestamp, and per-version re-signing form a real record. PETITIONS (a sign-this-petition drive with a live signature count toward a goal): an ADMIN creates it `POST ${API}/petitions/<slug> {title, description?, goal?}`. A member signs once `POST ${API}/petitions/<slug>/sign {name?, comment?}`. Anyone reads `GET ${API}/petitions/<slug>` → `{title, goal, signatures, progress, mine, recent}` (progress = % of goal, recent = the latest signers with their comments) and lists all with `GET ${API}/petitions`. Use THIS for a petition/pledge with a progress bar instead of a counter — one signature per member, a goal %, and a live signer wall are handled. VAULT / APP SETTINGS (an admin-only key-value store for backend config or secrets your edge functions read — API keys, feature config, integration IDs): an ADMIN sets `POST ${API}/vault/<key> {value, note?}` (value is a string or any JSON) and reads `GET ${API}/vault/<key>` → `{value, note}`. `GET ${API}/vault` lists the keys with values REDACTED (only key + size + note). Every operation is admin-only — NEVER expose vault values on a public page. Use THIS for admin-managed backend config/secrets instead of hardcoding them — an edge function or admin screen reads them, and the list view never leaks the values. EMBED CACHE (store the oEmbed/embed HTML for a pasted link — a YouTube video, a tweet — so you render the rich card without re-fetching): a signed-in user caches it `POST ${API}/embeds {url, title?, html?, thumbnail?, provider?}` (build the html/thumbnail however — an edge function fetching oEmbed, or the user pasting). Your page renders `GET ${API}/embeds?url=<u>` → `{embed:{title, html, thumbnail, provider}}` (null if not cached — then fetch + cache it). Admin `DELETE ${API}/embeds?url=`. Use THIS to cache link previews / embed cards instead of re-fetching every render — the metadata lives keyed by URL. MILESTONES (per-user progression goals with an achieved badge — reach 10 posts, invite 5 friends — distinct from a group challenge): an ADMIN defines one `POST ${API}/milestones/<key> {name, target, reward?}`. Each member accrues `POST ${API}/milestones/<key>/progress {by}` (or `{set}`) → `{progress, target, achieved}` — the FIRST time they cross the target it stamps an achieved date. Show a members standing `GET ${API}/milestones/<key>` (includes `mine`) and all of theirs `GET ${API}/milestones/mine`; list definitions with `GET ${API}/milestones`. Use THIS for personal achievement goals/progress bars instead of a counter — the target, the achieved flag + timestamp, and per-member progress are handled (use /challenges for a shared group goal with a leaderboard). REWARDS CATALOG (let members spend their points on real rewards — a redemption store on top of /points): an ADMIN lists rewards `POST ${API}/rewards-catalog {name, cost, stock?, description?}` (cost in points; omit stock or set -1 for unlimited). A member redeems `POST ${API}/rewards-catalog/<id>/redeem` → `{balance}` or 409 (out of stock, or not enough points) — the server claims a unit of stock AND deducts the points atomically (and refunds the stock if the points fall short), so it never oversells or overdraws. Show the store `GET ${API}/rewards-catalog`, a members redemptions `GET ${API}/rewards-catalog/mine`, and (admin) all of them `GET ${API}/rewards-catalog/redemptions`. Use THIS to turn /points into a real rewards store instead of wiring the deduction yourself — stock + points are spent safely together. ONBOARDING CHECKLIST (a getting-started checklist that tracks each users progress — set up profile ✓, invite a friend ✓): an ADMIN defines the steps `POST ${API}/onboarding/steps {steps:[{key, title, position?}]}`. A member marks one done `POST ${API}/onboarding/complete/<step>` (or DELETE to undo) and reads their progress `GET ${API}/onboarding/me` → `{steps:[{key,title,done}], completed, total, percent, all_done}`. Render it as a checklist with a progress bar; hide it once `all_done`. Use THIS for a user onboarding/setup checklist instead of per-user flags — the step list, per-member completion, and the percent are handled. SPOTLIGHT / FEATURED ROTATION (rotate a featured item automatically — a daily deal, a member spotlight, a highlighted post — no manual switching): an ADMIN adds candidates `POST ${API}/spotlight {item, label?, weight?}` (weight makes some appear more often). Your page shows `GET ${API}/spotlight/current` → `{current:{item, label}}` — a deterministic weighted pick that ROTATES each day on its own (everyone sees the same one that day; no cron needed). `GET ${API}/spotlight` lists the pool; admin `DELETE`s. Use THIS for an auto-rotating featured slot instead of hand-picking daily — the weighted, day-stable pick is computed for you. COHORT RETENTION (measure whether members come back — signup cohorts, weekly active retention): `${API}/cohorts/track` (POST, member) records that the signed-in member was active today (pass `{day:'2026-01-05'}` to backfill; an admin may pass `{user}` to seed someone). `GET ${API}/cohorts/retention?period=week&size=8` (ADMIN) buckets users by the period (day/week/month) of their FIRST activity and returns, per cohort, how many came back in each following period as counts + rates — the classic retention triangle. `GET ${API}/cohorts` (ADMIN) → totals. Use THIS to answer 'of the people who joined in week X, how many were still active N weeks later'. HANDLE / SLUG RESERVATION (claim a unique username, vanity URL, room code or short-link slug so no two people grab the same one): `POST ${API}/handles/reserve {handle, ns?}` atomically claims it for the signed-in member (idempotent if they already own it, 409 if someone else does); `GET ${API}/handles/check?handle=&ns=` (public) → {available} + owner_is_me; `GET ${API}/handles/mine` lists a member's claims; DELETE `${API}/handles/<handle>?ns=` releases it (owner or admin). Use `ns` to keep separate pools (usernames vs team-slugs) in one app. Use THIS instead of a plain UNIQUE column when you need a check-then-claim that stays safe under concurrency. IMPORT PREVIEW / DRY-RUN VALIDATION (sanity-check a pasted CSV or bulk paste BEFORE committing it): `POST ${API}/import-preview {fields:[{name,type,required}], rows:[…]}` (member) returns {total, valid, invalid, results:[{index, ok, errors:[{field,message}]}]} — flagging missing-required, wrong-type (string/number/integer/boolean/email/date) and unknown columns per row, writing NOTHING. Use THIS to show a green/red import summary so the user fixes their file before the real insert. UTM CAMPAIGN LINKS (track which campaign/ad/email drove a click — a marketing link shortener with attribution): `POST ${API}/utm {target, campaign?, source?, medium?, term?, content?, slug?}` (ADMIN) registers a tracked link and returns a `url` with the utm_* params already appended (share THAT); `POST ${API}/utm/<slug>/click` (public) atomically bumps its click counter and returns the target to redirect to; `GET ${API}/utm/report` (ADMIN) rolls the clicks up by campaign/source/medium; `GET ${API}/utm` lists them; DELETE `${API}/utm/<slug>` removes one. Use THIS for 'which channel is working' dashboards instead of a plain link. SPAM / HONEYPOT SCORE (screen a contact/signup/comment form for bots before you store it): `POST ${API}/spam-check {honeypot?, elapsed_ms?, text?, links_max?}` (public, stateless) returns {score 0-100, verdict:'ham'|'suspect'|'spam', reasons}. Add a hidden `honeypot` input a human never sees (filled → almost certainly a bot), pass `elapsed_ms` since the form loaded (sub-2s = bot), and the message `text` (too many links, ALL CAPS, and spam keywords each add points). Use THIS to silently drop/flag junk submissions — nothing is written, it is pure scoring. RETURN / RMA FLOW (returns, refunds, exchanges for a store): `POST ${API}/rma {order_ref, reason?, items?}` (member) opens a request (status requested); an ADMIN drives it with `POST ${API}/rma/<id>/approve`, `/reject {note?}`, and `/refund {amount?}` — transitions are guarded (requested→approved|rejected, approved→refunded; a wrong-state move is a 409). Members read `GET ${API}/rma/mine`, admins `GET ${API}/rma?status=` and `GET ${API}/rma/<id>`. Use THIS for a self-serve returns portal rather than a status column you flip by hand. CONTACTS / CRM ADDRESS BOOK (a staff-managed contact list with dedupe + merge — for a CRM, a mailing list, a 'people' admin): `POST ${API}/contacts {email?, name?, phone?, company?, tags?, notes?}` (ADMIN) captures a contact and DEDUPES on email (a repeat email fills the gaps on the existing row instead of making a duplicate); `POST ${API}/contacts/merge {from, into}` folds one contact into another (the survivor gap-fills from the loser, the loser is hidden); `GET ${API}/contacts?q=` searches by name/email/company, `GET/PATCH/DELETE ${API}/contacts/<id>` manage one. Use THIS instead of a plain table when the same person keeps re-submitting a form. ORDER NOTES / GIFT MESSAGES (attach a delivery note or gift message to an order — checkout add-ons): `POST ${API}/order-notes {order_ref, message, gift?}` (member) attaches a note (set `gift:true` for a gift message); `GET ${API}/order-notes?order_ref=<ref>` returns a member their own notes on that order and an admin ALL of them; `GET ${API}/order-notes/mine` lists a member's; DELETE `${API}/order-notes/<id>` (owner or admin). Use THIS for 'add a note to your order / gift wrapping message' at checkout. CONFIG VALIDATION (check a settings object against a spec before you save it — a typed form validator): `POST ${API}/config-validate {schema:{key:{type,required?,default?,enum?,min?,max?}}, config}` (member, stateless) returns {valid, errors:[{key,message}], normalized}. `normalized` has defaults filled in and values coerced (an integer string → a number, 'true' → a boolean), so you can validate-then-save in one step. Types string/number/integer/boolean; min/max bound numbers or string length; enum restricts allowed values; unknown keys are flagged. Use THIS for a settings/preferences panel (the sibling `${API}/import-preview` does the same for MANY rows). RATE-LIMIT POLICIES (throttle an action per user/key — 'max 5 password resets an hour', 'max 3 SMS a day', a usage quota): `POST ${API}/rate-policies {key, max, window_sec}` (ADMIN) declares a named limit; then before doing the action call `POST ${API}/rate-policies/<key>/consume` (member) which atomically counts a hit in the current window and returns {allowed, remaining, reset_at} — proceed only when allowed is true. `GET ${API}/rate-policies` lists, DELETE `${API}/rate-policies/<key>` removes. Use THIS for app-level quotas you can tune without redeploying (the raw ${API} endpoints already have their own network throttle). AUDIT-LOG RETENTION (keep the audit trail from growing forever — a GDPR/storage-hygiene control): `POST ${API}/audit-policy {retention_days}` (ADMIN) sets how long to keep audit rows; `POST ${API}/audit-policy/prune` (optionally `{before}`) deletes anything older; `GET ${API}/audit-policy` shows {retention_days, audit_rows, oldest_at}. Use THIS on tables you gave `audit:true` when you want old change-history purged on a schedule. TRENDING / TOP-N (a 'popular right now' or 'most viewed this week' feed): `POST ${API}/trending/hit {item, weight?}` (member) records a view/vote/play for an item id; `GET ${API}/trending/top?window=24h&n=10` (public) returns the top items ranked by total weight inside the window (window is like `1h`, `24h`, `7d`, `30d`, or `all`); an ADMIN can DELETE `${API}/trending?before=` to prune. Use THIS for trending posts/products/tracks instead of ordering a table by a raw counter — the time window is the point. NPS SURVEYS (the classic 'how likely are you to recommend us, 0-10?' loyalty metric): `POST ${API}/nps {score, campaign?, comment?}` (member) records one answer per person per campaign (a re-answer overwrites); `GET ${API}/nps?campaign=` (ADMIN) returns {total, promoters, passives, detractors, nps} where NPS = %promoters(9-10) − %detractors(0-6); `GET ${API}/nps/me` shows a member their own answer, `GET ${API}/nps/responses` (ADMIN) lists them raw. Use THIS for the specific NPS math — a generic star rating or survey does NOT compute it. TESTIMONIALS WALL (a curated 'what customers say' section for a landing page): `POST ${API}/testimonials {quote, author?, role?, avatar?, rating?}` (member) submits a quote that starts PENDING; an ADMIN `PATCH ${API}/testimonials/<id> {approved?, featured?, position?}` approves/pins/reorders it and `GET ${API}/testimonials/all` sees every one incl. pending; the PUBLIC `GET ${API}/testimonials` returns ONLY approved ones, featured first. Use THIS for a moderated quote wall rather than showing raw user submissions. TICKET MERGE + LINK (dedupe and relate support tickets — additive to the ticket system): an ADMIN `POST ${API}/tickets/<id>/merge {into}` folds a duplicate ticket into another (its messages move over, the duplicate becomes status 'merged'); `POST ${API}/tickets/<id>/link {other, relation?}` marks two tickets as related; `GET ${API}/tickets/<id>/links` lists a ticket's relations (the requester on their own ticket, or an admin). Use THIS when the same issue comes in twice or several tickets share a root cause. iCALENDAR FEED (a downloadable .ics / 'add to my calendar' file — for events, bookings, class schedules): `POST ${API}/ical {events:[{title, start, end?, description?, location?, allDay?, uid?}], name?}` (public) returns a text/calendar VCALENDAR the browser saves as an .ics that imports into Google/Apple/Outlook Calendar. `start`/`end` accept any parseable date; set `allDay:true` for a whole-day event. Use THIS for an 'Add to Calendar' button instead of hand-building ICS. CSV CONVERTER (build an export file or parse a pasted spreadsheet without a client library): `POST ${API}/csv/to {rows:[{...}], columns?, delimiter?}` (member) turns JSON rows into RFC-4180 CSV text (commas/quotes/newlines quoted correctly; pass `columns` to pick/order them); `POST ${API}/csv/from {csv, delimiter?, headers?}` parses CSV text back into rows (first line is headers unless `headers:false`). Use THIS for 'Export to CSV' / 'Import from CSV' — pair `csv/from` with `${API}/import-preview` to validate before saving. vCARD (a 'save my contact' .vcf download — for a team page, a digital business card): `POST ${API}/vcard {name, email?, phone?, org?, title?, url?, note?}` (public) returns a text/vcard vCard 3.0 file that opens straight into the phone's Contacts app (you can also give `first`/`last` separately). Use THIS for an 'Add to contacts' button. WEBHOOK DEAD-LETTER + RETRY (see which outbound webhook deliveries failed and re-send one — additive to the ${API}/webhooks system): `GET ${API}/webhooks/dead-letter?hook=&limit=` (ADMIN) lists the failed deliveries (non-2xx or unreachable); `POST ${API}/webhooks/deliveries/<id>/retry {data?}` (ADMIN) re-fires that delivery to its hook and logs the result. Use THIS for a 'failed webhooks' admin panel with a Retry button. API-KEY SCOPES (limit what each API key is allowed to do — additive to ${API}/apikeys): `GET ${API}/apikeys/<id>/scopes` and `PUT ${API}/apikeys/<id>/scopes {scopes:[...]}` (ADMIN) attach a list of permission strings (like `read`, `write:orders`, `admin.*`) to a key; your app checks the list before honoring a key. Use THIS to issue least-privilege keys instead of all-or-nothing ones. FLAG ATTRIBUTE AUDIENCES (turn a feature flag on only for users matching attributes — plan=pro, country=US — on top of ${API}/flags): an ADMIN `PUT ${API}/flag-audiences/<key> {attrs:{plan:['pro','max'], country:['US']}}` sets the targeting rules on an existing flag; then `POST ${API}/flag-audiences/<key>/match {attrs:{plan:'pro', country:'US'}}` (public) returns {matched, enabled, failed_on} — true only when the flag is enabled AND every rule is satisfied. Use THIS for attribute-based rollouts (the plain ${API}/flags/eval still handles role/team/percentage rollout). ANALYTICS SESSIONS (measure active users / 'who is online now' / average session length): a member calls `POST ${API}/sessions/start` (returns an id) when the app loads, `POST ${API}/sessions/<id>/beat` periodically (bumps a page-view counter + last-seen), and `POST ${API}/sessions/<id>/end` on unload; an ADMIN reads `GET ${API}/sessions/active?window=5m` for the live count + unique users, and a member reads `GET ${API}/sessions/me`. Use THIS for a live-visitors widget or session-length analytics. QR PAYLOAD BUILDER (build the exact string to put inside a QR code — pass the result to any QR-image library): `POST ${API}/qr {type, ...}` (public, stateless) returns {payload}. type=url/text (just the value), tel/sms (phone[, message]), mailto (email, subject?, body?), geo (lat,lng), wifi (ssid, password?, encryption?), or vcard (name, phone?, email?, url?, org?). Use THIS so you do not have to remember the WIFI:/MECARD:/SMSTO: formats. PERCENTILE / DISTRIBUTION (p50/p90/p95 latency, score distributions — the stats a plain AVG hides): `POST ${API}/stats/percentile {values:[...], p?:[50,90,95]}` (public, stateless) returns {count, min, max, mean, median, percentiles}. Use THIS for 'p95 response time' style tiles (the sibling `${API}/stats/significance` does A/B z-tests). UNIT CONVERTER (convert between physical units — a recipe app, fitness tracker, shipping calculator): `POST ${API}/convert {value, from, to}` (public, stateless) returns {result, category}. Handles length (m/km/cm/mi/yd/ft/in), mass (g/kg/lb/oz/t), volume (l/ml/gal/qt/cup/floz), time (s/min/h/d/wk), data (b/kb/mb/gb/kib/mib/gib), and temperature (c/f/k) — the category is auto-detected, and mismatched units (km→kg) are rejected. Use THIS instead of hard-coding conversion factors (the sibling ${API}/fx/convert handles CURRENCY). TEXT DIFF (show what changed between two versions — a revision history, an edit review, a config comparison): `POST ${API}/diff {a, b}` (public, stateless) returns {changes:[{type:'eq'|'add'|'del', line}], added, removed} from a line-level LCS diff. Use THIS to render a red/green side-by-side of two text blobs. PRICE LISTS (customer-group pricing + quantity discounts — retail vs wholesale vs VIP, buy-more-save-more): an ADMIN `POST ${API}/price-lists {list, item, price, currency?, min_qty?}` sets a price tier (one per list+item+min_qty; `list` is the customer group, `min_qty` is the volume break); the app calls `GET ${API}/price-lists/lookup?list=<group>&item=<sku>&qty=<n>` (public) to get the best price whose min_qty is at or below the quantity. Use THIS for tiered/bulk pricing instead of a single price column. BACKGROUND JOB QUEUE (defer work + retry failures — send-later emails, image processing, sync tasks): an ADMIN `POST ${API}/jobs {payload, queue?, max_attempts?, delay_sec?}` enqueues a job; a worker loop calls `POST ${API}/jobs/claim {queue?}` to atomically grab the next due job, does the work, then `POST ${API}/jobs/<id>/done` or `POST ${API}/jobs/<id>/fail {error?}` (a failure retries with exponential backoff until max_attempts, then the job goes 'dead'). `GET ${API}/jobs/stats` shows counts by status. Use THIS for reliable async work with automatic retries, not a plain table you poll. HEALTH-CHECK REGISTRY (a status page / uptime dashboard): an ADMIN `POST ${API}/health-checks {name, status, message?}` reports each component as up/degraded/down; `GET ${API}/health-checks` (public) returns every check plus a single rolled-up `overall` (down beats degraded beats up). Use THIS for a 'system status' page or an internal ops dashboard. HISTOGRAM (bucket a set of numbers into a bar chart — score/latency/age distributions): `POST ${API}/stats/histogram {values:[...], bins?, min?, max?}` (public, stateless) splits the range into equal bins and returns {bins:[{lo,hi,count}], min, max, count}. Use THIS to draw a distribution bar chart (the siblings ${API}/stats/percentile and ${API}/stats/significance give percentiles and A/B tests). READABILITY (analyze a piece of writing — a blog editor, an SEO tool, a 'X min read' badge): `POST ${API}/readability {text, wpm?}` (public, stateless) returns {chars, words, sentences, syllables, reading_time_min, flesch_reading_ease, flesch_kincaid_grade}. Higher reading-ease = simpler; grade = US school grade level. Use THIS for a reading-time label or a writing-quality meter. SCHEDULE REGISTRY (a lightweight cron — declare recurring jobs, then a poller runs the due ones): an ADMIN `POST ${API}/schedules {name, interval_sec, enabled?}` declares a recurring schedule; a poller calls `GET ${API}/schedules/due` to get the ones whose interval has elapsed, does the work, then `POST ${API}/schedules/<name>/ran` to reset the clock. Use THIS to drive periodic tasks (daily digest, hourly sync) when you do not have real cron. KUDOS / PEER RECOGNITION (a shout-outs / props / peer-recognition wall for a team app or community): a member `POST ${API}/kudos {to, message?}` gives kudos to another member (not themselves); `GET ${API}/kudos/leaderboard` ranks the top receivers, and `GET ${API}/kudos/received` / `GET ${API}/kudos/given` show a member's own. Use THIS for employee recognition, community props, or a gratitude wall. ON-CALL ROTATION (who is on duty right now — support rotations, DevOps on-call, a duty roster): an ADMIN `POST ${API}/oncall/<rotation> {members:[...], interval_sec, anchor?}` defines an ordered rotation; anyone reads `GET ${API}/oncall/<rotation>/current` to get {on_call, next, next_handoff} — the current person is computed from the clock (no pointer to advance), so it is always correct. Use THIS for a live 'currently on call' widget. RENEWALS (track contract / subscription end dates and what is coming up for renewal): an ADMIN `POST ${API}/renewals {name, end_date, amount?, ref?}` records a contract; `GET ${API}/renewals/upcoming?days=30` lists active ones ending within the window; `POST ${API}/renewals/<id>/renew {end_date}` extends it, and `PATCH ${API}/renewals/<id> {status}` cancels/marks it. Use THIS for a renewals dashboard or 'expiring soon' reminders. SLUGIFY (turn a title into a clean URL slug): `POST ${API}/slugify {text, max?, separator?, existing?:[...]}` (public, stateless) lowercases, strips accents (Cafe Deja Vu becomes cafe-deja-vu), and replaces punctuation with a separator; pass the slugs you already have as `existing` and it appends -2/-3 to avoid a clash. Use THIS for post/product URL slugs (pair with `${API}/handles` if you need to atomically RESERVE the slug). MOVING AVERAGE (smooth a noisy time-series for a trend line — sales, sensor readings, metrics): `POST ${API}/stats/moving-average {values:[...], window, ema?}` (public, stateless) returns {sma:[...]} aligned to the input (null until the window fills); pass `ema:true` for an exponential moving average too. Use THIS to draw a trend line over jumpy data (the siblings ${API}/stats/percentile, histogram, significance cover the other stats). NO-SHOW TRACKING (count missed appointments per customer — enforce a no-show policy): an ADMIN `POST ${API}/no-shows {user, ref?, reason?}` records a missed booking and returns the running strike count; `GET ${API}/no-shows/count?user=<id>` reads it, a member sees their own at `GET ${API}/no-shows/me`, and DELETE `${API}/no-shows/<id>` forgives one. Use THIS to warn or block repeat no-shows. CONTENT REVIEW WORKFLOW (an editorial approval pipeline — draft to review to publish): a member `POST ${API}/content-review {ref, title?}` opens a draft; the author `POST ${API}/content-review/<ref>/submit` sends it for review; an ADMIN `POST ${API}/content-review/<ref>/approve` (or `/reject {note}`) then `/publish` moves it along (each step is a guarded transition — you cannot publish something that was not approved). `GET ${API}/content-review?status=in_review` is the review queue. Use THIS for moderated posts, KB articles, or any submit-review-publish flow. ANOMALY DETECTION (spot outliers / spikes in a set of numbers — fraud, error rates, unusual usage): `POST ${API}/stats/anomaly {values:[...], value?, threshold?}` (public, stateless). Pass a `value` to test one point (returns its z-score + an anomaly flag), or omit it to scan the whole series and get back every outlier. `threshold` is the z-score cutoff (default 3). Use THIS for 'is this number unusual' checks. EQUIPMENT / ASSET CHECKOUT (a lending library, tool crib, gear/room booking, device loans): an ADMIN `POST ${API}/equipment {name, ref?}` adds an asset; a member `POST ${API}/equipment/<id>/checkout` claims it ONLY if it is free (a second person gets a 409), then `POST ${API}/equipment/<id>/return` gives it back (the holder or an admin); `GET ${API}/equipment/mine` lists what a member holds and `GET ${API}/equipment?status=available` lists what is free. Every move is logged. Use THIS for any 'check out / check in' inventory. TAXONOMY (a nested category / topic tree — a menu of categories, a tag hierarchy, a docs sidebar): an ADMIN `POST ${API}/taxonomy {term, parent?}` adds a term under a parent (or at the root; slugs are auto and unique per parent); `GET ${API}/taxonomy` returns the whole nested tree ready to render, and `PATCH ${API}/taxonomy/<id> {parent}` moves a branch. A term with children cannot be deleted until they are moved. Use THIS for hierarchical categories instead of a flat tag list. PASSWORD STRENGTH METER (a live strength bar on a sign-up / change-password form): `POST ${API}/password-strength {password}` (public, stateless) returns {score 0-4, label, checks, suggestions}. It flags common passwords, repeats and sequences, and the suggestions tell the user exactly what to improve. NOTHING is stored or logged. Use THIS to drive a red-to-green strength bar (call it as the user types). DOUBLE OPT-IN (confirmed email signups — a newsletter or waitlist that requires a click-to-confirm): `POST ${API}/opt-in {email, list?}` records a PENDING subscriber and returns a `token` (email the user a link like /confirm?token=...); when they click, `POST ${API}/opt-in/confirm {token}` marks them confirmed. An ADMIN reads `GET ${API}/opt-in?status=confirmed`. Use THIS for GDPR-friendly, verified mailing lists (the plain ${API}/newsletter stores unconfirmed signups). REPUTATION / KARMA (a trust/reputation score that FADES over time — unlike a plain point total): an ADMIN `POST ${API}/reputation/award {user, points, reason?}` logs a timestamped event; `GET ${API}/reputation/score?user=<id>&half_life_days=90` returns the score with older points exponentially discounted, and `GET ${API}/reputation/leaderboard` ranks users by the decayed score. Use THIS when recent activity should matter more than ancient history (the plain ${API}/points ledger never decays). BROKEN-LINK REGISTRY (track which of your links are dead — a link checker's results store): an ADMIN `POST ${API}/link-check {url}` registers a URL to watch, a crawler posts results with `POST ${API}/link-check/report {url, ok, http_status?}`, and `GET ${API}/link-check/broken` lists everything currently broken. NOTE the server does not fetch the URLs itself — you (or a scheduled job) report the results. Use THIS for a 'broken links' admin report. RIGHT-TO-BE-FORGOTTEN QUEUE (GDPR / CCPA data-deletion requests): a member `POST ${API}/erasure-requests {reason?}` opens a data-erasure request (one at a time); an ADMIN works the queue `GET ${API}/erasure-requests?status=open` and moves each one `POST ${API}/erasure-requests/<id>/process` then `/complete` (or `/reject {note}`). Use THIS to log and track deletion requests for compliance (do the actual data deletion in your own code when you complete one). COLOR CONTRAST (WCAG accessibility check for text colors — a theme editor, a brand tool): `POST ${API}/color-contrast {fg, bg}` (public, stateless) takes two hex colors and returns {ratio, aa, aaa, aa_large, aaa_large} — whether the pair passes WCAG AA/AAA for normal and large text. Use THIS to warn when a chosen text/background pair is not legible. METRIC ALERTS (threshold alerting on your own numbers — error rate too high, stock too low, uptime dipped): an ADMIN `POST ${API}/metric-alerts {metric, op, threshold}` declares a rule (op is gt/gte/lt/lte/eq/ne); push a reading through `POST ${API}/metric-alerts/check {metric, value}` and it returns which rules breached AND logs them, readable at `GET ${API}/metric-alerts/breaches`. Use THIS for 'alert me when X crosses Y' without a monitoring service. REPLAY-PROTECTION NONCES (make a one-time token truly one-time — payment callbacks, magic links, form re-submits): `POST ${API}/nonce/consume {nonce}` succeeds the FIRST time and returns 409 on every repeat, so you can guard an action against double-submission or replay. `POST ${API}/nonce/purge` (ADMIN) clears expired ones. Use THIS to make a webhook/callback idempotent at the edge (the sibling ${API}/idempotency stores-and-replays a response; a nonce just blocks the repeat). TEMPLATE RENDER (fill a text/HTML template with data — emails, receipts, message bodies): `POST ${API}/template-render {template, data}` (member, stateless) renders a mustache-lite template: `{{name}}` inserts an HTML-escaped value, `{{{html}}}` inserts raw, `{{#items}}...{{.}}...{{/items}}` loops an array, `{{#flag}}...{{/flag}}` / `{{^flag}}...{{/flag}}` show/hide a block, and `{{a.b}}` reads nested fields. Use THIS to build a confirmation email or a personalized message from a stored template + data. PHONE NORMALIZE (clean up phone numbers to a standard E.164 format — for storage, SMS, dedupe): `POST ${API}/phone-normalize {phone, country?}` (public, stateless) returns {e164, valid, country_code}. A number that already starts with + is trusted; otherwise pass a `country` (like 'us' or the dialing code '44') and it adds the prefix and strips a national leading 0. It is best-effort (not a full validator). Use THIS before saving a phone number so they all match. MARKETING ATTRIBUTION (first-touch / last-touch — which channel gets credit for a signup or sale): call `POST ${API}/attribution/touch {channel, campaign?}` on each visit to log a touchpoint; then `GET ${API}/attribution/for?user=<id>&model=last` (or first) returns the channel that gets the credit, and `GET ${API}/attribution/report?model=first` (ADMIN) tallies channels across all users. Use THIS to answer 'where do my conversions come from'. QUEST CHAINS (a guided multi-step journey where order matters — onboarding checklists that must be done in sequence, tutorials, achievement chains): an ADMIN `POST ${API}/quests {key, steps:[...]}` defines the ordered steps; a member `POST ${API}/quests/<key>/advance {step}` completes the NEXT step (doing them out of order or repeating one is refused with the expected step), and `GET ${API}/quests/<key>/me` shows progress + percent. Use THIS when steps have a required order (the sibling ${API}/onboarding is an unordered checklist). EXCERPT / SMART TRUNCATE (a teaser or meta-description from long text — post previews, card summaries, SEO tags): `POST ${API}/excerpt {text, chars?, words?, strip_html?, suffix?}` (public, stateless) trims to N characters (on a word boundary) or N words and appends an ellipsis; pass `strip_html:true` to drop tags first. Use THIS for clean previews instead of a raw substring that cuts mid-word. ENTITY FIELDS (attach extra custom attributes to a record without changing its table — custom fields, metadata, per-item settings): an ADMIN `POST ${API}/entity-fields/<type>/<id> {fields:{color:'red', size:'L'}}` stores arbitrary key/values against any record (identified by a type + id you choose), and `GET ${API}/entity-fields/<type>/<id>` reads them back as an object. Use THIS for user-defined/custom fields or sparse metadata you do not want as real columns. USAGE METERING (count usage for billing or a usage dashboard — API calls, exports, generations per customer): `POST ${API}/usage-meter/record {meter, period?, amount?}` (member) atomically bumps a cumulative counter (e.g. meter 'api_calls', period '2026-08'); an ADMIN reads `GET ${API}/usage-meter/total?meter=api_calls` for the running count + summed amount, or `GET ${API}/usage-meter?meter=` for the per-period breakdown. Use THIS to track how much each customer used (the sibling ${API}/rate-policies ENFORCES a per-window cap; this one just COUNTS). ENVIRONMENT CONFIG (per-environment settings with a promote step — dev vs staging vs prod values): an ADMIN `POST ${API}/env-config/<env> {key, value}` stores a setting for an environment, `GET ${API}/env-config/<env>` reads them all, and `POST ${API}/env-config/promote {from, to, keys?}` copies settings from one environment to another (all keys or a named subset). Use THIS to keep separate config per environment and roll changes forward (the plain ${API}/config is a single unscoped set). ADDRESS FORMAT (turn structured address parts into a correctly-laid-out mailing label): `POST ${API}/address-format {line1, line2?, city, region?, postal?, country?}` (public, stateless) returns {formatted, lines} in the conventional multi-line layout for the country (US does City, ST ZIP on one line; UK puts the postcode on its own line; a sensible default otherwise). Use THIS to render a mailing address block. WEIGHTED BALLOTS (a vote where some voters count more than others — shareholder votes, weighted polls, board decisions): an ADMIN `POST ${API}/ballots {key, options:[...]}` opens a poll; a member `POST ${API}/ballots/<key>/vote {choice, weight?}` casts a vote whose `weight` is their voting power (a re-vote replaces the old one); `GET ${API}/ballots/<key>/results` returns the summed weight per option and the winner. Use THIS when votes are not one-person-one-vote (the plain ${API}/polls is unweighted). GEO DISTANCE (how far apart are two points — 'X km away', shipping zones, nearest-store labels): `POST ${API}/geo-distance {from:{lat,lng}, to:{lat,lng}, unit?}` (public, stateless) returns the great-circle {distance, bearing} in km (or mi). Use THIS for a distance label between two coordinates (to FILTER a table by radius instead, give the table a `geo` config and use the built-in nearby search). RRULE / RECURRENCE (expand a repeating schedule into actual dates — recurring events, subscriptions, 'every other Tuesday'): `POST ${API}/rrule {start, freq, interval?, count?, until?, byday?}` (public, stateless) returns the next occurrence dates. freq is daily/weekly/monthly/yearly, `interval` skips (every 2 weeks), `byday:['mo','we','fr']` picks weekdays, and `count`/`until` bound the list. Use THIS to show upcoming dates for a recurring rule without a full calendar library. CONTACT FREQUENCY CAP (do not over-message a person — 'max 3 emails per week to any one user'): before sending, call `POST ${API}/frequency-cap/consume {recipient, channel?, max, window_sec}` — it returns {allowed} and only lets `max` through per window per recipient; send only when allowed is true. `GET ${API}/frequency-cap/check` peeks without counting. Use THIS to prevent notification fatigue (the sibling ${API}/rate-policies caps an ACTION globally; this caps messages PER RECIPIENT). BUSINESS DAYS (working-day math — SLA due dates, delivery estimates, 'ships in 3 business days'): `POST ${API}/business-days {from, to, holidays?}` (public, stateless) counts business days between two dates (skipping weekends and any holidays you pass), or `POST ${API}/business-days {from, add, holidays?}` returns the date N business days later. Use THIS for deadlines that skip weekends instead of raw date math. CHECKSUM (hash a value for integrity or de-duplication — detect changed content, dedupe uploads): `POST ${API}/checksum {text, algo?}` (public, stateless) returns the hex {hash} (sha-256 by default; sha-1 / sha-512 too). Use THIS to fingerprint content so you can tell if it changed or already exists. SPLIT AMOUNT (divide money fairly to the cent — bill splitting, payouts, revenue share): `POST ${API}/split-amount {amount, ways}` splits evenly, or `{amount, weights:[...]}` splits in proportion; the leftover cents are distributed so the shares sum EXACTLY to the amount (no rounding drift). Use THIS instead of amount/n which loses or gains a cent. STRING SIMILARITY (fuzzy matching — 'did you mean', typo-tolerant search, dedupe near-identical records): `POST ${API}/string-similarity {a, b}` (public, stateless) returns {levenshtein (edit distance), similarity (0-1), dice (bigram overlap)}. Use THIS to detect duplicate names/entries or suggest a correction (a high similarity or low levenshtein means they are close). MASK (hide PII for display — show a card as ****1234, an email as j****@x.com): `POST ${API}/mask {value, type?, keep?}` (public, stateless) returns {masked}. type=email keeps the first letter + domain, card/phone keep the last 4 digits, generic keeps the last N characters. Use THIS to safely show a partial identifier without exposing the whole thing. SENTIMENT (is this review/comment/message positive or negative?): `POST ${API}/sentiment {text}` (public, stateless) returns {score, comparative, label:'positive'|'negative'|'neutral', positive:[words], negative:[words]} using a built-in word list with basic negation ('not good' reads negative). It is a lightweight heuristic (not an AI model). Use THIS to flag unhappy feedback or color-code comments. GIFT REGISTRY (a wishlist others can claim so a gift is not bought twice — weddings, baby showers, secret santa, team wishlists): a member `POST ${API}/gift-registry {title, url?, price?, qty?}` adds an item to THEIR registry; someone else views it at `GET ${API}/gift-registry/user/<ownerId>` and claims one with `POST ${API}/gift-registry/<id>/claim` — the claim is atomic, so once the quantity is taken others get a 409. The owner sees only how many remain, NOT who claimed (keep the surprise). `POST ${API}/gift-registry/<id>/unclaim` frees it again. Use THIS for any 'reserve so no duplicates' wishlist. CURRENCY FORMAT (display money correctly for a currency/locale — $1,234.50, 1.234,50 EUR, no-decimal yen): `POST ${API}/currency-format {amount, currency?, locale?}` (public, stateless) returns the localized {formatted, symbol} using Intl. Use THIS to render prices instead of hand-formatting (the sibling ${API}/fx/convert changes the currency; this one just DISPLAYS it). LUHN CHECK (validate a card / account / ID number's checksum before you submit it): `POST ${API}/luhn {number}` (public, stateless) returns {valid, check_digit} using the Luhn mod-10 algorithm (spaces and dashes are ignored). Use THIS for instant client-side validation of a card or membership number (it does NOT verify the account exists — just the checksum). INVENTORY LOTS / FEFO (batch + expiry stock — perishables, pharma, food, anything with a use-by date): an ADMIN `POST ${API}/inventory-lots {sku, qty, expires?, lot?}` receives a batch; `POST ${API}/inventory-lots/issue {sku, qty}` consumes stock EARLIEST-EXPIRY-FIRST across lots (atomic, refuses if not enough); `GET ${API}/inventory-lots?sku=` shows lots + total, and `GET ${API}/inventory-lots/expiring?days=30` lists what is about to expire. Use THIS when expiry matters (the plain stock endpoints do not track lots/expiry). RANKED-CHOICE / INSTANT-RUNOFF VOTING (a fairer poll where voters RANK the options — board elections, 'pick a winner' polls): an ADMIN `POST ${API}/ranked-vote {key, candidates:[...]}` opens it; a member `POST ${API}/ranked-vote/<key>/ballot {ranking:[...]}` submits their order of preference; `GET ${API}/ranked-vote/<key>/results` runs the instant-runoff (eliminate the last-place option, transfer its votes, repeat until someone has a majority) and returns the winner + each round. Use THIS instead of a plain plurality poll when you want a majority winner. COLOR CONVERT (translate a color between hex, rgb, and hsl — theme editors, design tools): `POST ${API}/color-convert {color}` (public, stateless) accepts #hex, rgb(...), or hsl(...) and returns all three plus ready-to-use css strings. Use THIS to normalize or transform user-entered colors. HUMANIZE (turn raw numbers/dates into friendly display text — file sizes, durations, counts, '3 days ago'): `POST ${API}/humanize {value, type}` (public, stateless). type=bytes (1536 becomes 1.5 KB), duration (seconds become '1h 1m 1s'), number (1500 becomes 1.5K), ordinal (23 becomes 23rd), or relative (a timestamp becomes '3 days ago' / 'in 2 hours'). Use THIS for display strings instead of hand-formatting. ID GENERATE (make unique identifiers — order numbers, tokens, keys): `POST ${API}/id-generate {type?, count?, prefix?, size?}` (member) returns {ids}. type=uuid (a v4 UUID), ulid (26-char, time-sortable), short (a compact base62 id), or nano (url-safe). Use THIS for a random unique id (for a GUARANTEED-unique claimable slug/handle use ${API}/handles instead). EXPENSE CLAIMS (submit-and-approve expense reports for a team/finance app): a member `POST ${API}/expense-claims {amount, category?, description?, receipt_url?}` submits a claim; an ADMIN works the queue `GET ${API}/expense-claims?status=submitted` and moves each `POST ${API}/expense-claims/<id>/approve` (or `/reject {note}`) then `/reimburse`. Amounts are kept exact in cents and the queue reports a running total. Use THIS for expense reimbursement flows. LOYALTY PUNCH CARDS (buy-N-get-1-free stamp cards for a cafe/salon/loyalty app — the paper punch card, done right): ADMIN defines a program `POST ${API}/punch-cards {key, title?, punches_needed, reward?}` (punches_needed >= 1); staff stamp a member `POST ${API}/punch-cards/<key>/punch {user}` -> `{punches, needed, rewards_available, rewards_earned, total}` where `punches` cycles 0..needed-1 and a full card bumps `rewards_available` (carry-over is automatic across cycles). The member reads their own card `GET ${API}/punch-cards/<key>/me` and cashes one in `POST ${API}/punch-cards/<key>/redeem` (409 when none pending). `GET ${API}/punch-cards/<key>` is the public program, `GET ${API}/punch-cards` lists them, admin `DELETE ${API}/punch-cards/<key>`. Stamps + redemptions are atomic integer math (no float rounding), one card per (program,user). Use THIS for loyalty stamp cards instead of counting rows yourself. CARD TYPE (detect a payment-card brand from its number, client- or server-side, WITHOUT storing it): `POST ${API}/card-type {number}` -> `{brand, luhn_valid, length, length_ok}`. Brand comes from the IIN/prefix (visa, mastercard incl. the 2221-2720 range, amex, discover, diners, jcb, or unknown), `luhn_valid` runs the Luhn checksum, and `length_ok` checks the digit count against the brand (Amex 15, most others 16). Spaces/dashes are ignored; a number with no digits is refused (400). Stateless + storeless — nothing is persisted. Use THIS to show a card-brand icon and pre-validate a card field before hitting your processor. BASE64 (encode/decode text to base64 or base64url, UTF-8 safe): `POST ${API}/base64 {text, mode:'encode'|'decode', urlsafe?}` -> `{result}`. `encode` handles any Unicode (emoji, accents) correctly; `decode` accepts standard OR url-safe input automatically and 400s on invalid base64; `urlsafe:true` emits the `-`/`_` no-padding variant. Stateless. Use THIS for encoding a token/blob for a URL or data field instead of shipping your own encoder. CONTENT-HASH DEDUP (SHA-256 fingerprint store to catch duplicate uploads/submissions WITHOUT keeping the content): a member `POST ${API}/content-hash {content}` (or `{hash}` if you already computed it) -> `{hash, duplicate, first_seen, hits}` — the first time content is seen it is recorded (duplicate:false); identical content later returns duplicate:true plus a running hit count and WHEN it was first seen. `GET ${API}/content-hash/<hash>` (member) checks whether a fingerprint is known; admin `GET ${API}/content-hash` lists recent ones and `DELETE ${API}/content-hash/<hash>` forgets one. Only the 64-char hash is stored, never the content. Use THIS to reject re-uploads / detect repost spam / dedupe imports instead of comparing full blobs. TEMPORARY BAN LIST (block an abuser for a while — a user id, IP-hash, email, or any key): an ADMIN `POST ${API}/bans {key, seconds?, reason?}` bans until now+seconds (omit `seconds` for a permanent ban); a PUBLIC `GET ${API}/bans/<key>` -> `{banned, until, remaining, reason}` where an EXPIRED ban automatically reads banned:false — so your app just checks this before letting the key act. Re-banning the same key updates in place; admin `DELETE ${API}/bans/<key>` lifts it and `GET ${API}/bans` lists the currently-active ones. Use THIS for rate-limit bans / suspension lists instead of a status column you have to expire yourself. ACCESS-VIEW LOG (audit who viewed what — a read trail for compliance/analytics): a signed-in member `POST ${API}/access-log {resource, note?}` records that THEY viewed a resource (append-only, actor = the caller); an ADMIN reads the trail `GET ${API}/access-log?resource=&actor=&limit=` (newest first, filterable) or a rollup `GET ${API}/access-log/summary[?resource=]` -> per-resource `{views, viewers}` (viewers = distinct actors). Use THIS for 'who accessed this record' audit trails and popularity counts instead of scattering view-counters across tables. MARKDOWN -> SANITIZED HTML (render user-written Markdown to SAFE HTML for a comment/post/description): `POST ${API}/markdown {text}` -> `{html}`. ALL input is HTML-escaped FIRST so no raw HTML or <script> can pass through — only a known tag set is emitted. Supports #..###### headings, **bold**/_italic_, `inline code` + ``` fenced blocks ```, [text](url) links (http/https/mailto ONLY — anything else renders as plain text), -/* and 1. lists, > blockquotes, --- rules, and paragraphs. Use THIS to safely display Markdown instead of dangerouslySetInnerHTML on unsanitized input — the escaping is the whole point. PRORATION (what to charge when a subscription changes mid-cycle): `POST ${API}/proration {new_price, old_price?, period_start, period_end, change_date?}` -> `{days_total, days_remaining, unused_credit_cents, new_charge_cents, net_cents}` (money in cents; `net_cents` negative = a credit). It computes the unused credit from the old plan and the prorated charge for the new plan over the remaining days of the period. Stateless. Use THIS for upgrade/downgrade math instead of rolling your own day-counting. PER-CUSTOMER CREDIT LIMIT (a store credit line / net-terms account per member — charge now, pay later, capped): an ADMIN sets it `POST ${API}/credit-limit {user, limit}`; charges draw it down `POST ${API}/credit-limit/<user>/charge {amount}` (REFUSED with 409 if it would exceed the limit — the guard is atomic), payments pay it back `POST ${API}/credit-limit/<user>/pay {amount}` (floored at 0). `GET ${API}/credit-limit/<user>` -> `{limit_cents, balance_cents, available_cents}` (a member may read their OWN line; admins read anyone), `GET ${API}/credit-limit` lists all, `DELETE ${API}/credit-limit/<user>` removes one. Balance kept in cents, one line per user. Use THIS for net-30 / house-account / spending-cap features instead of summing an orders table. COMMISSION (calculate a sales commission — flat OR tiered): `POST ${API}/commission {amount, rate?, tiers?}` -> `{commission, effective_rate, breakdown}`. Flat: pass `rate` as a FRACTION (0.1 = 10%). Tiered: pass `tiers:[{upto, rate}]` for MARGINAL brackets (like progressive tax — each band of the amount is taxed at its own rate; the last tier may omit `upto` for 'everything above'); tiers can be given out of order. The `breakdown` shows each bracket's band + commission. Stateless (amounts are numbers, commission rounds to cents). Use THIS for rep payouts / affiliate cuts instead of hand-rolling bracket math. SALES QUOTA (track a rep's target vs attainment per period): an ADMIN sets it `POST ${API}/sales-quota {rep, period, target}` (rep is any label — a name/email/id; period like '2026-Q1'); record closed business `POST ${API}/sales-quota/<rep>/<period>/record {amount}` (a NEGATIVE amount corrects, floored at 0). `GET ${API}/sales-quota/<rep>/<period>` -> `{target_cents, attained_cents, pct, remaining_cents}`; `GET ${API}/sales-quota?period=<p>` lists every rep RANKED by attainment (a leaderboard); `DELETE` removes one. Money in cents, one row per (rep, period). Use THIS for quota dashboards / commission-attainment tracking. TAX-EXEMPTION REGISTRY (record a customer's resale/exemption certificate so checkout can skip tax): an ADMIN registers `POST ${API}/tax-exempt {customer, certificate, region?, expires?, note?}` (one cert per customer key); a check `GET ${API}/tax-exempt/<customer>` -> `{exempt, certificate, region, expires}` where an EXPIRED certificate automatically reads exempt:false (and hides the cert). `GET ${API}/tax-exempt` lists them, `DELETE ${API}/tax-exempt/<customer>` revokes. Use THIS to gate tax calculation on a valid, unexpired certificate instead of a boolean flag you have to expire yourself. ACCOUNT HIERARCHY (a parent/child tree of orgs — companies -> divisions -> teams, or any nested structure): an ADMIN defines nodes `POST ${API}/account-hierarchy {key, name?, parent?}` (parent = another key, or null for a root; CYCLES are refused). Reads are public: `GET ${API}/account-hierarchy/<key>` -> `{node, ancestors, children}` (ancestors walk up to the root), `GET ${API}/account-hierarchy/<key>/descendants` -> the flattened subtree, `GET ${API}/account-hierarchy` -> the whole nested forest. `DELETE ${API}/account-hierarchy/<key>` removes a node and REPARENTS its children to its own parent (no orphans). Use THIS for org charts / category trees / nested cost centers instead of storing parent ids on a flat table and walking them client-side. ROLLING UNIQUES (an EXACT distinct-value counter per stream — unique visitors, devices, coupon redemptions): a signed-in member records a value `POST ${API}/rolling-uniques/<stream> {value}` -> `{added, distinct}` (dupes are ignored, `added` tells you if it was new); anyone reads `GET ${API}/rolling-uniques/<stream>` -> `{distinct}`, or `?since=<iso>` for the count within a time window (the 'rolling' part); an ADMIN `DELETE ${API}/rolling-uniques/<stream>` resets it. One row per (stream, value). Use THIS for 'how many unique X' instead of a counter you have to dedupe yourself. COMPARISON SETS (a 'compare tray' — a member collects a few item references to compare side-by-side): `POST ${API}/comparison {name, items}` creates/replaces a named set (deduped, capped at 24); `POST ${API}/comparison/<name>/add {item}` and `/remove {item}` tweak one item; `GET ${API}/comparison/<name>` reads it, `GET ${API}/comparison` lists the member's sets, `DELETE ${API}/comparison/<name>` drops one. Per-member, one row per (user, name). Use THIS for product-compare / shortlist trays instead of juggling the list in client state. DEPOSIT HOLDS (a refundable deposit against a booking/order — hold now, keep or refund later): an ADMIN places one `POST ${API}/deposit-holds {amount, ref?, user?, reason?}` (amount in dollars -> stored cents, status 'held'); then CAPTURE it `POST ${API}/deposit-holds/<id>/capture` (keep the money) or RELEASE it `POST ${API}/deposit-holds/<id>/release` (refund) — each transition is atomic, so a resolved hold can't change again (409). `GET ${API}/deposit-holds/<id>` reads one (admin, or the member it's tied to); `GET ${API}/deposit-holds?status=&ref=&user=` lists with per-status totals. Use THIS for security/damage deposits instead of a boolean + a separate amount column. MAINTENANCE SCHEDULE (recurring service due-dates for assets — filters, inspections, equipment): an ADMIN registers `POST ${API}/maintenance-schedule {key, interval_days, name?, last_serviced?}` and the server computes `next_due`; marking it done `POST ${API}/maintenance-schedule/<key>/service {date?}` advances next_due from the service date. `GET ${API}/maintenance-schedule/<key>` -> `{…, overdue, days_until}`, `GET ${API}/maintenance-schedule?overdue=1` lists only overdue items, `DELETE` removes one. Use THIS for 'what's due for service' instead of recomputing dates client-side. CAPACITY FORECAST (capacity-vs-demand roll-up for planning): `POST ${API}/capacity-forecast {periods:[{label?, capacity, demand}]}` -> each period's `{utilization, shortfall, surplus}` plus `total_capacity/total_demand/total_shortfall/total_surplus/overall_utilization`. Stateless. Use THIS to turn a capacity plan into a utilization/shortfall report (staffing, inventory, server capacity) instead of computing the percentages by hand. CONTACT ENRICHMENT (a side key/value field store per contact — firmographics, source, tags — kept OUT of the main contact record): an ADMIN upserts fields `POST ${API}/contact-enrichment {contact, fields:{industry:'saas', size:'50'}}` (merges, doesn't replace); reads one `GET ${API}/contact-enrichment/<contact>` -> `{fields:{…}}`, or SEGMENTS `GET ${API}/contact-enrichment?field=industry&value=saas` -> the contacts that match; `DELETE ${API}/contact-enrichment/<contact>[?field=]` drops one field or the whole contact. Use THIS for enrichment/append data you don't want to schema onto the contact table, and for 'find everyone where field = X'. DISCOUNT STACK (decide how multiple discounts combine, and the final price): `POST ${API}/discount-stack {price, discounts:[{code, type:'percent'|'fixed', value, stackable?}]}` -> `{final_cents, discount_cents, applied, strategy}`. All `stackable:true` discounts apply TOGETHER (percents compound on the running total, fixed subtract, clamped at 0); each non-stackable is considered ALONE; the engine returns whichever combination gives the LOWEST price. Money in cents. Use THIS for coupon-stacking rules at checkout instead of hand-coding which promos combine. OPPORTUNITY FORECAST CATEGORIES (a sales forecast rolled up by commit stage): an ADMIN tags each deal `POST ${API}/forecast-categories {ref, amount, category, period?, name?}` where category is pipeline / best_case / commit / closed / omitted (upsert by ref). `GET ${API}/forecast-categories?period=<p>` -> per-category totals PLUS a forecast `{commit_cents (commit+closed), best_case_cents (+best_case), pipeline_cents (+pipeline), closed_cents}` and the deal list. `GET ${API}/forecast-categories/<ref>` reads one, `DELETE` removes it. Use THIS for a weighted sales forecast dashboard instead of summing a deals table by hand. TERRITORY RULES (route a lead/account to the right owner by rules — sales territories, support regions): an ADMIN defines territories `POST ${API}/territory {key, rules, name?, owner?, priority?}` where `rules` is a JSON object of allowed values per field (e.g. `{country:['US'], industry:['saas']}`; `postal_prefix:['9']` PREFIX-matches the input's postal; empty rules = catch-all). Then `POST ${API}/territory/match {country, postal, industry, …}` returns the HIGHEST-PRIORITY territory whose rules all fit. `GET/DELETE ${API}/territory/<key>` and `GET ${API}/territory` manage them. Use THIS for lead routing / territory assignment instead of a pile of if-statements. READ RECEIPTS (who has read a message/announcement/doc — the seen-by list): a member marks it read `POST ${API}/read-receipts/<message>` (idempotent) -> `{count, mine}`; `GET ${API}/read-receipts/<message>` returns the count + whether the caller read it, and for an ADMIN the full reader list; `DELETE` (admin) clears it. Use THIS for group-message 'seen by 5' / announcement read-tracking (for 1:1 DMs, `/dm` already has read state). BROADCAST FAN-OUT LOG (track a bulk send — email/SMS/push blast — as it fans out): an ADMIN opens one `POST ${API}/broadcast-log {channel, recipients, subject?}` (status 'sending'); a worker reports progress `POST ${API}/broadcast-log/<id>/progress {sent?, failed?, done?}` (counts ACCUMULATE atomically; `done:true` marks it finished). `GET ${API}/broadcast-log/<id>` and `GET ${API}/broadcast-log` read them, `DELETE` removes one. Use THIS to record + monitor a campaign send instead of a bespoke status table. DUNNING (failed-payment retry state machine — recover a declined subscription/invoice charge over N attempts): an ADMIN opens a case `POST ${API}/dunning {ref, amount?, user?, max_attempts?, retry_days?}` (status 'active', next_retry scheduled); each retry outcome `POST ${API}/dunning/<ref>/attempt {success, error?, retry_days?}` either RECOVERS it (success) or bumps attempts + schedules the next retry until max_attempts -> 'failed'; `POST ${API}/dunning/<ref>/cancel` stops it. `GET ${API}/dunning?due=1` lists cases whose next_retry has passed (feed your retry worker), `?status=` filters, `GET/DELETE ${API}/dunning/<ref>` manage one. Use THIS for card-decline recovery flows instead of a hand-rolled attempts column. GEOFENCE (is a point inside a region? — stateless): `POST ${API}/geofence {point:{lat,lon}, fence}` where fence is a `circle` {center:{lat,lon}, radius_m} (also returns distance_m), a `bbox` {min_lat,min_lon,max_lat,max_lon}, or a `polygon` {points:[{lat,lon}]} (ray-casting) -> `{inside, distance_m?}`. Use THIS for 'is the user in the delivery zone / at the venue / in this sales region' checks (pairs with `/geo-distance` for the distance-only case). SLOT CHECK (is a proposed appointment time free? — stateless): `POST ${API}/slot-check {proposed:{start,end}, busy:[{start,end}], buffer_minutes?}` -> `{available, conflicts}`. The buffer is applied on BOTH sides of the proposal (so a 15-min turnaround blocks back-to-back bookings). Use THIS to validate a booking against existing appointments + a turnaround buffer before you write it, instead of comparing intervals client-side. IBAN (validate a bank IBAN — stateless): `POST ${API}/iban {iban}` -> `{valid, country, length_ok, checksum_ok, formatted}`. Checks the per-country length AND the ISO 7064 mod-97 checksum (spaces ignored); `formatted` groups it in fours. Use THIS to validate a bank account field before saving (pairs with `/card-type` for cards). CRON PREVIEW (show when a cron schedule will next run — stateless): `POST ${API}/cron-preview {expression, count?, from?}` -> `{next:[iso,…]}`, the next N UTC fire times of a standard 5-field cron (minute hour day-of-month month day-of-week; supports *, ranges a-b, lists a,b, steps */n). DOM/DOW use the usual cron OR rule when both are set. Use THIS to preview a schedule in a UI ('runs next at …') without a cron library. PASSWORD POLICY (a site-configurable password rule set + a checker — the RULES, vs `/password-strength` which is a METER): an ADMIN sets the policy `POST ${API}/password-policy {min_length?, require_upper?, require_lower?, require_digit?, require_symbol?, min_classes?, disallow_common?}`; the current rules are PUBLIC `GET ${API}/password-policy` (so a signup form can display them) and a check `POST ${API}/password-policy/check {password}` -> `{valid, failures:[…]}` lists exactly which rules failed. Use THIS to enforce YOUR password requirements consistently on signup/reset instead of hard-coding them in each form. CHECKLISTS (a reusable checklist template + per-member completion — onboarding steps, pre-flight lists, move-in tasks): an ADMIN defines one `POST ${API}/checklist {key, items:[{id?,label}], title?}` (string items get sequential ids); a member checks items off `POST ${API}/checklist/<key>/check {item}` (and `/uncheck`) and reads their own progress `GET ${API}/checklist/<key>/me` -> `{done, total, remaining, pct, complete}`. `GET ${API}/checklist[/<key>]` reads the template(s) publicly; `DELETE` removes it. Progress is PER-MEMBER. Use THIS for any 'track completion of a fixed set of tasks' instead of a bespoke table. NUMBER TO WORDS (spell a number or money amount in English — for cheques, invoices, legal docs): `POST ${API}/number-to-words {number, currency?}` -> `{words}`. Plain: 1234567 -> 'one million two hundred thirty-four thousand five hundred sixty-seven'; decimals spell digit-by-digit ('three point one four'); with `currency` (usd/eur/gbp): 123.45 -> 'one hundred twenty-three dollars and forty-five cents' (singular/plural + pence handled). Stateless. Use THIS for the written-amount line on an invoice/cheque. VAT NUMBER (validate an EU/UK VAT number's FORMAT — structure only, not a live VIES lookup): `POST ${API}/vat-number {vat}` -> `{valid, country, format_ok, normalized}`. Strips spaces/dots, reads the 2-letter country, and checks the body against that country's pattern (~27 countries). Use THIS to sanity-check a VAT field at input (pairs with `/iban` for bank details); for a real existence check you'd still call VIES server-side. PLURALIZE (English inflection — 'you have 1 item' / '3 items' without hard-coding): `POST ${API}/pluralize {word, count?}` -> `{singular, plural, inflected, formatted?}`. It returns BOTH forms (handling irregulars like person/people, suffix rules like baby->babies, knife->knives, box->boxes, and uncountables like sheep), and with a `count` it picks the right form + a 'N words' phrase (case is preserved). Use THIS for grammatically-correct counts in UI copy instead of naive word+'s'. MIME DETECT (sniff a file's real type from its MAGIC BYTES, never the filename): `POST ${API}/mime-detect {base64|hex}` (the first bytes are enough) -> `{mime, ext, category, detected}`. Recognizes PNG/JPEG/GIF/WEBP/BMP, PDF, ZIP/GZIP, MP3/MP4/M4A/WAV/OGG, and more. Use THIS to validate an upload's actual content-type server-side before trusting a client-supplied type or extension. APPROVAL QUORUM (an N-of-M sign-off — needs `needed` distinct approvers before it passes): an ADMIN opens a request `POST ${API}/approval-quorum {key, needed, title?}`; members cast a vote `POST ${API}/approval-quorum/<key>/approve` (once each; `/revoke` withdraws while still open) and once the count hits `needed` it flips to 'approved' and locks. `GET ${API}/approval-quorum/<key>` shows the count + status + whether YOU approved (admins also see the approver ids). This is MANY-approver quorum — distinct from `/dual-approval` (2-party maker/checker). Use THIS for 'needs 3 sign-offs' gates. ISBN (validate a book ISBN + convert between ISBN-10 and ISBN-13 — stateless): `POST ${API}/isbn {isbn}` -> `{valid, type, check_ok, isbn10, isbn13}`. Hyphens/spaces are ignored; it runs the correct check-digit (mod-11 for 10, mod-10 for 13, X allowed) and, when valid, gives you BOTH forms. Use THIS to validate a book field and normalize to a single form. BARCODE (validate a retail barcode's check digit — stateless GTIN): `POST ${API}/barcode {code}` -> `{valid, type, check_digit, expected_check}`. Auto-detects EAN-13 / UPC-A(12) / EAN-8 by length and verifies the mod-10 check digit (reporting the expected one on a mismatch). Use THIS to sanity-check a scanned/typed barcode before saving (pairs with `/isbn` for books). INVENTORY COUNT (a stock-take / cycle-count log — record physical counts, flag variances, reconcile): an ADMIN records `POST ${API}/inventory-count {sku, expected, counted, note?}` and the server stores the variance (counted - expected); `POST ${API}/inventory-count/<id>/reconcile` closes it. `GET ${API}/inventory-count?sku=&status=&variance=1` lists (variance=1 = only non-zero discrepancies — your shrinkage report), `GET/DELETE ${API}/inventory-count/<id>` manage one. Independent of the live stock ledger. Use THIS for periodic stock-takes instead of overwriting your on-hand numbers. COLOR PALETTE (generate a harmonious palette from a base color — stateless): `POST ${API}/color-palette {color, scheme?}` -> `{base, scheme, colors:[hex,…]}`. Schemes: complementary (2), analogous (3), triadic (3), tetradic (4), monochromatic (5 tints/shades). Colors are derived by HSL rotation; accepts #rgb, #rrggbb, or a bare hex. Use THIS to build a theme from one brand color instead of hand-picking swatches. ROMAN (convert to/from Roman numerals, 1..3999 — stateless): `POST ${API}/roman {number}` -> `{roman}` OR `{roman}` -> `{number}`. Reverse conversion validates canonically (rejects IIII / VX). Use THIS for edition numbers, clock faces, outline numbering. WORD FREQUENCY (top terms in a block of text — stateless): `POST ${API}/word-frequency {text, top?, stopwords?}` -> `{total_words, unique_words, top:[{word,count}]}`. Lower-cased, split on non-letters, common stop-words removed by default (pass `stopwords:false` to keep them), `top` caps the list. Use THIS for tag clouds / keyword extraction / 'most mentioned' widgets. SEAT MAP (reserve individual seats from a named layout — events, tables, parking, desks): a member claims `POST ${API}/seat-map/<map>/reserve {seat|seats, holder?}` (a group is ALL-OR-NOTHING — if any seat is taken the whole request rolls back, so you never half-book); claiming a taken seat fails ATOMICALLY on the DB. `POST ${API}/seat-map/<map>/release {seat}` frees your own seat (admins free anyone's). `GET ${API}/seat-map/<map>` is the occupancy, `GET ${API}/seat-map/<map>/<seat>` one seat, `DELETE` (admin) clears the map. Use THIS for seat/space selection instead of racing UPDATEs. HOME FEED / TIMELINE (a social timeline of posts from the people you follow): pairs with the follow graph (`POST ${API}/follow/<userId>`). `GET ${API}/feed?table=<t>[&limit=&before=]` returns the rows of a `feed`-access table owned by whoever the signed-in caller follows, newest-first, excluding their own + trashed rows. Keyset-paginate with the returned `next_before` (pass it as `before`). The table must be `feed` access (public rows owned by members) — a private `user` table is rejected. Use THIS for a home timeline instead of fetching all posts and filtering client-side. DIRECT MESSAGES (1:1 private chat between two members): `POST ${API}/dm {to, body}` sends (to = the other member's id); `GET ${API}/dm/<otherId>[?limit=&before=&markRead=1]` returns that conversation newest-first (both directions share one thread) — `markRead=1` clears your unread from them. `GET ${API}/dm/threads` lists your conversations (each: `with`, `last` message, `unread`), `GET ${API}/dm/unread` → total unread, `POST ${API}/dm/<otherId>/read` marks a thread read. Only the two participants can see a thread. A `POST ${API}/dm` to someone who has BLOCKED you is refused with 403 `{code:'blocked'}` — surface a 'you can't message this member' notice. Use THIS for private messaging instead of a public table anyone can read. TIME & ATTENDANCE / CLOCK (HRMS — clock in/out, worked hours): a signed-in member clocks themselves. `POST ${API}/timeclock/in {at?, note?}` opens a shift (409 if already clocked in), `POST ${API}/timeclock/out {at?}` closes it → `{minutes, hours}`; `GET ${API}/timeclock/status` → `{clocked_in, since}`. `GET ${API}/timeclock/summary?employee=&from=&to=` → total hours over a period (an admin omits `employee` to get everyone). `GET ${API}/timeclock/entries` lists shifts. An admin can pass `employee` to act for anyone, and `POST ${API}/timeclock/entry {employee, clock_in, clock_out}` adds a corrected shift. Use THIS for attendance/hours instead of a plain table so double clock-ins are impossible and hours are computed for you. EFFECTIVE-DATED RECORDS (a value that changes over time you can query 'as of' any date — salary/title history, price history): ADMIN-only, `${API}/effective`. `POST ${API}/effective {subject, attribute, effective_date, value, note?}` records a dated change (`value` is any JSON; same subject+attribute+date upserts). `GET ${API}/effective?subject=<s>&attribute=<a>&as_of=<date>` returns the value in force on that date (the latest change on/before it) with which record applied; omit `as_of` for the full history. `GET ${API}/effective/snapshot?attribute=<a>&as_of=<date>` returns EVERY subject's value as of a date (e.g. everyone's salary on a pay date). Use THIS for anything where you must know the historical value at a point in time, instead of overwriting a column and losing the past. COURSE PROGRESS (LMS — lessons, a learner's completion %, prerequisites): an admin defines a course `POST ${API}/courses/<course> {items:[{item, prereq?, sort?}]}` (a `prereq` must be another item in the course). A signed-in member records THEIR OWN progress `POST ${API}/courses/<course>/complete {item, score?}` — refused (409 `prereq`) until the item's prerequisite is done — and reads it `GET ${API}/courses/<course>/progress` → `{completed, total, percent, items:[{item, done, score}]}`. `POST ${API}/courses/<course>/reset {item?}` un-completes one item or the whole course. An admin can pass `learner` to record/read for any student (instructor view). `GET ${API}/courses` lists courses. Use THIS for lesson/module completion + gating instead of a boolean column. QUIZ AUTO-GRADING (assessments where the answer key stays SERVER-SIDE — no cheating): an admin defines `POST ${API}/quizzes/<quiz> {questions:[{qid, answer, points?}], pass_pct?}` (answer can be a value, an array of acceptable values for any-of, or an array for an exact multi-select; case/space-insensitive). A signed-in member submits `POST ${API}/quizzes/<quiz>/grade {answers:{qid:answer}}` → `{score, max, percent, passed, results:[{qid, correct}]}` — the response NEVER contains the correct answers, and `GET ${API}/quizzes/<quiz>` hides the key from non-admins (takers see qids+points only). `GET ${API}/quizzes/<quiz>/attempts` returns the learner's past attempts. Use THIS whenever scoring must be trustworthy instead of grading in the browser. LOCALIZATION / i18n (the same UI strings or content in many languages, with fallback): reads are PUBLIC (no login — a multilingual site renders to anyone). Admin loads strings `POST ${API}/i18n {locale, entries:{'home.title':'Welcome', …}, namespace?}` (or a single `{locale, key, value}`); the site fetches `GET ${API}/i18n?locale=fr&fallback=en` → `{values:{key:string}}` where any key missing in `fr` falls back to `en` — so you render one flat dictionary. `GET ${API}/i18n/<key>?locale=&fallback=` gets one string, `GET ${API}/i18n/locales` lists which languages exist, `DELETE ${API}/i18n/<key>[?locale=]` removes a translation (one locale, or all). Use `namespace` to separate string sets (UI vs emails vs a page's content). Use THIS for translations instead of duplicating columns per language. " +
  "STOCK / INVENTORY LEDGER (real warehouse stock — on-hand that can't go negative, reservations, multi-location — NOT just a `qty` number on a product row): ADMIN-only, `${API}/stock/*`. Record a movement `POST ${API}/stock/moves {item, location?, qty, kind?, ref?, unit_cost?}` — qty POSITIVE = receipt, NEGATIVE = issue; an issue that would drive on-hand below zero is REFUSED (409 insufficient stock) unless you pass `allowNegative:true`. Read `GET ${API}/stock/level?item=<i>[&location=<l>]` → `{on_hand, reserved, available}` (available = on_hand − active reservations; omit location to aggregate across all), or `GET ${API}/stock/levels[?location=&below=N]` for every item (a stock-on-hand report; `below=N` → the low-stock/reorder list). RESERVE stock for an order without shipping it: `POST ${API}/stock/reserve {item, location?, qty, ref?}` earmarks it (409 if it would oversell available), then `POST ${API}/stock/reservations/<id>/release` frees it or `POST ${API}/stock/reservations/<id>/fulfill` ships it (issues the qty + closes the reservation). Move between warehouses with `POST ${API}/stock/transfer {item, from, to, qty}` (guarded so you can't transfer more than the source holds). `GET ${API}/stock/moves` / `${API}/stock/reservations` list the history. Quantities are exact to 3 decimals (kg/litres OK). Use THIS for anything that must not oversell — the no-negative guarantee + reservations are the point — instead of a hand-maintained quantity field that races. INVENTORY VALUATION (what the stock on hand is WORTH — for a balance sheet / stock report): pass `unit_cost` on receipts, then `GET ${API}/stock/valuation[?item=&location=]` → each item+location's `{on_hand, avg_cost, value}` + a `total_value`, where avg_cost is the WEIGHTED-AVERAGE of the costed receipts (issues/transfers don't move it) and value = on_hand × avg_cost. An item received without any cost reads avg_cost/value null. LOT / BATCH / SERIAL + EXPIRY (track WHICH batch each quantity is — food/pharma expiry, recalls, serialized units): pass `lot` (and optional `expiry` date) on a `${API}/stock/moves` receipt; an issue that names a `lot` can't take more than that lot holds (409). `GET ${API}/stock/lots?item=&location=[&expiring_before=<date>]` → on-hand per lot with expiry, earliest-expiry-first (and an expiring-soon report). `GET ${API}/stock/allocate?item=&location=&qty=N` → a FEFO pick plan (which lots to pull, earliest expiry first) with any shortfall. A SERIAL number is just a lot with qty 1. Non-lot moves keep working unchanged. REORDER / REPLENISHMENT (auto-suggest what to buy when stock runs low): `POST ${API}/stock/reorder-rules {item, location?, reorder_point, reorder_qty?, target?, supplier?}` sets a per-item minimum; `GET ${API}/stock/reorder-rules` lists, `DELETE ${API}/stock/reorder-rules/<item>[?location=]` removes. `GET ${API}/stock/replenishment[?location=]` → every item whose AVAILABLE (on-hand − reservations) has dropped to/below its reorder_point, with a `suggested_order` (to `target` if set, else the fixed `reorder_qty`, else back up to the point) + supplier — a ready-to-order buy list. BILL OF MATERIALS (what a product is built from — for manufacturing/assembly/kits): ADMIN-only, `${API}/bom/*`. Define a recipe `POST ${API}/bom {product, notes?, lines:[{component, qty}]}` (SKU-like names; a component can itself be a built product → multi-level); `GET ${API}/bom` lists products with BOMs, `GET/DELETE ${API}/bom/<product>` fetch/remove one. The key call is EXPLODE: `GET ${API}/bom/<product>/explode?qty=N` recursively expands to the aggregated LEAF (raw) `components:[{component, qty}]` needed to build N (plus the `subassemblies` built along the way) — cycles are refused (409). Feed the exploded components into a stock issue to build the product. WORK ORDERS (actually build a product from its BOM — consumes components, produces finished goods): `POST ${API}/work-orders {product, qty, location?}` plans a build (needs a BOM); `GET ${API}/work-orders/<id>` shows the exploded `requirements` with availability + a `can_build` flag; `POST ${API}/work-orders/<id>/build` issues the leaf components from stock (all-or-nothing, 409 if short) and receives the finished product valued at the ROLLED-UP component cost (idempotent — re-build → 409); `POST ${API}/work-orders/<id>/cancel` cancels a planned one. MRP (what to buy to meet a production plan): `POST ${API}/mrp {demand:[{product, qty}], location?}` explodes the whole basket, nets the aggregated component needs against on-hand → `{requirements:[{component, required, available, shortfall}], shortfalls}` (a demanded product with no BOM is treated as a purchased item). " +
  "DOCUMENT FLOW (quotes → orders → invoices → payments for sales/procurement — line-item business documents with totals + tax + a paper trail, NOT flat rows): ADMIN-only, `${API}/documents/*`. Create `POST ${API}/documents {type, party?, date?, currency?, ref?, memo?, status?, lines:[{item?, description?, qty, unit_price, tax_rate?, dim?}]}` — `type` is any string ('quote','sales_order','invoice','purchase_order','bill','credit_note',…); each line's subtotal (qty×price), tax (tax_rate is a PERCENT 0–100), and total are computed SERVER-SIDE, summed into the document `{subtotal, tax, total}`; every doc gets an auto number per type (QUOTE-00001, INVOICE-00001, independent counters). The KILLER action is CONVERT: `POST ${API}/documents/<id>/convert {type, source_status?}` copies the lines into a NEW document of the target type and links it via `from_id` — so quote→order→invoice threads the whole deal (optionally stamp the source's status, e.g. quote→'accepted'). Move status with `POST ${API}/documents/<id>/status {status}` (your own flow: draft/sent/accepted/paid/…). Read `GET ${API}/documents/<id>` (header+lines) and `GET ${API}/documents[?type=&party=&status=&from_id=&from=&to=]` (list; `from_id` finds a doc's children). `PATCH ${API}/documents/<id>` edits the header anytime, but LINES can only be changed while status is 'draft' (a sent/paid doc is locked — 409); DELETE is draft-only too (cancel via status otherwise). Money exact to the cent. Use THIS for any quote/order/invoice/bill instead of a plain table so totals, tax, numbering, and the quote→invoice trail are handled for you. POST TO THE LEDGER (turn an invoice/bill into real double-entry accounting in one call): `POST ${API}/documents/<id>/post {total_account, base_account, tax_account?, total_side?}` builds a balanced journal entry from the doc's totals — for a SALE invoice `{total_account:'accounts_receivable', base_account:'revenue', tax_account:'tax_payable'}` posts Dr A/R (total), Cr Revenue (subtotal), Cr Tax (tax); for a PURCHASE bill add `total_side:'credit'` so it mirrors (Cr A/P, Dr Expense, Dr Tax). It's IDEMPOTENT — the doc records its `ledger_entry_id`, so a second post is refused (409 `posted`) — and it respects the period lock. Use this on invoice-confirm/payment so your books tie out automatically instead of hand-writing journal entries. POST TO STOCK (fulfil a document = move its line items in inventory): `POST ${API}/documents/<id>/post-stock {location?, direction?}` issues (sales) or receives (purchase) each line that names an `item` — a sales_order/invoice ISSUES (reduces on-hand), a purchase_order/bill RECEIVES (raises it, carrying the line's unit_price as cost so valuation works); direction is inferred from the doc type or forced with `direction:'issue'|'receive'`. It's IDEMPOTENT (the doc's `stock_posted` flag; re-post → 409) and ALL-OR-NOTHING for issues (availability is pre-checked across all lines, summing repeats of the same item, so a multi-line order never half-ships — 409 `stock` with the short item if any line can't be met). Use it on order-confirm/ship so inventory and the paperwork stay in lockstep. PAYMENTS / OUTSTANDING (record what's been paid against an invoice/bill; every doc reports `paid` + `outstanding`): `POST ${API}/documents/<id>/allocations {amount, ref?, memo?, date?}` applies a payment/credit (refused if it exceeds the outstanding unless `allowOverpay`), `GET …/allocations` lists them with paid/outstanding, `DELETE …/allocations/<allocId>` unapplies one. Set a doc's `due_date` (on create or PATCH) to drive aging. AR/AP AGING (a receivables/payables report — who owes what, how overdue): `GET ${API}/documents/aging?type=invoice[&as_of=&party=&buckets=30,60,90]` → open docs bucketed current/1-30/31-60/61-90/91+ by days past `due_date` (or doc_date), grouped `parties:[{party,total,aged}]` with `totals`. Fully-paid, draft, cancelled and void docs are excluded. Use `type=bill` for payables. TAX SUMMARY (a VAT/GST/sales-tax return — tax you collected vs tax you paid): `GET ${API}/documents/tax-summary?from=&to=[&sales_types=invoice&purchase_types=bill]` → `{output:{by_rate:[{rate,base,tax}], total_base, total_tax}, input:{…}, net_tax}` where output = tax on sales docs, input = tax on purchase docs, net_tax = what you owe (output − input). Broken down by rate; draft/cancelled/void excluded. " +
  "FILES: an `<input type=file accept=\"image/*,application/pdf\">`; read the file as a data URL and `POST /api/site/upload {slug, name, data}` (slug = `location.pathname.split('/')[2]`) → `{url}` is a PERMANENT link — ALWAYS save it into a row or it's orphaned. Images/PDF ≤6MB; never upload elsewhere. " +
  "SERVER FUNCTIONS + SECRETS (ONLY for server-side logic the endpoints above can't do: a 3rd-party API with a private key, a PAYMENT, or EMAIL — never hardcode a key). Declare `===FILE: isibi.functions.json===` = `{\"functions\":[{\"name\":\"<kebab>\",\"steps\":[…]}]}`. Each step is ONE of: " +
  "`{\"do\":\"fetch\",\"url\":\"https://…\",\"method\":\"POST\",\"headers\":{…},\"body\":{…},\"as\":\"r\"}` (→ `{{steps.r.status}}`/`{{steps.r.body}}`); `{\"do\":\"ai\",\"prompt\":\"…{{input.x}}…\",\"as\":\"r\"}` (→ `{{steps.r.text}}`); `{\"do\":\"email\",\"provider\":\"resend|sendgrid|postmark\",\"secret\":\"RESEND_KEY\",\"from\":\"you@d.com\",\"to\":\"{{input.email}}\",\"subject\":\"…\",\"html\":\"…\"}`; `{\"do\":\"checkout\",\"secret\":\"STRIPE_KEY\",\"amount\":2999,\"currency\":\"usd\",\"name\":\"…\",\"success_url\":\"…\",\"cancel_url\":\"…\",\"as\":\"s\"}` (cents; add `\"mode\":\"subscription\",\"interval\":\"month\"` for a sub); `{\"do\":\"save\",\"collection\":\"<declared table>\",\"data\":{…}}`; `{\"do\":\"read\",\"collection\":\"<declared table>\",\"limit\":20,\"as\":\"list\"}` (→ `{{steps.list.records}}`); `{\"do\":\"notify\",\"to\":\"{{input.owner_id}}\",\"type\":\"comment\",\"text\":\"Someone replied to your post\",\"link\":\"/post/{{input.post_id}}\"}` (drops an in-app notification into a MEMBER's inbox — `to` is a member id; use inside an on-insert trigger to notify on new comment/like/order); `{\"do\":\"respond\",\"data\":{…}}` (the JSON the browser gets). TEMPLATES: `{{input.x}}` · `{{steps.<as>.<path>}}` · `{{secret.NAME}}` (resolved server-side, injected ONLY into fetch/email/checkout, never sent to the browser). ≤8 steps, ≤2 fetch. " +
  "CALL a function: `POST /api/site/fn {slug, fn:'<name>', input:{…}}` → your respond data (payments: `location.href = d.url`). SECRETS: every `{{secret.NAME}}` (STRIPE_KEY, RESEND_KEY…) is added by the OWNER in Cloud → Secrets — tell them exactly which name(s) to add; never inline a key. EVENT TRIGGER: add `\"on\":{\"insert\":\"<table>\"}` OR `\"on\":{\"update\":\"<table>\"}` (sibling of steps) to run a function automatically after a row is inserted into / updated in that table (new order → email; a deal moved to `won` → log an activity or notify the rep), with the affected row's fields as `{{input.<field>}}` (updates also carry `{{input.id}}`); single-row writes only. Pair `on:{update}` with `transitions` for stage-driven automation (when the stage advances, do X). WEBHOOKS: a function with `\"on\":{\"insert\":\"<table>\"}` + a `fetch` step POSTing to an external URL = an outbound webhook on new rows (new order → notify Slack/Zapier/your server). SMS: a `fetch` step to a provider's REST API (e.g. Twilio) with the account secret. MAGIC-LINK / OTP: an `email` step that sends a code/link (store the code in a table via `save`, verify it in a second function) — same shape as the built-in password-reset. " +
  "Build REAL, working flows (a form that truly saves, a login that truly works, a dashboard of the visitor's own rows, a real checkout). Do NOT invent other backend endpoints — these are the only ones. ";

// Safety-net contract: the model wired the app to the backend API but forgot to
// emit isibi.schema.json (common enough that it can't be optional — a shipped app
// whose login/data silently 404s is a total failure). We ask for JUST the schema,
// inferred from the app's own code, and provision it before publishing.
export const SCHEMA_REPAIR_RULES =
  "A generated React app calls its per-site backend API but FORGOT to declare `isibi.schema.json`, so no database gets created and every `/auth` and `/rows` call fails on the live site. Given the project files, emit ONLY a single `===FILE: isibi.schema.json===` block whose body is the JSON schema — NO other files, NO prose, NO markdown fences. " +
  "Declare EVERY table the app reads or writes via `${API}/rows/<table>` (scan for each distinct `<table>`). Choose each table's access mode from how the code uses it: each logged-in user's OWN private rows (a dashboard, saved items, a personal to-do list) = `user`; a public shared list everyone reads but only a logged-in visitor posts to (board / comments / reviews) = `feed`; a submit-only form only the owner reads (contact / waitlist / orders) = `collect`; owner-managed public content everyone reads (products / menu / posts) = `display`, OR `admin` if the app has an in-app admin screen that creates/edits that content (checks `user.role === 'admin'`). If the app has login (`/auth/signup` or `/auth/login`), its per-user data tables are `user` (or `feed` for shared-but-authored lists). " +
  "Infer each table's columns from the JSON the app POSTs and the fields it renders. NEVER declare `id`, `created_at`, or `owner_id` (the platform adds those). Body format EXACTLY: `{\"tables\":[{\"name\":\"<snake>\",\"access\":\"collect|display|user|feed|admin\",\"columns\":[{\"name\":\"<snake>\",\"type\":\"text|integer|real|boolean|json\"}]}]}`. Output ONLY the isibi.schema.json file block.";

// Auto-fix contract — used when the generated app calls the backend API but wires
// the URL WITHOUT the site slug, so every request 404s on the live site (the app
// compiles fine, so the build loop never catches it — this is a RUNTIME wiring bug).
// The one true base is `/api/db/<slug>/…` where `<slug> = location.pathname.split('/')[2]`;
// the model must re-point EVERY backend call through it.
export const WIRING_REPAIR_RULES =
  "You are a senior React engineer fixing a SHIPPED-BUT-BROKEN backend wiring bug. The app calls its per-site backend API, but the URLs are MISSING the site slug, so every `/auth` and `/rows` request 404s on the live site (the app compiles, so this was never caught). " +
  "THE ONE TRUE BASE: `const API = '/api/db/' + (location.pathname.split('/')[2] || '')` — the site is served at `/s/<slug>/`, so `location.pathname.split('/')[2]` IS the slug. EVERY backend call MUST go through it: `${API}/auth/signup`, `${API}/auth/login`, `${API}/auth/me`, `${API}/rows/<table>`, `${API}/rows/<table>/<id>`, `${API}/rows/<table>/stats`, `${API}/rows/<table>/changes`, plus any `?where=`/`?q=`/`?expand=`/`?children=`/`?sort=` query on `${API}/rows/<table>`. " +
  "Find EVERY fetch/axios call in the project that hits `/api/db…` and rewrite it to include the slug via that `API` base. Fix malformed URLs too (e.g. a query string with no `/rows/<table>?` prefix). Define `API` ONCE (a helper/hook/module) and use it everywhere — do NOT hardcode `/api/db/auth` or `/api/db/rows` or `` `/api/db${x}` `` without the slug. Preserve auth headers (`Authorization: Bearer <token>`), methods, and bodies exactly. " +
  "Return ONLY the CORRECTED file blocks in the SAME format — a line `===FILE: <relative/path>===` on its own line, then the file's raw contents IN FULL (not a diff). Return only the files you change. Change NOTHING about the design, layout, or copy — this is a URL-wiring fix only. Import ONLY from " + REACT_DEPS.join(", ") + ". If (and only if) every backend call already includes the slug, return NO file blocks at all. Output ONLY file blocks — NO prose, NO markdown fences.";

